#[derive(Debug, Subcommand)]
enum RlmCommand {
    /// Slice text into overlapping chunks without invoking an LLM.
    #[command(name = "chunk-text", hide = true)]
    ChunkText {
        /// Input text to slice.
        #[arg(long, value_name = "TEXT")]
        text: String,
        /// Max chunk size in chars.
        #[arg(long, default_value_t = 80000, value_name = "N")]
        size: usize,
        /// Chars of overlap between adjacent chunks.
        #[arg(long, default_value_t = 0, value_name = "N")]
        overlap: usize,
    },
    /// Read files and pack their contents into stitched chunks.
    #[command(name = "chunk-files", hide = true)]
    ChunkFiles {
        /// File path to include. Repeat for multiple files.
        #[arg(long = "path", value_name = "PATH", action = ArgAction::Append)]
        paths: Vec<PathBuf>,
        /// Max files per chunk.
        #[arg(long = "group-size", default_value_t = 5, value_name = "N")]
        group_size: usize,
        /// Max cumulative content bytes per chunk.
        #[arg(long = "max-bytes", default_value_t = 200000, value_name = "N")]
        max_bytes: usize,
        /// Separator between files within a chunk.
        #[arg(long, default_value = "\n\n---\n\n", value_name = "TEXT")]
        separator: String,
    },
    /// Parse map-step result strings with JSON/EDN fallback.
    #[command(name = "parse-map-results", hide = true)]
    ParseMapResults {
        /// Result string to parse. Repeat for multiple results.
        #[arg(long = "result", value_name = "TEXT", action = ArgAction::Append)]
        results: Vec<String>,
        /// Tier-1 parser: json or edn.
        #[arg(long, default_value = "json", value_name = "SHAPE")]
        shape: String,
        /// Split each result by newline before parsing.
        #[arg(long = "per-line", action = ArgAction::SetTrue)]
        per_line: bool,
    },
    /// Aggregate parsed map rows by key.
    #[command(name = "reduce-counts", hide = true)]
    ReduceCounts {
        /// Parsed rows as a JSON or EDN vector.
        #[arg(long = "parsed-results", value_name = "JSON_OR_EDN")]
        parsed_results: String,
        /// Group-by key.
        #[arg(long, default_value = "category", value_name = "KEY")]
        key: String,
        /// Per-row count key.
        #[arg(long = "count-key", default_value = "count", value_name = "KEY")]
        count_key: String,
    },
    /// Conservative boolean verdict aggregation over parsed rows.
    #[command(name = "conservative-verdict", hide = true)]
    ConservativeVerdict {
        /// Parsed rows as a JSON or EDN vector.
        #[arg(long = "parsed-results", value_name = "JSON_OR_EDN")]
        parsed_results: String,
        /// Boolean field that flips the verdict when any row is true.
        #[arg(
            long = "positive-key",
            default_value = "malicious?",
            value_name = "KEY"
        )]
        positive_key: String,
    },
    /// Build one trajectory entry from an RLM iteration without persistence.
    #[command(name = "trajectory-entry", hide = true)]
    TrajectoryEntry {
        /// Iteration number.
        #[arg(long, value_name = "N")]
        iteration: i64,
        /// Eval results as a JSON or EDN vector.
        #[arg(long = "eval-results", value_name = "JSON_OR_EDN")]
        eval_results: Option<String>,
        /// Optional iteration error.
        #[arg(long, value_name = "TEXT")]
        error: Option<String>,
        /// Optional raw LLM response text for reasoning extraction.
        #[arg(long = "response-text", value_name = "TEXT")]
        response_text: Option<String>,
    },
    /// Build a complete trajectory export from a completed RLM result.
    #[command(name = "trajectory-build", hide = true)]
    TrajectoryBuild {
        /// User query.
        #[arg(long, value_name = "TEXT")]
        question: String,
        /// RLM completion result as JSON or EDN.
        #[arg(long, value_name = "JSON_OR_EDN")]
        result: String,
        /// Model identifier.
        #[arg(long, value_name = "MODEL")]
        model: Option<String>,
        /// Usage tracker summary as JSON or EDN.
        #[arg(long = "usage-summary", value_name = "JSON_OR_EDN")]
        usage_summary: Option<String>,
        /// Agent identifier.
        #[arg(long = "agent-id", value_name = "ID")]
        agent_id: Option<String>,
        /// Session identifier.
        #[arg(long = "session-id", value_name = "ID")]
        session_id: Option<String>,
        /// Recursion depth.
        #[arg(long, value_name = "N")]
        depth: Option<i64>,
        /// Context key present in the RLM context. Repeat for multiple keys.
        #[arg(long = "context-key", value_name = "KEY", action = ArgAction::Append)]
        context_keys: Vec<String>,
        /// Start timestamp in epoch milliseconds.
        #[arg(long = "started-at", value_name = "MS")]
        started_at: Option<i64>,
        /// End timestamp in epoch milliseconds. Defaults to current time when started-at is set.
        #[arg(long = "ended-at", value_name = "MS")]
        ended_at: Option<i64>,
    },
    /// Create a lightweight trajectory summary.
    #[command(name = "trajectory-summary", hide = true)]
    TrajectorySummary {
        /// Trajectory as JSON or EDN.
        #[arg(long, value_name = "JSON_OR_EDN")]
        trajectory: String,
    },
    /// Select training-data export fields from a trajectory.
    #[command(name = "trajectory-format-export", hide = true)]
    TrajectoryFormatExport {
        /// Trajectory as JSON or EDN.
        #[arg(long, value_name = "JSON_OR_EDN")]
        trajectory: String,
    },
}

