#[derive(Debug)]
struct AskRequest {
    agent: String,
    provider: String,
    model: Option<String>,
    max_iterations: Option<usize>,
    user_id: Option<String>,
    region: Option<String>,
    aws_profile: Option<String>,
    temperature: f64,
    max_tokens: Option<u32>,
    no_prompt_cache: bool,
    dry_run: bool,
    live: bool,
    fixture_response: Option<PathBuf>,
    question: Vec<String>,
}

#[derive(Debug)]
struct RunOneTurnRequest {
    agent: String,
    provider: String,
    model: Option<String>,
    max_iterations: Option<usize>,
    user_id: Option<String>,
    region: Option<String>,
    aws_profile: Option<String>,
    max_tokens: Option<u32>,
    no_prompt_cache: bool,
    dry_run: bool,
    live: bool,
    fixture_response: Option<PathBuf>,
    question: Vec<String>,
    session_selection: RunSessionSelection,
}

struct RunInteractiveRequest {
    agent: String,
    provider: String,
    model: Option<String>,
    max_iterations: Option<usize>,
    user_id: Option<String>,
    region: Option<String>,
    aws_profile: Option<String>,
    max_tokens: Option<u32>,
    no_prompt_cache: bool,
    session_selection: RunSessionSelection,
}

fn run_one_turn_mode_requested(
    dry_run: bool,
    live: bool,
    fixture_response: Option<&PathBuf>,
) -> bool {
    dry_run || live || fixture_response.is_some()
}

fn print_run_one_turn(args: RunOneTurnRequest) -> Result<()> {
    validate_run_one_turn_modes(args.dry_run, args.live, args.fixture_response.as_ref())?;
    let (provider, model, question) =
        resolve_run_one_turn_positionals(args.provider, args.model, args.question);
    let question = question.context(
        "by-rs run one-turn mode requires a prompt when --dry-run, --live, or --fixture-response is used",
    )?;

    let default_config = read_default_config()?;
    let llm_config = default_config.as_ref().map(by_config::ConfigDocument::llm);
    let agent_config = default_config
        .as_ref()
        .map(by_config::ConfigDocument::agent);
    let resolved_agent = resolve_ask_agent(
        args.agent,
        agent_config
            .as_ref()
            .and_then(|config| config.default_agent.as_deref()),
    );
    let resolved_max_iterations = resolve_ask_max_iterations(&resolved_agent, args.max_iterations)?;
    let resolved_provider = match provider.as_str() {
        "claude-code" => llm_config
            .as_ref()
            .and_then(|config| config.default_provider.clone())
            .unwrap_or(provider),
        _ => provider,
    };
    let model = model
        .or_else(|| {
            llm_config
                .as_ref()
                .and_then(|config| config.default_model.clone())
        })
        .context("--model is required for run one-turn mode")?;

    if args.live && resolved_provider != "bedrock" {
        bail!("by-rs run live one-turn currently supports provider 'bedrock' only");
    }

    let messages = run_one_turn_messages(&args.session_selection, &question)?;
    let dotenv = by_config::load_process_dotenv()?;

    let session_selection = prepare_run_session(
        args.session_selection,
        &resolved_agent,
        args.user_id.as_deref(),
    )?;
    let session_id = session_selection
        .session_id
        .as_deref()
        .context("run session was not prepared")?
        .to_string();

    if let Some(path) = args.fixture_response {
        let raw: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&path)
                .with_context(|| format!("failed to read response fixture {}", path.display()))?,
        )
        .with_context(|| format!("failed to parse response fixture {}", path.display()))?;
        let projected = by_llm::reshape_provider_response(&resolved_provider, raw)?;
        let text = by_llm::projected_response_text(&projected);
        let assistant_content = if text.is_empty() {
            serde_json::to_string_pretty(&projected)?
        } else {
            text
        };
        persist_run_result(
            &session_id,
            &resolved_agent,
            &model,
            &question,
            &assistant_content,
            &projected,
        )?;
        println!("{assistant_content}");
        return Ok(());
    }

    if args.dry_run {
        let user_id =
            by_config::resolve_process_user_id_with_dotenv(args.user_id.as_deref(), &dotenv);
        if resolved_provider != "bedrock" {
            let config = by_llm::ProviderChatConfig {
                model: model.clone(),
                temperature: Some(0.0),
                max_tokens: args.max_tokens,
                drop_temperature: by_llm::bedrock_drops_temperature(&model),
            };
            let projection =
                by_llm::build_provider_request(&resolved_provider, &config, &messages)?;
            let dry_run = serde_json::json!({
                "provider": resolved_provider,
                "operation": projection.operation,
                "network": false,
                "session_id": session_id,
                "resume": session_selection.resume,
                "agent_session": ask_agent_session(&resolved_agent, user_id, resolved_max_iterations),
                "request": projection.request,
            });
            println!("{}", serde_json::to_string_pretty(&dry_run)?);
            return Ok(());
        }

        let catalog_region = bedrock_catalog_region(&model)?;
        let runtime = by_llm::resolve_bedrock_runtime_options(by_llm::BedrockRuntimeInputs {
            explicit_region: args.region,
            catalog_region,
            aws_region: by_config::process_env_or_dotenv(&dotenv, "AWS_REGION"),
            aws_default_region: by_config::process_env_or_dotenv(&dotenv, "AWS_DEFAULT_REGION"),
            explicit_profile: args.aws_profile,
            aws_profile: by_config::process_env_or_dotenv(&dotenv, "AWS_PROFILE"),
            aws_default_profile: by_config::process_env_or_dotenv(&dotenv, "AWS_DEFAULT_PROFILE"),
        });
        let config = by_llm::BedrockConfig {
            model: model.clone(),
            temperature: Some(0.0),
            max_tokens: args.max_tokens,
            prompt_cache: !args.no_prompt_cache && by_llm::bedrock_supports_prompt_cache(&model),
            drop_temperature: by_llm::bedrock_drops_temperature(&model),
        };
        let request = by_llm::build_bedrock_request(&config, &messages);
        let dry_run = serde_json::json!({
            "provider": "bedrock",
            "operation": "Converse",
            "network": false,
            "session_id": session_id,
            "resume": session_selection.resume,
            "agent_session": ask_agent_session(&resolved_agent, user_id, resolved_max_iterations),
            "region": runtime.region,
            "aws_profile": runtime.aws_profile,
            "request": request,
        });
        println!("{}", serde_json::to_string_pretty(&dry_run)?);
        return Ok(());
    }

    let catalog_region = bedrock_catalog_region(&model)?;
    let runtime = by_llm::resolve_bedrock_runtime_options(by_llm::BedrockRuntimeInputs {
        explicit_region: args.region,
        catalog_region,
        aws_region: by_config::process_env_or_dotenv(&dotenv, "AWS_REGION"),
        aws_default_region: by_config::process_env_or_dotenv(&dotenv, "AWS_DEFAULT_REGION"),
        explicit_profile: args.aws_profile,
        aws_profile: by_config::process_env_or_dotenv(&dotenv, "AWS_PROFILE"),
        aws_default_profile: by_config::process_env_or_dotenv(&dotenv, "AWS_DEFAULT_PROFILE"),
    });
    let config = by_llm::BedrockConfig {
        model: model.clone(),
        temperature: Some(0.0),
        max_tokens: args.max_tokens,
        prompt_cache: !args.no_prompt_cache && by_llm::bedrock_supports_prompt_cache(&model),
        drop_temperature: by_llm::bedrock_drops_temperature(&model),
    };
    let response = tokio::runtime::Runtime::new()
        .context("failed to create Tokio runtime for Bedrock live call")?
        .block_on(by_llm::converse_bedrock(by_llm::BedrockConverseRequest {
            config,
            runtime,
            messages,
            cache_zones: Vec::new(),
        }))?;
    let by_llm::BedrockConverseResponse {
        projected, text, ..
    } = response;
    let assistant_content = if text.is_empty() {
        serde_json::to_string_pretty(&projected)?
    } else {
        text
    };
    persist_run_result(
        &session_id,
        &resolved_agent,
        &model,
        &question,
        &assistant_content,
        &projected,
    )?;
    println!("{assistant_content}");
    Ok(())
}

fn validate_run_one_turn_modes(
    dry_run: bool,
    live: bool,
    fixture_response: Option<&PathBuf>,
) -> Result<()> {
    if dry_run && live {
        bail!("choose only one of --dry-run or --live");
    }
    if fixture_response.is_some() && (dry_run || live) {
        bail!("choose only one of --dry-run, --live, or --fixture-response");
    }
    if !dry_run && !live && fixture_response.is_none() {
        bail!("by-rs run one-turn mode requires --dry-run, --live, or --fixture-response");
    }
    Ok(())
}

fn resolve_run_one_turn_positionals(
    provider: String,
    model: Option<String>,
    mut positionals: Vec<String>,
) -> (String, Option<String>, Option<String>) {
    let (provider, model) = match take_legacy_provider_model(&mut positionals) {
        Some((legacy_provider, legacy_model)) => (legacy_provider, Some(legacy_model)),
        None => (provider, model),
    };
    let joined = positionals.join(" ");
    let trimmed = joined.trim();
    let question = (!trimmed.is_empty()).then(|| trimmed.to_string());
    (provider, model, question)
}

fn persist_run_result(
    session_id: &str,
    agent: &str,
    model: &str,
    question: &str,
    answer: &str,
    projected: &serde_json::Value,
) -> Result<()> {
    let root = default_sessions_root().context("could not determine default session root")?;
    let lock = acquire_session_write_lock(&root, session_id)?;
    by_persist::append_session_message(&root, session_id, "user", question)?;
    by_persist::append_session_message(&root, session_id, "assistant", answer)?;
    persist_run_snapshots(&root, session_id, agent, model, question, projected)?;
    lock.release()?;
    Ok(())
}

struct SessionWriteLock(Option<by_persist::SessionLock>);

impl SessionWriteLock {
    fn release(mut self) -> Result<()> {
        if let Some(lock) = self.0.take() {
            by_persist::release_session_lock(lock)?;
        }
        Ok(())
    }
}

impl Drop for SessionWriteLock {
    fn drop(&mut self) {
        if let Some(lock) = self.0.take() {
            let _ = by_persist::release_session_lock(lock);
        }
    }
}

fn acquire_session_write_lock(root: &Path, session_id: &str) -> Result<SessionWriteLock> {
    let lock = by_persist::try_acquire_session_lock(root, session_id)?
        .with_context(|| format!("Session is locked by another process: {session_id}"))
        .map(Some)
        .map(SessionWriteLock)?;
    Ok(lock)
}

fn persist_run_snapshots(
    root: &Path,
    session_id: &str,
    agent: &str,
    model: &str,
    question: &str,
    projected: &serde_json::Value,
) -> Result<()> {
    let restored = by_persist::restore_session(root, session_id).ok();
    let messages = match &restored {
        Some(restored) => restored.messages.clone(),
        None => by_persist::read_session_messages(root, session_id)?,
    };
    let usage_tracker = restored
        .as_ref()
        .and_then(|restored| restored.usage_tracker.as_ref())
        .cloned()
        .or_else(|| {
            by_persist::read_session_snapshot(
                root,
                session_id,
                by_persist::SessionSnapshotKind::UsageTracker,
            )
            .ok()
            .flatten()
        });

    let now_millis = current_epoch_millis().context("could not determine current time")?;
    let user_id = restored
        .as_ref()
        .and_then(|restored| restored.user_id.clone())
        .unwrap_or_else(resolve_default_user_id);
    let agent_id = restored
        .as_ref()
        .and_then(|restored| restored.agent.clone())
        .unwrap_or_else(|| agent.to_string());
    let total_turns = i64::try_from(
        messages
            .iter()
            .filter(|message| message.role == "user")
            .count(),
    )
    .unwrap_or(i64::MAX);
    let agent_activity_seq = restored
        .as_ref()
        .and_then(|restored| restored.agent_activity_seq)
        .unwrap_or_else(|| total_turns.saturating_sub(1))
        .saturating_add(1);
    let session_snapshot = run_session_snapshot_value(
        session_id,
        &user_id,
        &agent_id,
        total_turns,
        agent_activity_seq,
        now_millis,
    );
    by_persist::write_session_snapshot(
        root,
        session_id,
        by_persist::SessionSnapshotKind::Session,
        &session_snapshot,
    )?;

    let usage_snapshot = run_usage_tracker_snapshot_value(model, projected, usage_tracker.as_ref());
    by_persist::write_session_snapshot(
        root,
        session_id,
        by_persist::SessionSnapshotKind::UsageTracker,
        &usage_snapshot,
    )?;

    let input_history = run_input_history_snapshot_value(root, session_id, question);
    by_persist::write_session_snapshot(
        root,
        session_id,
        by_persist::SessionSnapshotKind::InputHistory,
        &input_history,
    )?;
    Ok(())
}

fn run_session_snapshot_value(
    session_id: &str,
    user_id: &str,
    agent_id: &str,
    total_turns: i64,
    agent_activity_seq: i64,
    updated_at_millis: i64,
) -> by_contracts::EdnValue {
    let mut entries = BTreeMap::new();
    entries.insert(
        "agent-activity-seq".to_string(),
        by_contracts::EdnValue::Integer(agent_activity_seq),
    );
    entries.insert(
        "agent-id".to_string(),
        by_contracts::EdnValue::Keyword(agent_id.to_string()),
    );
    entries.insert(
        "agent-session-id".to_string(),
        by_contracts::EdnValue::String(session_id.to_string()),
    );
    entries.insert(
        "defagent-id".to_string(),
        by_contracts::EdnValue::Keyword(agent_id.to_string()),
    );
    entries.insert(
        "total-turns".to_string(),
        by_contracts::EdnValue::Integer(total_turns),
    );
    entries.insert(
        "updated-at".to_string(),
        by_contracts::EdnValue::Integer(updated_at_millis),
    );
    entries.insert(
        "user-id".to_string(),
        by_contracts::EdnValue::String(user_id.to_string()),
    );
    by_contracts::EdnValue::Map(by_contracts::EdnMap::new(entries))
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
struct RunUsageTotals {
    input_tokens: i64,
    output_tokens: i64,
    total_tokens: i64,
    cache_read_tokens: i64,
    cache_write_tokens: i64,
    total_cost: f64,
    call_count: i64,
}

impl RunUsageTotals {
    fn plus(self, other: Self) -> Self {
        Self {
            input_tokens: self.input_tokens.saturating_add(other.input_tokens),
            output_tokens: self.output_tokens.saturating_add(other.output_tokens),
            total_tokens: self.total_tokens.saturating_add(other.total_tokens),
            cache_read_tokens: self
                .cache_read_tokens
                .saturating_add(other.cache_read_tokens),
            cache_write_tokens: self
                .cache_write_tokens
                .saturating_add(other.cache_write_tokens),
            total_cost: self.total_cost + other.total_cost,
            call_count: self.call_count.saturating_add(other.call_count),
        }
    }
}

fn run_usage_tracker_snapshot_value(
    model: &str,
    projected: &serde_json::Value,
    existing: Option<&by_contracts::EdnValue>,
) -> by_contracts::EdnValue {
    let current = usage_totals_from_projected(projected);
    let totals = usage_totals_from_tracker(existing).plus(current);
    let model_totals = usage_model_totals_from_tracker(existing, model).plus(current);
    let history_cap = usage_history_cap_from_tracker(existing);
    let history_entry = by_contracts::EdnValue::MapEntries(vec![
        (
            by_contracts::EdnValue::Keyword("model".to_string()),
            by_contracts::EdnValue::String(model.to_string()),
        ),
        (
            by_contracts::EdnValue::Keyword("input-tokens".to_string()),
            by_contracts::EdnValue::Integer(current.input_tokens),
        ),
        (
            by_contracts::EdnValue::Keyword("output-tokens".to_string()),
            by_contracts::EdnValue::Integer(current.output_tokens),
        ),
        (
            by_contracts::EdnValue::Keyword("total-tokens".to_string()),
            by_contracts::EdnValue::Integer(current.total_tokens),
        ),
        (
            by_contracts::EdnValue::Keyword("cache-read-tokens".to_string()),
            by_contracts::EdnValue::Integer(current.cache_read_tokens),
        ),
        (
            by_contracts::EdnValue::Keyword("cache-write-tokens".to_string()),
            by_contracts::EdnValue::Integer(current.cache_write_tokens),
        ),
        (
            by_contracts::EdnValue::Keyword("total-cost".to_string()),
            by_contracts::EdnValue::Float(current.total_cost),
        ),
    ]);
    let mut history = usage_history_from_tracker(existing);
    history.push(history_entry);
    if history_cap > 0 {
        let history_cap = usize::try_from(history_cap).unwrap_or(usize::MAX);
        if history.len() > history_cap {
            history.drain(0..history.len() - history_cap);
        }
    }

    by_contracts::EdnValue::MapEntries(vec![
        (
            by_contracts::EdnValue::Keyword("totals".to_string()),
            usage_totals_edn_value(totals),
        ),
        (
            by_contracts::EdnValue::Keyword("by-model".to_string()),
            by_contracts::EdnValue::MapEntries(usage_by_model_entries_from_tracker(
                existing,
                model,
                model_totals,
            )),
        ),
        (
            by_contracts::EdnValue::Keyword("history".to_string()),
            by_contracts::EdnValue::Vector(history),
        ),
        (
            by_contracts::EdnValue::Keyword("history-cap".to_string()),
            by_contracts::EdnValue::Integer(history_cap),
        ),
    ])
}

fn run_input_history_snapshot_value(
    root: &Path,
    session_id: &str,
    question: &str,
) -> by_contracts::EdnValue {
    let mut history = match by_persist::read_session_snapshot(
        root,
        session_id,
        by_persist::SessionSnapshotKind::InputHistory,
    ) {
        Ok(Some(by_contracts::EdnValue::Vector(values))) => values
            .into_iter()
            .filter(|value| matches!(value, by_contracts::EdnValue::String(_)))
            .collect(),
        _ => Vec::new(),
    };
    history.push(by_contracts::EdnValue::String(question.to_string()));
    by_contracts::EdnValue::Vector(history)
}

fn usage_totals_from_projected(projected: &serde_json::Value) -> RunUsageTotals {
    let input_tokens = projected_usage_i64(projected, "input_tokens");
    let output_tokens = projected_usage_i64(projected, "output_tokens");
    let total_tokens = match projected_usage_i64(projected, "total_tokens") {
        0 => input_tokens.saturating_add(output_tokens),
        total_tokens => total_tokens,
    };
    RunUsageTotals {
        input_tokens,
        output_tokens,
        total_tokens,
        cache_read_tokens: projected_usage_i64(projected, "cache_read_input_tokens"),
        cache_write_tokens: projected_usage_i64(projected, "cache_creation_input_tokens"),
        total_cost: 0.0,
        call_count: 1,
    }
}

fn projected_usage_i64(projected: &serde_json::Value, key: &str) -> i64 {
    projected
        .get("usage")
        .and_then(|usage| usage.get(key))
        .and_then(serde_json::Value::as_i64)
        .unwrap_or(0)
}

fn usage_totals_from_tracker(existing: Option<&by_contracts::EdnValue>) -> RunUsageTotals {
    let Some(by_contracts::EdnValue::Map(map)) = existing else {
        return RunUsageTotals::default();
    };
    match map.get("totals") {
        Some(by_contracts::EdnValue::Map(totals)) => usage_totals_from_edn_map(totals),
        _ => RunUsageTotals::default(),
    }
}

fn usage_model_totals_from_tracker(
    existing: Option<&by_contracts::EdnValue>,
    model: &str,
) -> RunUsageTotals {
    let Some(by_contracts::EdnValue::Map(map)) = existing else {
        return RunUsageTotals::default();
    };
    let Some(by_contracts::EdnValue::Map(by_model)) = map.get("by-model") else {
        return RunUsageTotals::default();
    };
    match by_model.get(model) {
        Some(by_contracts::EdnValue::Map(totals)) => usage_totals_from_edn_map(totals),
        _ => RunUsageTotals::default(),
    }
}

fn usage_by_model_entries_from_tracker(
    existing: Option<&by_contracts::EdnValue>,
    model: &str,
    model_totals: RunUsageTotals,
) -> Vec<(by_contracts::EdnValue, by_contracts::EdnValue)> {
    let mut entries = BTreeMap::new();
    if let Some(by_contracts::EdnValue::Map(map)) = existing {
        if let Some(by_contracts::EdnValue::Map(by_model)) = map.get("by-model") {
            for (key, value) in by_model.iter() {
                if key != model {
                    entries.insert(key.clone(), value.clone());
                }
            }
        }
    }
    entries.insert(model.to_string(), usage_totals_edn_value(model_totals));
    entries
        .into_iter()
        .map(|(key, value)| (by_contracts::EdnValue::String(key), value))
        .collect()
}

fn usage_history_from_tracker(
    existing: Option<&by_contracts::EdnValue>,
) -> Vec<by_contracts::EdnValue> {
    let Some(by_contracts::EdnValue::Map(map)) = existing else {
        return Vec::new();
    };
    match map.get("history") {
        Some(by_contracts::EdnValue::Vector(history)) => history.clone(),
        _ => Vec::new(),
    }
}

fn usage_history_cap_from_tracker(existing: Option<&by_contracts::EdnValue>) -> i64 {
    const DEFAULT_HISTORY_CAP: i64 = 1000;
    let Some(by_contracts::EdnValue::Map(map)) = existing else {
        return DEFAULT_HISTORY_CAP;
    };
    match map.get("history-cap") {
        Some(by_contracts::EdnValue::Integer(value)) if *value > 0 => *value,
        _ => DEFAULT_HISTORY_CAP,
    }
}

fn usage_totals_from_edn_map(map: &by_contracts::EdnMap) -> RunUsageTotals {
    RunUsageTotals {
        input_tokens: edn_map_i64(map, "input-tokens"),
        output_tokens: edn_map_i64(map, "output-tokens"),
        total_tokens: edn_map_i64(map, "total-tokens"),
        cache_read_tokens: edn_map_i64(map, "cache-read-tokens"),
        cache_write_tokens: edn_map_i64(map, "cache-write-tokens"),
        total_cost: edn_map_f64(map, "total-cost"),
        call_count: edn_map_i64(map, "call-count"),
    }
}

fn usage_totals_edn_value(totals: RunUsageTotals) -> by_contracts::EdnValue {
    let mut entries = BTreeMap::new();
    entries.insert(
        "cache-read-tokens".to_string(),
        by_contracts::EdnValue::Integer(totals.cache_read_tokens),
    );
    entries.insert(
        "cache-write-tokens".to_string(),
        by_contracts::EdnValue::Integer(totals.cache_write_tokens),
    );
    entries.insert(
        "call-count".to_string(),
        by_contracts::EdnValue::Integer(totals.call_count),
    );
    entries.insert(
        "input-tokens".to_string(),
        by_contracts::EdnValue::Integer(totals.input_tokens),
    );
    entries.insert(
        "output-tokens".to_string(),
        by_contracts::EdnValue::Integer(totals.output_tokens),
    );
    entries.insert(
        "total-cost".to_string(),
        by_contracts::EdnValue::Float(totals.total_cost),
    );
    entries.insert(
        "total-tokens".to_string(),
        by_contracts::EdnValue::Integer(totals.total_tokens),
    );
    by_contracts::EdnValue::Map(by_contracts::EdnMap::new(entries))
}

fn edn_map_i64(map: &by_contracts::EdnMap, key: &str) -> i64 {
    match map.get(key) {
        Some(by_contracts::EdnValue::Integer(value)) => *value,
        _ => 0,
    }
}

fn edn_map_f64(map: &by_contracts::EdnMap, key: &str) -> f64 {
    match map.get(key) {
        Some(by_contracts::EdnValue::Float(value)) => *value,
        Some(by_contracts::EdnValue::Integer(value)) => *value as f64,
        _ => 0.0,
    }
}

fn resolve_default_user_id() -> String {
    let dotenv = by_config::load_process_dotenv().unwrap_or_default();
    by_config::resolve_process_user_id_with_dotenv(None, &dotenv)
}

fn run_one_turn_messages(
    selection: &RunSessionSelection,
    question: &str,
) -> Result<Vec<by_llm::ChatMessage>> {
    let mut messages = Vec::new();
    if selection.resume {
        let root = default_sessions_root().context("could not determine default session root")?;
        let session_id = selection
            .session_id
            .as_deref()
            .context("run resume session was not selected")?;
        messages.extend(
            by_persist::read_session_messages(&root, session_id)?
                .into_iter()
                .filter_map(persisted_message_to_chat_message),
        );
    }
    messages.push(by_llm::ChatMessage::user(question.to_string()));
    Ok(messages)
}

fn persisted_message_to_chat_message(
    message: by_persist::SessionMessage,
) -> Option<by_llm::ChatMessage> {
    match message.role.as_str() {
        "assistant" => Some(by_llm::ChatMessage::assistant(message.content)),
        "system" => Some(by_llm::ChatMessage::system(message.content)),
        "user" => Some(by_llm::ChatMessage::user(message.content)),
        _ => None,
    }
}

fn print_ask(args: AskRequest) -> Result<()> {
    let (provider, model, question) =
        resolve_ask_positionals(args.provider, args.model, args.question);
    let Some(question) = question.filter(|question| !question.trim().is_empty()) else {
        print_missing_ask_question_and_exit();
    };

    if args.dry_run && args.live {
        bail!("choose only one of --dry-run or --live");
    }
    if args.fixture_response.is_some() && (args.dry_run || args.live) {
        bail!("choose only one of --dry-run, --live, or --fixture-response");
    }
    if !args.dry_run && !args.live && args.fixture_response.is_none() {
        bail!("by-rs ask requires --dry-run or --live");
    }

    let default_config = read_default_config()?;
    let llm_config = default_config.as_ref().map(by_config::ConfigDocument::llm);
    let agent_config = default_config
        .as_ref()
        .map(by_config::ConfigDocument::agent);
    let resolved_agent = resolve_ask_agent(
        args.agent,
        agent_config
            .as_ref()
            .and_then(|config| config.default_agent.as_deref()),
    );
    let resolved_max_iterations = resolve_ask_max_iterations(&resolved_agent, args.max_iterations)?;
    let resolved_provider = match provider.as_str() {
        "claude-code" => llm_config
            .as_ref()
            .and_then(|config| config.default_provider.clone())
            .unwrap_or(provider),
        _ => provider,
    };
    let model = model
        .or_else(|| {
            llm_config
                .as_ref()
                .and_then(|config| config.default_model.clone())
        })
        .context("--model is required for ask")?;

    if let Some(path) = args.fixture_response {
        let raw: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(&path)
                .with_context(|| format!("failed to read response fixture {}", path.display()))?,
        )
        .with_context(|| format!("failed to parse response fixture {}", path.display()))?;
        let projected = by_llm::reshape_provider_response(&resolved_provider, raw)?;
        let text = by_llm::projected_response_text(&projected);
        if text.is_empty() {
            println!("{}", serde_json::to_string_pretty(&projected)?);
        } else {
            println!("{text}");
        }
        return Ok(());
    }

    let messages = vec![by_llm::ChatMessage::user(question)];
    let dotenv = by_config::load_process_dotenv()?;

    if args.dry_run && resolved_provider != "bedrock" {
        let drop_temperature = by_llm::bedrock_drops_temperature(&model);
        let config = by_llm::ProviderChatConfig {
            model,
            temperature: Some(args.temperature),
            max_tokens: args.max_tokens,
            drop_temperature,
        };
        let projection = by_llm::build_provider_request(&resolved_provider, &config, &messages)?;
        let user_id =
            by_config::resolve_process_user_id_with_dotenv(args.user_id.as_deref(), &dotenv);
        let dry_run = serde_json::json!({
            "provider": resolved_provider,
            "operation": projection.operation,
            "network": false,
            "agent_session": ask_agent_session(&resolved_agent, user_id, resolved_max_iterations),
            "request": projection.request,
        });
        println!("{}", serde_json::to_string_pretty(&dry_run)?);
        return Ok(());
    }

    if resolved_provider != "bedrock" {
        bail!("by-rs ask currently supports provider 'bedrock' only");
    }

    let catalog_region = bedrock_catalog_region(&model)?;
    let runtime = by_llm::resolve_bedrock_runtime_options(by_llm::BedrockRuntimeInputs {
        explicit_region: args.region,
        catalog_region,
        aws_region: by_config::process_env_or_dotenv(&dotenv, "AWS_REGION"),
        aws_default_region: by_config::process_env_or_dotenv(&dotenv, "AWS_DEFAULT_REGION"),
        explicit_profile: args.aws_profile,
        aws_profile: by_config::process_env_or_dotenv(&dotenv, "AWS_PROFILE"),
        aws_default_profile: by_config::process_env_or_dotenv(&dotenv, "AWS_DEFAULT_PROFILE"),
    });

    let config = by_llm::BedrockConfig {
        model: model.clone(),
        temperature: Some(args.temperature),
        max_tokens: args.max_tokens,
        prompt_cache: !args.no_prompt_cache && by_llm::bedrock_supports_prompt_cache(&model),
        drop_temperature: by_llm::bedrock_drops_temperature(&model),
    };

    if args.dry_run {
        let request = by_llm::build_bedrock_request(&config, &messages);
        let user_id =
            by_config::resolve_process_user_id_with_dotenv(args.user_id.as_deref(), &dotenv);
        let dry_run = serde_json::json!({
            "provider": "bedrock",
            "operation": "Converse",
            "network": false,
            "agent_session": ask_agent_session(&resolved_agent, user_id, resolved_max_iterations),
            "region": runtime.region,
            "aws_profile": runtime.aws_profile,
            "request": request,
        });
        println!("{}", serde_json::to_string_pretty(&dry_run)?);
        return Ok(());
    }

    let response = tokio::runtime::Runtime::new()
        .context("failed to create Tokio runtime for Bedrock live call")?
        .block_on(by_llm::converse_bedrock(by_llm::BedrockConverseRequest {
            config,
            runtime,
            messages,
            cache_zones: Vec::new(),
        }))?;

    if response.text.is_empty() {
        println!("{}", serde_json::to_string_pretty(&response.projected)?);
    } else {
        println!("{}", response.text);
    }
    Ok(())
}

fn resolve_ask_max_iterations(
    agent_id: &str,
    cli_max_iterations: Option<usize>,
) -> Result<Option<usize>> {
    if cli_max_iterations.is_some() {
        return Ok(cli_max_iterations);
    }

    Ok(by_registry::load_embedded_oracle_registry()?
        .agents
        .into_iter()
        .find(|agent| agent.id == agent_id)
        .and_then(|agent| agent.max_iterations)
        .or(Some(by_config::DEFAULT_AGENT_MAX_ITERATIONS)))
}

fn resolve_ask_agent(cli_agent: String, config_default_agent: Option<&str>) -> String {
    if cli_agent != "coact-agent" && !cli_agent.trim().is_empty() {
        return cli_agent;
    }

    config_default_agent
        .filter(|agent| !agent.trim().is_empty())
        .map(ToOwned::to_owned)
        .unwrap_or(cli_agent)
}

fn ask_agent_session(
    agent_id: &str,
    user_id: String,
    max_iterations: Option<usize>,
) -> serde_json::Value {
    let mut session = serde_json::Map::new();
    session.insert("agent_id".to_string(), serde_json::json!(agent_id));
    session.insert("user_id".to_string(), serde_json::json!(user_id));
    if let Some(max_iterations) = max_iterations {
        session.insert(
            "max_iterations".to_string(),
            serde_json::json!(max_iterations),
        );
    }
    serde_json::Value::Object(session)
}

fn print_missing_ask_question_and_exit() -> ! {
    println!("Error: question argument is required.");
    println!("Usage: by ask [options] QUESTION");
    std::process::exit(1);
}

fn bedrock_catalog_region(model: &str) -> Result<Option<String>> {
    Ok(by_registry::load_embedded_oracle_registry()?
        .models
        .into_iter()
        .find(|entry| entry.provider == "bedrock" && entry.id == model)
        .and_then(|entry| entry.region))
}

fn resolve_ask_positionals(
    provider: String,
    model: Option<String>,
    mut positionals: Vec<String>,
) -> (String, Option<String>, Option<String>) {
    let (provider, model) = match take_legacy_provider_model(&mut positionals) {
        Some((legacy_provider, legacy_model)) => (legacy_provider, Some(legacy_model)),
        None => (provider, model),
    };
    let question = positionals.into_iter().next();
    (provider, model, question)
}

fn take_legacy_provider_model(positionals: &mut Vec<String>) -> Option<(String, String)> {
    let index = positionals
        .iter()
        .position(|value| legacy_provider_model(value))?;
    let token = positionals.remove(index);
    let (provider, model) = token.split_once(':')?;
    Some((provider.to_string(), model.to_string()))
}

fn legacy_provider_model(value: &str) -> bool {
    let Some((provider, model)) = value.split_once(':') else {
        return false;
    };
    if model.contains(':') {
        return false;
    }

    provider_token(provider) && model_token(model)
}

fn provider_token(value: &str) -> bool {
    let mut chars = value.chars();
    matches!(chars.next(), Some(ch) if ch.is_ascii_lowercase())
        && chars.all(provider_or_model_rest_char)
}

fn model_token(value: &str) -> bool {
    let mut chars = value.chars();
    matches!(chars.next(), Some(ch) if ch.is_ascii_lowercase() || ch.is_ascii_digit())
        && chars.all(provider_or_model_rest_char)
}

fn provider_or_model_rest_char(ch: char) -> bool {
    ch.is_ascii_lowercase() || ch.is_ascii_digit() || matches!(ch, '.' | '_' | '-')
}

