fn print_agent_registry_instances(agents_json: String, total_turns: i64) -> Result<()> {
    let parsed = match parse_rlm_json_or_edn(&agents_json) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse --agents-json as JSON or EDN: {error}"
            ))?;
            return Ok(());
        }
    };
    let (items, fixture_total_turns) = match parsed.as_array() {
        Some(items) => (items.as_slice(), None),
        None => {
            let Some(map) = parsed.as_object() else {
                print_json_error("--agents-json must be a vector or map with :agents")?;
                return Ok(());
            };
            let Some(items) = rlm_map_get(map, "agents").and_then(serde_json::Value::as_array)
            else {
                print_json_error("--agents-json map must contain :agents vector")?;
                return Ok(());
            };
            (items.as_slice(), agent_registry_i64(map, "total-turns"))
        }
    };
    let agents = items
        .iter()
        .filter_map(|item| item.as_object())
        .map(agent_registry_instance_json)
        .collect::<Vec<_>>();
    let total = agents.len();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "agents": agents,
            "total": total,
            "total-turns": if total_turns != 0 { total_turns } else { fixture_total_turns.unwrap_or(0) },
            "projection": "common.commands/agent-registry$instances",
            "live-skipped?": true,
        }))?
    );
    Ok(())
}

fn agent_registry_instance_json(
    map: &serde_json::Map<String, serde_json::Value>,
) -> serde_json::Value {
    let state = agent_registry_object(map, "state")
        .or_else(|| agent_registry_object(map, "!state"))
        .or_else(|| agent_registry_object(map, "st"));
    let memory_init = agent_registry_object(map, "memory-init")
        .or_else(|| agent_registry_object(map, "st-init"))
        .or_else(|| agent_registry_object(map, "memory_init"));
    let bt_memory = agent_registry_object(map, "bt-st-memory")
        .or_else(|| agent_registry_object(map, "st-memory"))
        .or_else(|| agent_registry_object(map, "bt_st_memory"));
    let agent_id = agent_registry_string(map, "agent-id")
        .or_else(|| agent_registry_string(map, "id"))
        .or_else(|| agent_registry_string(map, "name"))
        .unwrap_or_default();
    let parent_id = agent_registry_string(map, "parent-id")
        .or_else(|| agent_registry_string(map, "parent"))
        .or_else(|| {
            state
                .and_then(|state| agent_registry_string(state, "parent-id"))
                .or_else(|| state.and_then(|state| agent_registry_string(state, "parent")))
        });
    let turn = agent_registry_i64(map, "turn")
        .or_else(|| memory_init.and_then(|state| agent_registry_i64(state, "turn-id")))
        .unwrap_or(0);
    let iter = agent_registry_i64(map, "iter")
        .or_else(|| agent_registry_i64(map, "iteration-count"))
        .or_else(|| bt_memory.and_then(|state| agent_registry_i64(state, "iteration-count")))
        .unwrap_or(0);
    let status = agent_registry_string(map, "status")
        .or_else(|| state.and_then(|state| agent_registry_string(state, "status")));
    serde_json::json!({
        "agent-id": agent_id,
        "turn": turn,
        "iter": iter,
        "parent-id": parent_id,
        "status": status,
    })
}

fn agent_registry_object<'a>(
    map: &'a serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<&'a serde_json::Map<String, serde_json::Value>> {
    rlm_map_get(map, key).and_then(serde_json::Value::as_object)
}

fn agent_registry_string(
    map: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<String> {
    rlm_map_get(map, key)
        .and_then(json_scalar_string)
        .map(|value| normalize_keywordish(&value))
        .filter(|value| !value.is_empty())
}

fn agent_registry_i64(map: &serde_json::Map<String, serde_json::Value>, key: &str) -> Option<i64> {
    match rlm_map_get(map, key)? {
        serde_json::Value::Number(value) => value.as_i64(),
        serde_json::Value::String(value) => value.parse().ok(),
        _ => None,
    }
}

fn print_models(fixture: Option<PathBuf>, provider: Option<String>) -> Result<()> {
    let registry = load_registry_or_embedded(fixture)?;
    if registry.models.is_empty() {
        println!("No models registered.");
        return Ok(());
    }

    let provider_filter = provider.as_deref();
    let listed = print_models_table(registry.models, provider_filter);
    if let Some(provider) = provider_filter.filter(|_| listed == 0) {
        println!("No models found for provider: {provider}");
    } else {
        println!(
            "{} model(s) listed.{}",
            listed,
            provider_filter
                .map(|provider| format!(" (filtered to {provider})"))
                .unwrap_or_default()
        );
    }
    Ok(())
}

fn print_llm_list_models(
    fixture: Option<PathBuf>,
    provider: Option<String>,
    limit: Option<usize>,
) -> Result<()> {
    let registry = load_registry_or_embedded(fixture)?;
    let all_models = registry.models;
    let total = all_models.len();
    let providers = distinct_model_providers(&all_models);
    let provider_filter = provider
        .as_deref()
        .map(normalize_keywordish)
        .filter(|value| !value.is_empty());
    let mut models = all_models
        .into_iter()
        .filter(|model| {
            provider_filter
                .as_ref()
                .is_none_or(|provider| provider == &model.provider)
        })
        .collect::<Vec<_>>();
    if let Some(limit) = limit.filter(|limit| *limit > 0) {
        models.truncate(limit);
    }
    let models = models
        .iter()
        .map(llm_model_descriptor_json)
        .collect::<Vec<_>>();
    let count = models.len();
    let output = serde_json::json!({
        "projection": "common.commands/llm$list-models",
        "models": models,
        "count": count,
        "total": total,
        "providers": providers,
        "provider": provider_filter,
        "network-skipped?": true
    });
    println!("{}", serde_json::to_string_pretty(&output)?);
    Ok(())
}

fn distinct_model_providers(models: &[by_registry::ModelDescriptor]) -> Vec<String> {
    let mut seen = BTreeSet::new();
    models
        .iter()
        .filter_map(|model| {
            if seen.insert(model.provider.clone()) {
                Some(model.provider.clone())
            } else {
                None
            }
        })
        .collect()
}

fn llm_model_descriptor_json(model: &by_registry::ModelDescriptor) -> serde_json::Value {
    let mut object = serde_json::Map::new();
    object.insert(
        "provider".to_string(),
        serde_json::Value::String(model.provider.clone()),
    );
    object.insert(
        "model".to_string(),
        serde_json::Value::String(model.id.clone()),
    );
    object.insert(
        "description".to_string(),
        serde_json::Value::String(model.description.clone().unwrap_or_default()),
    );
    if let Some(region) = model.region.as_deref().filter(|value| !value.is_empty()) {
        object.insert(
            "region".to_string(),
            serde_json::Value::String(region.to_string()),
        );
    }
    serde_json::Value::Object(object)
}

fn load_registry_or_embedded(fixture: Option<PathBuf>) -> Result<by_registry::RegistryFixture> {
    match fixture {
        Some(path) => by_registry::load_registry_path(path),
        None => by_registry::load_embedded_oracle_registry(),
    }
}

fn print_tools(fixture: PathBuf, tool_type: Option<String>, id: Option<String>) -> Result<()> {
    let tools = by_registry::load_tools_path(&fixture)?;
    if tools.is_empty() {
        println!("No tools registered.");
        return Ok(());
    }

    let listed = print_tools_table(tools, tool_type.as_deref(), id.as_deref());
    if listed == 0 {
        match (tool_type.as_deref(), id.as_deref()) {
            (_, Some(id)) => println!("No tools found for id: {id}"),
            (Some(tool_type), None) => println!("No tools found for type: {tool_type}"),
            (None, None) => println!("No tools registered."),
        }
    } else {
        println!(
            "{} tool(s) listed.{}{}",
            listed,
            tool_type
                .as_deref()
                .map(|tool_type| format!(" (filtered to type {tool_type})"))
                .unwrap_or_default(),
            id.as_deref()
                .map(|id| format!(" (filtered to id {id})"))
                .unwrap_or_default()
        );
    }
    Ok(())
}

fn print_mcp_servers(fixture: Option<PathBuf>) -> Result<()> {
    let mut servers = load_mcp_servers_or_embedded(fixture)?;
    for server in &servers {
        by_mcp::validate_server_config(&server.transport, &server.config)
            .with_context(|| format!("invalid MCP config for server '{}'", server.name))?;
    }
    servers.sort_by(|left, right| left.name.cmp(&right.name));

    let projected_servers = servers
        .iter()
        .map(|server| {
            serde_json::json!({
                "name": server.name,
                "connected": false,
                "transport": server.transport,
            })
        })
        .collect::<Vec<_>>();
    let output = serde_json::json!({
        "result": {
            "servers": projected_servers,
            "total": servers.len(),
            "connected": 0,
        }
    });
    println!("{}", serde_json::to_string_pretty(&output)?);
    Ok(())
}

fn print_mcp_config(fixture: Option<PathBuf>, server_name: String) -> Result<()> {
    let servers = load_mcp_servers_or_embedded(fixture)?;
    if server_name.trim().is_empty() {
        let output = by_mcp::project_error_command_result("server-name is required")?;
        println!("{}", serde_json::to_string_pretty(&output)?);
        return Ok(());
    }

    let Some(server) = servers
        .into_iter()
        .find(|server| server.name == server_name)
    else {
        let output = by_mcp::project_error_command_result(&format!(
            "MCP server '{server_name}' not found in configuration"
        ))?;
        println!("{}", serde_json::to_string_pretty(&output)?);
        return Ok(());
    };
    by_mcp::validate_server_config(&server.transport, &server.config)
        .with_context(|| format!("invalid MCP config for server '{}'", server.name))?;

    let output = serde_json::json!({
        "result": {
            "name": server.name,
            "config": {
                "transport": server.transport,
                "config": server.config,
                "enabled": server.enabled,
                "auto-register-tools": server.auto_register_tools,
            }
        }
    });
    println!("{}", serde_json::to_string_pretty(&output)?);
    Ok(())
}

