struct ConfigApplyPreflightArgs {
    proposed_edn: String,
    reason: String,
    confirm: bool,
    auto: bool,
    expected_mtime: Option<i64>,
    current_edn: Option<String>,
    current_mtime: Option<i64>,
    scope: String,
    requested_scope: Option<String>,
    target_path: String,
}

fn print_config_apply_preflight(args: ConfigApplyPreflightArgs) -> Result<()> {
    let requested_scope = args
        .requested_scope
        .clone()
        .unwrap_or_else(|| args.scope.clone());
    let base = serde_json::json!({
        "projection": "common.config/apply-preflight",
        "scope": args.scope.clone(),
        "requested-scope": requested_scope.clone(),
        "path": args.target_path.clone(),
        "write-skipped?": true,
        "snapshot-skipped?": true,
        "smoke-test-skipped?": true,
        "dossier-skipped?": true,
    });
    let Some(base_object) = base.as_object() else {
        unreachable!("json object literal")
    };

    if args.reason.is_empty() {
        let mut response = base_object.clone();
        response.insert("ok?".to_string(), serde_json::json!(false));
        response.insert("stage".to_string(), serde_json::json!("reason"));
        response.insert(
            "error".to_string(),
            serde_json::json!(":reason is required (string)"),
        );
        println!("{}", serde_json::to_string_pretty(&response)?);
        return Ok(());
    }

    let proposed_map = match parse_config_apply_map(&args.proposed_edn, "proposed") {
        Ok(map) => map,
        Err(error) => {
            let mut response = base_object.clone();
            response.insert("ok?".to_string(), serde_json::json!(false));
            response.insert("stage".to_string(), serde_json::json!("proposed"));
            response.insert("error".to_string(), serde_json::json!(error));
            println!("{}", serde_json::to_string_pretty(&response)?);
            return Ok(());
        }
    };
    let current_map = match args.current_edn.as_deref() {
        Some(current_edn) => match parse_config_apply_map(current_edn, "current") {
            Ok(map) => Some(map),
            Err(error) => {
                let mut response = base_object.clone();
                response.insert("ok?".to_string(), serde_json::json!(false));
                response.insert("stage".to_string(), serde_json::json!("current"));
                response.insert("error".to_string(), serde_json::json!(error));
                println!("{}", serde_json::to_string_pretty(&response)?);
                return Ok(());
            }
        },
        None => None,
    };

    let validation = config_validate_persisted(&proposed_map);
    let proposed_json = edn_map_to_json(&proposed_map);
    let current_json = current_map
        .as_ref()
        .map(edn_map_to_json)
        .unwrap_or_else(|| serde_json::json!({}));
    let after_json = deep_merge_json(&current_json, &proposed_json);
    let before_text = serde_json::to_string_pretty(&current_json)?;
    let after_text = serde_json::to_string_pretty(&after_json)?;
    let diff = fallback_config_diff(&before_text, &after_text);
    let structural = structural_config_delta(&current_json, &after_json);
    let secrets = config_secret_scan_redacted(&args.proposed_edn);
    let sensitive = config_sensitive_write(&proposed_map);

    let mut response = base_object.clone();
    response.insert("sensitive?".to_string(), serde_json::json!(sensitive));
    response.insert("diff".to_string(), serde_json::json!(diff));
    response.insert("structural".to_string(), structural);

    if !validation.errors.is_empty() {
        let has_allowlist = validation.errors.iter().any(|error| {
            error.get("type").and_then(|value| value.as_str()) == Some("allowlist-violation")
        });
        response.insert("ok?".to_string(), serde_json::json!(false));
        response.insert("stage".to_string(), serde_json::json!("validate"));
        response.insert(
            "error".to_string(),
            serde_json::json!(format!(
                "Validation failed ({} issue(s)).",
                validation.errors.len()
            )),
        );
        response.insert("errors".to_string(), serde_json::json!(validation.errors));
        if has_allowlist {
            response.insert(
                "hint".to_string(),
                serde_json::json!("Use bootstrap$re-run-rung for LLM provider/model changes."),
            );
        }
    } else if !secrets.is_empty() {
        response.insert("ok?".to_string(), serde_json::json!(false));
        response.insert("stage".to_string(), serde_json::json!("secret-detected"));
        response.insert("matches".to_string(), serde_json::json!(secrets));
        response.insert(
            "hint".to_string(),
            serde_json::json!("Secret-shaped value in config.edn. Reference it via an env var (e.g. in :mcp server env), not an inline literal. Put the secret in .env."),
        );
    } else if !args.confirm && (!args.auto || sensitive) {
        response.insert("ok?".to_string(), serde_json::json!(false));
        response.insert("stage".to_string(), serde_json::json!("unconfirmed"));
        response.insert(
            "hint".to_string(),
            serde_json::json!(config_apply_unconfirmed_hint(
                &args.scope,
                &requested_scope,
                &args.target_path,
                args.auto,
                sensitive,
            )),
        );
    } else if let (Some(expected), Some(actual)) = (args.expected_mtime, args.current_mtime) {
        if expected != actual {
            response.insert("ok?".to_string(), serde_json::json!(false));
            response.insert("stage".to_string(), serde_json::json!("mtime-conflict"));
            response.insert("expected".to_string(), serde_json::json!(expected));
            response.insert("actual".to_string(), serde_json::json!(actual));
            response.insert(
                "hint".to_string(),
                serde_json::json!(
                    "config.edn changed since you read it. Re-read with config$read."
                ),
            );
        } else {
            config_apply_ready_response(&mut response, args.current_mtime);
        }
    } else {
        config_apply_ready_response(&mut response, args.current_mtime);
    }

    println!("{}", serde_json::to_string_pretty(&response)?);
    Ok(())
}

fn parse_config_apply_map(
    input: &str,
    label: &str,
) -> std::result::Result<by_contracts::EdnMap, String> {
    match by_contracts::parse_value(input) {
        Ok(by_contracts::EdnValue::Map(map)) => Ok(map),
        Ok(_) => Err(format!(":{label} must be a map")),
        Err(error) => Err(format!("failed to parse {label} EDN: {error}")),
    }
}

fn config_apply_unconfirmed_hint(
    scope: &str,
    requested_scope: &str,
    target_path: &str,
    auto: bool,
    sensitive: bool,
) -> String {
    let mut hint = format!(
        "Surface :diff AND :path to the user, then re-call with :confirm? true. Resolved scope: {scope}"
    );
    if requested_scope == "auto" {
        hint.push_str(" (auto-resolved). Confirm the user wants this scope.");
    }
    if auto && sensitive {
        hint.push_str(
            " NOTE: this touches a security-sensitive key (permissions / sandbox-mode / allowed-dirs); --auto cannot self-confirm it — explicit :confirm? true is required.",
        );
    }
    hint.push_str(&format!(" Target: {target_path}"));
    hint
}

fn config_apply_ready_response(
    response: &mut serde_json::Map<String, serde_json::Value>,
    current_mtime: Option<i64>,
) {
    response.insert("ok?".to_string(), serde_json::json!(true));
    response.insert("stage".to_string(), serde_json::json!("ready-to-write"));
    response.insert(
        "hint".to_string(),
        serde_json::json!(
            "Projection only: snapshot, write, smoke test, dossier, and mtime-after are skipped."
        ),
    );
    if let Some(mtime) = current_mtime {
        response.insert("mtime-before".to_string(), serde_json::json!(mtime));
    }
    response.insert(
        "updated-at-would-change?".to_string(),
        serde_json::json!(true),
    );
}

fn print_config_list_snapshots(
    limit: usize,
    scope: String,
    base_dir: Option<PathBuf>,
    project_dir: Option<PathBuf>,
) -> Result<()> {
    let resolution = resolve_config_scope(project_dir.clone(), &scope)?;
    if let Some(error) = &resolution.error {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "snapshots": [],
                "error": error,
                "requested-scope": resolution.requested,
            }))?
        );
        return Ok(());
    }

    let base = base_dir.unwrap_or_else(|| {
        project_dir
            .map(|dir| dir.join(".brainyard"))
            .or_else(|| resolution.config_dir.clone())
            .unwrap_or_else(|| PathBuf::from(".brainyard"))
    });
    let mut snapshots = config_snapshot_records(&base)?;
    snapshots.truncate(limit);
    let response = serde_json::json!({
        "snapshots": snapshots,
        "base-dir": base.display().to_string(),
        "scope": resolution.scope,
        "requested-scope": resolution.requested,
    });
    println!("{}", serde_json::to_string_pretty(&response)?);
    Ok(())
}

fn print_config_snapshot_preview(
    reason: String,
    scope: String,
    base_dir: Option<PathBuf>,
    project_dir: Option<PathBuf>,
    timestamp: Option<String>,
) -> Result<()> {
    let resolution = resolve_config_scope(project_dir.clone(), &scope)?;
    if let Some(error) = &resolution.error {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "ok?": false,
                "error": error,
                "requested-scope": resolution.requested,
                "projection": "common.config/config$snapshot-preview",
                "write-skipped?": true,
                "rotation-skipped?": true,
            }))?
        );
        return Ok(());
    }
    let resolved_scope = resolution
        .scope
        .clone()
        .unwrap_or_else(|| "auto".to_string());
    let Some(config_path) = resolution.config_path() else {
        print_json_error("No config.edn at scope auto — nothing to snapshot.")?;
        return Ok(());
    };
    if !config_path.is_file() {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "ok?": false,
                "error": format!(
                    "No config.edn at scope {} — nothing to snapshot.",
                    resolved_scope
                ),
                "scope": resolved_scope,
                "requested-scope": resolution.requested,
                "projection": "common.config/config$snapshot-preview",
                "write-skipped?": true,
                "rotation-skipped?": true,
            }))?
        );
        return Ok(());
    }

    let base = config_base_dir_for_scope(&resolution, base_dir, project_dir);
    let timestamp = timestamp.unwrap_or_else(init_doc_now_ts);
    let filename = config_snapshot_filename(&timestamp, &reason);
    let path = config_snapshot_dir(&base).join(&filename);
    let content = std::fs::read_to_string(&config_path)
        .with_context(|| format!("failed to read config {}", config_path.display()))?;
    let rotated = config_rotation_preview(&base, &filename)?;
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "ok?": true,
            "path": path.display().to_string(),
            "reason": reason,
            "ts": timestamp,
            "rotated": rotated,
            "scope": resolved_scope,
            "requested-scope": resolution.requested,
            "source-path": config_path.display().to_string(),
            "content": content,
            "projection": "common.config/config$snapshot-preview",
            "write-skipped?": true,
            "rotation-skipped?": true,
        }))?
    );
    Ok(())
}

fn print_config_revert_preview(
    snapshot_path: Option<PathBuf>,
    steps: Option<usize>,
    scope: String,
    base_dir: Option<PathBuf>,
    project_dir: Option<PathBuf>,
    timestamp: Option<String>,
) -> Result<()> {
    let resolution = resolve_config_scope(project_dir.clone(), &scope)?;
    if let Some(error) = &resolution.error {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "ok?": false,
                "error": error,
                "requested-scope": resolution.requested,
                "projection": "common.config/config$revert-preview",
                "write-skipped?": true,
                "snapshot-skipped?": true,
            }))?
        );
        return Ok(());
    }
    let resolved_scope = resolution
        .scope
        .clone()
        .unwrap_or_else(|| "auto".to_string());
    let base = config_base_dir_for_scope(&resolution, base_dir, project_dir);
    let chosen = match config_find_snapshot(&base, snapshot_path.as_deref(), steps)? {
        Ok(record) => record,
        Err(error) => {
            println!(
                "{}",
                serde_json::to_string_pretty(&serde_json::json!({
                    "ok?": false,
                    "error": error,
                    "scope": resolved_scope,
                    "requested-scope": resolution.requested,
                    "projection": "common.config/config$revert-preview",
                    "write-skipped?": true,
                    "snapshot-skipped?": true,
                }))?
            );
            return Ok(());
        }
    };
    let Some(dest) = resolution.config_path() else {
        print_json_error(&format!(
            "No config.edn at scope {resolved_scope} to revert into."
        ))?;
        return Ok(());
    };
    if !dest.is_file() {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "ok?": false,
                "error": format!("No config.edn at scope {resolved_scope} to revert into."),
                "scope": resolved_scope,
                "requested-scope": resolution.requested,
                "projection": "common.config/config$revert-preview",
                "write-skipped?": true,
                "snapshot-skipped?": true,
            }))?
        );
        return Ok(());
    }

    let timestamp = timestamp.unwrap_or_else(init_doc_now_ts);
    let pre_reason = format!("revert-to-{}", chosen.reason);
    let pre_filename = config_snapshot_filename(&timestamp, &pre_reason);
    let pre_path = config_snapshot_dir(&base).join(pre_filename);
    let content = std::fs::read_to_string(&chosen.path)
        .with_context(|| format!("failed to read snapshot {}", chosen.path.display()))?;
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "ok?": true,
            "restored-from": chosen.path.display().to_string(),
            "pre-revert-snapshot": pre_path.display().to_string(),
            "dest": dest.display().to_string(),
            "scope": resolved_scope,
            "requested-scope": resolution.requested,
            "content": content,
            "projection": "common.config/config$revert-preview",
            "write-skipped?": true,
            "snapshot-skipped?": true,
        }))?
    );
    Ok(())
}

