fn agent_runtime_valid_config_keys_display() -> String {
    CONFIG_SCHEMA_TYPES
        .iter()
        .map(|(key, _)| *key)
        .collect::<Vec<_>>()
        .join(", ")
}

fn agent_runtime_coerce_config_value(
    value: &str,
    type_name: &str,
) -> (serde_json::Value, by_contracts::EdnValue) {
    match type_name {
        "integer" => value
            .parse::<i64>()
            .map(|value| {
                (
                    serde_json::json!(value),
                    by_contracts::EdnValue::Integer(value),
                )
            })
            .unwrap_or_else(|_| agent_runtime_string_config_value(value)),
        "number" => value
            .parse::<f64>()
            .ok()
            .and_then(|number| {
                serde_json::Number::from_f64(number)
                    .map(|json_number| (number, serde_json::Value::Number(json_number)))
            })
            .map(|(number, json)| (json, by_contracts::EdnValue::Float(number)))
            .unwrap_or_else(|| agent_runtime_string_config_value(value)),
        "boolean" => match value {
            "true" => (serde_json::json!(true), by_contracts::EdnValue::Bool(true)),
            "false" => (
                serde_json::json!(false),
                by_contracts::EdnValue::Bool(false),
            ),
            _ => agent_runtime_string_config_value(value),
        },
        "keyword" => {
            let keyword = normalize_keywordish(value);
            (
                serde_json::json!(keyword),
                by_contracts::EdnValue::Keyword(keyword),
            )
        }
        "array" | "vector" => serde_json::from_str::<serde_json::Value>(value)
            .ok()
            .filter(serde_json::Value::is_array)
            .map(|json| {
                let edn = agent_runtime_json_to_edn(&json);
                (json, edn)
            })
            .unwrap_or_else(|| agent_runtime_string_config_value(value)),
        "object" => serde_json::from_str::<serde_json::Value>(value)
            .ok()
            .filter(serde_json::Value::is_object)
            .map(|json| {
                let edn = agent_runtime_json_to_edn(&json);
                (json, edn)
            })
            .unwrap_or_else(|| agent_runtime_string_config_value(value)),
        _ => agent_runtime_string_config_value(value),
    }
}

fn agent_runtime_string_config_value(value: &str) -> (serde_json::Value, by_contracts::EdnValue) {
    (
        serde_json::json!(value),
        by_contracts::EdnValue::String(value.to_string()),
    )
}

fn agent_runtime_json_to_edn(value: &serde_json::Value) -> by_contracts::EdnValue {
    match value {
        serde_json::Value::Null => by_contracts::EdnValue::Nil,
        serde_json::Value::Bool(value) => by_contracts::EdnValue::Bool(*value),
        serde_json::Value::Number(value) => {
            if let Some(value) = value.as_i64() {
                by_contracts::EdnValue::Integer(value)
            } else if let Some(value) = value.as_u64().and_then(|value| i64::try_from(value).ok()) {
                by_contracts::EdnValue::Integer(value)
            } else {
                by_contracts::EdnValue::Float(value.as_f64().unwrap_or_default())
            }
        }
        serde_json::Value::String(value) => by_contracts::EdnValue::String(value.clone()),
        serde_json::Value::Array(values) => {
            by_contracts::EdnValue::Vector(values.iter().map(agent_runtime_json_to_edn).collect())
        }
        serde_json::Value::Object(object) => {
            by_contracts::EdnValue::Map(by_contracts::EdnMap::new(
                object
                    .iter()
                    .map(|(key, value)| (key.clone(), agent_runtime_json_to_edn(value)))
                    .collect(),
            ))
        }
    }
}

fn agent_runtime_proposed_config_edn(
    key: &str,
    value: by_contracts::EdnValue,
) -> by_contracts::EdnMap {
    let mut config = BTreeMap::new();
    config.insert(key.to_string(), value);
    let mut agent = BTreeMap::new();
    agent.insert(
        "config".to_string(),
        by_contracts::EdnValue::Map(by_contracts::EdnMap::new(config)),
    );
    let mut root = BTreeMap::new();
    root.insert(
        "agent".to_string(),
        by_contracts::EdnValue::Map(by_contracts::EdnMap::new(agent)),
    );
    by_contracts::EdnMap::new(root)
}

fn agent_runtime_config_write_path(
    project_dir: Option<PathBuf>,
    requested_scope: &str,
) -> Result<PathBuf> {
    let dirs = config_dirs_for_project(project_dir)?;
    let requested_scope = normalize_config_scope(requested_scope);
    let dir = match requested_scope.as_str() {
        "user" => by_config::user_config_dir(&dirs)
            .unwrap_or_else(|| by_config::project_config_dir(&dirs)),
        "project" | "auto" => by_config::project_config_dir(&dirs),
        _ => by_config::project_config_dir(&dirs),
    };
    Ok(dir.join("config.edn"))
}

fn agent_runtime_config_value_display(value: &serde_json::Value, type_name: &str) -> String {
    if type_name == "keyword" {
        return value
            .as_str()
            .map(|value| format!(":{}", normalize_keywordish(value)))
            .unwrap_or_else(|| render_json_as_edn(value));
    }
    match value {
        serde_json::Value::String(value) => value.clone(),
        _ => render_json_as_edn(value),
    }
}

fn deep_merge_json(left: &serde_json::Value, right: &serde_json::Value) -> serde_json::Value {
    match (left, right) {
        (serde_json::Value::Object(left), serde_json::Value::Object(right)) => {
            let mut merged = left.clone();
            for (key, right_value) in right {
                let value = merged
                    .get(key)
                    .map(|left_value| deep_merge_json(left_value, right_value))
                    .unwrap_or_else(|| right_value.clone());
                merged.insert(key.clone(), value);
            }
            serde_json::Value::Object(merged)
        }
        _ => right.clone(),
    }
}

struct ConfigPersistedValidation {
    errors: Vec<serde_json::Value>,
}

fn config_validate_persisted(proposed: &by_contracts::EdnMap) -> ConfigPersistedValidation {
    let leaves = config_collect_leaves(proposed);
    let mut errors = Vec::new();
    for (path, value) in leaves {
        if !config_path_allowed(&path) {
            errors.push(serde_json::json!({
                "type": "allowlist-violation",
                "path": path,
                "reason": format!(
                    "{} is not in writable-prefixes. If this is an LLM provider/model change, call bootstrap$re-run-rung instead.",
                    config_path_display(&path)
                ),
            }));
            continue;
        }

        if config_schema_config_leaf(&path) {
            let key = path.last().expect("schema leaf has key");
            match config_schema_type(key) {
                None => errors.push(serde_json::json!({
                    "type": "schema-violation",
                    "path": path,
                    "value": edn_value_to_json(&value),
                    "reason": format!("{key} is not a known config-schema key. See agent.core.config/config-schema."),
                })),
                Some(type_name) if !config_valid_config_value(type_name, &value) => {
                    errors.push(serde_json::json!({
                        "type": "schema-violation",
                        "path": path,
                        "value": edn_value_to_json(&value),
                        "reason": format!(
                            "{} value {} does not match schema type {}.",
                            config_path_display(&path),
                            config_edn_reason_value(&value),
                            type_name
                        ),
                    }));
                }
                Some(_) => {}
            }
            continue;
        }

        if let Some(valid) = config_leaf_validator(&path) {
            if !valid(&value) {
                errors.push(serde_json::json!({
                    "type": "schema-violation",
                    "path": path,
                    "value": edn_value_to_json(&value),
                    "reason": format!("{} did not pass the leaf validator.", config_path_display(&path)),
                }));
            }
        }
    }
    ConfigPersistedValidation { errors }
}

fn config_collect_leaves(
    proposed: &by_contracts::EdnMap,
) -> Vec<(Vec<String>, by_contracts::EdnValue)> {
    let mut leaves = Vec::new();
    for (key, value) in proposed.iter() {
        config_collect_leaves_value(vec![key.clone()], value, &mut leaves);
    }
    leaves
}

fn config_collect_leaves_value(
    path: Vec<String>,
    value: &by_contracts::EdnValue,
    leaves: &mut Vec<(Vec<String>, by_contracts::EdnValue)>,
) {
    if path.as_slice() == ["mcp", "servers"] {
        leaves.push((path, value.clone()));
        return;
    }
    match value {
        by_contracts::EdnValue::Map(map) => {
            for (key, child) in map.iter() {
                let mut child_path = path.clone();
                child_path.push(key.clone());
                config_collect_leaves_value(child_path, child, leaves);
            }
        }
        by_contracts::EdnValue::MapEntries(entries) => {
            for (key, child) in entries {
                let mut child_path = path.clone();
                child_path.push(edn_json_key(key));
                config_collect_leaves_value(child_path, child, leaves);
            }
        }
        _ => leaves.push((path, value.clone())),
    }
}

fn config_path_allowed(path: &[String]) -> bool {
    const WRITABLE_PREFIXES: &[&[&str]] = &[
        &["llm", "available-providers"],
        &["permissions", "mode"],
        &["permissions", "allowed-dirs"],
        &["agent", "default-agent"],
        &["agent", "config"],
        &["environment", "sandbox-mode"],
        &["mcp", "servers"],
        &["updated-at"],
    ];
    WRITABLE_PREFIXES
        .iter()
        .any(|prefix| path.len() >= prefix.len() && prefix.iter().zip(path).all(|(a, b)| *a == b))
}

fn config_schema_config_leaf(path: &[String]) -> bool {
    path.len() == 3 && path[0] == "agent" && path[1] == "config"
}

fn config_leaf_validator(path: &[String]) -> Option<fn(&by_contracts::EdnValue) -> bool> {
    match path {
        [first, second] if first == "permissions" && second == "mode" => {
            Some(config_valid_permission_mode)
        }
        [first, second] if first == "permissions" && second == "allowed-dirs" => {
            Some(config_valid_string_sequence)
        }
        [first, second] if first == "agent" && second == "default-agent" => {
            Some(config_valid_keyword)
        }
        [first, second] if first == "environment" && second == "sandbox-mode" => {
            Some(config_valid_sandbox_mode)
        }
        [first, second] if first == "llm" && second == "available-providers" => {
            Some(config_valid_keyword_sequence)
        }
        [first] if first == "updated-at" => Some(config_valid_string),
        _ => None,
    }
}

fn config_valid_permission_mode(value: &by_contracts::EdnValue) -> bool {
    matches!(
        config_edn_keywordish(value).as_deref(),
        Some("auto-approve" | "ask-each-time" | "deny-by-default")
    )
}

fn config_valid_sandbox_mode(value: &by_contracts::EdnValue) -> bool {
    matches!(
        config_edn_keywordish(value).as_deref(),
        Some("permissive" | "standard" | "restricted")
    )
}

fn config_valid_keyword(value: &by_contracts::EdnValue) -> bool {
    matches!(value, by_contracts::EdnValue::Keyword(_))
}

fn config_valid_string(value: &by_contracts::EdnValue) -> bool {
    matches!(value, by_contracts::EdnValue::String(_))
}

fn config_valid_string_sequence(value: &by_contracts::EdnValue) -> bool {
    match value {
        by_contracts::EdnValue::Vector(values) | by_contracts::EdnValue::List(values) => values
            .iter()
            .all(|value| matches!(value, by_contracts::EdnValue::String(_))),
        _ => false,
    }
}

fn config_valid_keyword_sequence(value: &by_contracts::EdnValue) -> bool {
    match value {
        by_contracts::EdnValue::Vector(values) | by_contracts::EdnValue::List(values) => values
            .iter()
            .all(|value| matches!(value, by_contracts::EdnValue::Keyword(_))),
        _ => false,
    }
}

fn config_schema_type(key: &str) -> Option<&'static str> {
    CONFIG_SCHEMA_TYPES
        .iter()
        .find_map(|(schema_key, type_name)| (*schema_key == key).then_some(*type_name))
}

fn config_valid_config_value(type_name: &str, value: &by_contracts::EdnValue) -> bool {
    match type_name {
        "string" => matches!(
            value,
            by_contracts::EdnValue::String(_) | by_contracts::EdnValue::Keyword(_)
        ),
        "keyword" => matches!(value, by_contracts::EdnValue::Keyword(_)),
        "integer" => matches!(value, by_contracts::EdnValue::Integer(_)),
        "number" => matches!(
            value,
            by_contracts::EdnValue::Integer(_) | by_contracts::EdnValue::Float(_)
        ),
        "boolean" => matches!(value, by_contracts::EdnValue::Bool(_)),
        "array" | "vector" => matches!(
            value,
            by_contracts::EdnValue::Vector(_) | by_contracts::EdnValue::List(_)
        ),
        "object" => matches!(
            value,
            by_contracts::EdnValue::Map(_) | by_contracts::EdnValue::MapEntries(_)
        ),
        _ => true,
    }
}

fn config_sensitive_write(proposed: &by_contracts::EdnMap) -> bool {
    const SENSITIVE_PREFIXES: &[&[&str]] = &[
        &["permissions", "mode"],
        &["permissions", "allowed-dirs"],
        &["environment", "sandbox-mode"],
    ];
    config_collect_leaves(proposed)
        .into_iter()
        .any(|(path, _)| {
            SENSITIVE_PREFIXES.iter().any(|prefix| {
                path.len() >= prefix.len() && prefix.iter().zip(&path).all(|(a, b)| *a == b)
            })
        })
}

fn config_edn_keywordish(value: &by_contracts::EdnValue) -> Option<String> {
    match value {
        by_contracts::EdnValue::Keyword(value)
        | by_contracts::EdnValue::String(value)
        | by_contracts::EdnValue::Symbol(value) => Some(normalize_keywordish(value)),
        _ => None,
    }
}

fn config_path_display(path: &[String]) -> String {
    format!(
        "[{}]",
        path.iter()
            .map(|part| format!(":{part}"))
            .collect::<Vec<_>>()
            .join(" ")
    )
}

fn config_edn_reason_value(value: &by_contracts::EdnValue) -> String {
    match value {
        by_contracts::EdnValue::Keyword(value) => format!(":{value}"),
        by_contracts::EdnValue::Symbol(value) => value.clone(),
        by_contracts::EdnValue::String(value) => format!("{value:?}"),
        other => edn_value_to_json(other).to_string(),
    }
}

fn config_secret_scan_redacted(text: &str) -> Vec<String> {
    [
        r"sk-[A-Za-z0-9]{20,}",
        r"AKIA[0-9A-Z]{16}",
        r"ASIA[0-9A-Z]{16}",
        r"ghp_[A-Za-z0-9]{20,}",
        r"github_pat_[A-Za-z0-9_]{20,}",
        r"xox[bpoars]-[A-Za-z0-9-]{10,}",
        r"-----BEGIN [A-Z ]*PRIVATE KEY-----",
        r"AIza[0-9A-Za-z_-]{20,}",
    ]
    .iter()
    .filter_map(|pattern| regex::Regex::new(pattern).ok())
    .flat_map(|re| {
        re.find_iter(text)
            .map(|hit| {
                let value = hit.as_str();
                let prefix = value.chars().take(8).collect::<String>();
                format!("{prefix}…")
            })
            .collect::<Vec<_>>()
    })
    .collect()
}

