fn structural_config_delta(
    before: &serde_json::Value,
    after: &serde_json::Value,
) -> serde_json::Value {
    let Some(before) = before.as_object() else {
        return serde_json::json!({
            "adds": after,
            "removes": {},
            "changes": {},
        });
    };
    let Some(after) = after.as_object() else {
        return serde_json::json!({
            "adds": {},
            "removes": before,
            "changes": {
                "root": {
                    "before": serde_json::Value::Object(before.clone()),
                    "after": after,
                }
            },
        });
    };

    let mut adds = serde_json::Map::new();
    let mut removes = serde_json::Map::new();
    let mut changes = serde_json::Map::new();
    for (key, value) in after {
        match before.get(key) {
            None => {
                adds.insert(key.clone(), value.clone());
            }
            Some(before_value) if before_value != value => {
                changes.insert(
                    key.clone(),
                    serde_json::json!({
                        "before": before_value,
                        "after": value,
                    }),
                );
            }
            Some(_) => {}
        }
    }
    for (key, value) in before {
        if !after.contains_key(key) {
            removes.insert(key.clone(), value.clone());
        }
    }

    serde_json::json!({
        "adds": adds,
        "removes": removes,
        "changes": changes,
    })
}

fn fallback_config_diff(before: &str, after: &str) -> String {
    if before == after {
        return String::new();
    }
    format!("--- before\n{before}\n+++ after\n{after}\n")
}

fn config_snapshot_dir(base: &Path) -> PathBuf {
    base.join("agents/config-agent/snapshots")
}

fn config_snapshot_filename(timestamp: &str, reason: &str) -> String {
    format!(
        "{}-{}.edn",
        timestamp,
        config_slugify(
            if reason.is_empty() {
                "snapshot"
            } else {
                reason
            },
            60
        )
    )
}

fn config_snapshot_records(base: &Path) -> Result<Vec<serde_json::Value>> {
    Ok(config_snapshot_records_typed(base)?
        .into_iter()
        .map(config_snapshot_record_json)
        .collect())
}

fn config_snapshot_records_typed(base: &Path) -> Result<Vec<ConfigSnapshotRecord>> {
    let dir = config_snapshot_dir(base);
    if !dir.is_dir() {
        return Ok(Vec::new());
    }

    let mut records = Vec::new();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read snapshot dir {}", dir.display()))?
    {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let path = entry.path();
        let Some(filename) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        let Some((ts, reason)) = parse_config_snapshot_name(filename) else {
            continue;
        };
        let filename = filename.to_string();
        let metadata = entry.metadata()?;
        records.push(ConfigSnapshotRecord {
            ts,
            reason,
            path,
            filename,
            size_bytes: metadata.len(),
            mtime: metadata.modified().ok().and_then(system_time_millis),
        });
    }
    records.sort_by(|left, right| {
        right
            .ts
            .cmp(&left.ts)
            .then_with(|| right.filename.cmp(&left.filename))
    });
    Ok(records)
}

fn config_snapshot_record_json(record: ConfigSnapshotRecord) -> serde_json::Value {
    serde_json::json!({
        "ts": record.ts,
        "reason": record.reason,
        "path": record.path.display().to_string(),
        "filename": record.filename,
        "size-bytes": record.size_bytes,
        "mtime": record.mtime,
    })
}

fn config_rotation_preview(base: &Path, new_filename: &str) -> Result<Vec<String>> {
    let mut filenames = config_snapshot_records_typed(base)?
        .into_iter()
        .map(|record| record.filename)
        .collect::<Vec<_>>();
    filenames.push(new_filename.to_string());
    filenames.sort();
    let keep = filenames
        .iter()
        .rev()
        .take(20)
        .cloned()
        .collect::<BTreeSet<_>>();
    Ok(filenames
        .into_iter()
        .filter(|filename| !keep.contains(filename))
        .collect())
}

fn config_find_snapshot(
    base: &Path,
    snapshot_path: Option<&Path>,
    steps: Option<usize>,
) -> Result<std::result::Result<ConfigSnapshotRecord, String>> {
    if let Some(path) = snapshot_path {
        if !path.is_file() {
            return Ok(Err(format!("Snapshot not found: {}", path.display())));
        }
        let filename = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default()
            .to_string();
        let (ts, reason) = parse_config_snapshot_name(&filename)
            .unwrap_or_else(|| ("".to_string(), "snapshot".to_string()));
        let metadata = std::fs::metadata(path)
            .with_context(|| format!("failed to stat snapshot {}", path.display()))?;
        return Ok(Ok(ConfigSnapshotRecord {
            ts,
            reason,
            path: path.to_path_buf(),
            filename,
            size_bytes: metadata.len(),
            mtime: metadata.modified().ok().and_then(system_time_millis),
        }));
    }

    let Some(steps) = steps else {
        return Ok(Err("Provide :snapshot-path or :steps.".to_string()));
    };
    let records = config_snapshot_records_typed(base)?;
    if steps < 1 || records.is_empty() {
        return Ok(Err("No snapshots available.".to_string()));
    }
    if steps > records.len() {
        return Ok(Err(format!(
            ":steps {steps} exceeds {} available snapshots.",
            records.len()
        )));
    }
    Ok(Ok(records[steps - 1].clone()))
}

fn parse_config_snapshot_name(filename: &str) -> Option<(String, String)> {
    let stem = filename.strip_suffix(".edn")?;
    let bytes = stem.as_bytes();
    if bytes.len() < 17
        || !bytes[0..8].iter().all(u8::is_ascii_digit)
        || bytes[8] != b'-'
        || !bytes[9..15].iter().all(u8::is_ascii_digit)
        || bytes[15] != b'-'
    {
        return None;
    }
    let ts = stem[0..15].to_string();
    let reason = stem[16..].to_string();
    if reason.is_empty() {
        return None;
    }
    Some((ts, reason))
}

fn config_slugify(value: &str, max_chars: usize) -> String {
    const STOPWORDS: [&str; 57] = [
        "a", "an", "the", "is", "are", "and", "or", "of", "in", "on", "at", "to", "for", "by",
        "with", "from", "as", "but", "if", "then", "than", "so", "what", "where", "when", "who",
        "whom", "why", "how", "which", "do", "does", "did", "can", "could", "would", "should",
        "shall", "will", "this", "that", "these", "those", "it", "its", "we", "they", "you", "i",
        "be", "been", "being", "was", "were", "have", "has", "had",
    ];
    let mut normalized = String::new();
    for ch in value.chars().flat_map(char::to_lowercase) {
        if ch.is_ascii_alphanumeric() {
            normalized.push(ch);
        } else {
            normalized.push('-');
        }
    }
    let mut kept = Vec::new();
    for token in normalized.split('-') {
        if !token.is_empty() && !STOPWORDS.contains(&token) {
            kept.push(token);
        }
    }
    let joined = if kept.is_empty() {
        "change".to_string()
    } else {
        kept.join("-")
    };
    truncate_chars(&joined, max_chars)
}

fn build_config_dossier_frontmatter(opts: &ConfigFrontmatterOptions) -> String {
    let mut out = String::new();
    out.push_str("---\n");
    out.push_str("agent: config-agent\n");
    out.push_str(&format!(
        "session-id: {}\n",
        yaml_string(opts.session_id.as_deref().unwrap_or_default())
    ));
    out.push_str(&format!(
        "question: {}\n",
        yaml_string(opts.question.as_deref().unwrap_or_default())
    ));
    out.push_str(&format!("slug: {}\n", opts.slug));
    out.push_str(&format!(
        "started: {}\n",
        opts.started.clone().unwrap_or_else(current_iso_utc)
    ));
    if let Some(ended) = &opts.ended {
        out.push_str(&format!("ended: {ended}\n"));
    }
    out.push_str(&format!(
        "config-path: {}\n",
        yaml_string(opts.config_path.as_deref().unwrap_or_default())
    ));
    out.push_str(&format!(
        "snapshots: {}\n",
        yaml_flow_vector(&opts.snapshots)
    ));
    out.push_str(&format!("writes: {}\n", opts.writes));
    out.push_str(&format!("reverts: {}\n", opts.reverts));
    out.push_str(&format!(
        "next-steps: {}\n",
        yaml_flow_vector(&opts.next_steps)
    ));
    out.push_str("---\n");
    out
}

fn yaml_string(value: &str) -> String {
    format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
}

fn yaml_flow_vector(values: &[String]) -> String {
    let items = values
        .iter()
        .map(|value| {
            if yaml_bareword(value) {
                value.clone()
            } else {
                yaml_string(value)
            }
        })
        .collect::<Vec<_>>()
        .join(", ");
    format!("[{items}]")
}

fn yaml_bareword(value: &str) -> bool {
    !value.is_empty()
        && value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '_' | '.' | '/' | ':' | '-'))
}

fn current_iso_utc() -> String {
    let seconds = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or(0);
    unix_seconds_to_iso_utc(seconds)
}

fn unix_seconds_to_iso_utc(seconds: i64) -> String {
    let days = seconds.div_euclid(86_400);
    let seconds_of_day = seconds.rem_euclid(86_400);
    let (year, month, day) = civil_from_days(days);
    let hour = seconds_of_day / 3_600;
    let minute = (seconds_of_day % 3_600) / 60;
    let second = seconds_of_day % 60;
    format!("{year:04}-{month:02}-{day:02}T{hour:02}:{minute:02}:{second:02}Z")
}

fn civil_from_days(days_since_epoch: i64) -> (i64, i64, i64) {
    let z = days_since_epoch + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let year_of_era = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let month_prime = (5 * doy + 2) / 153;
    let day = doy - (153 * month_prime + 2) / 5 + 1;
    let month = month_prime + if month_prime < 10 { 3 } else { -9 };
    let year = year_of_era + if month <= 2 { 1 } else { 0 };
    (year, month, day)
}

fn print_config(path: Option<PathBuf>) -> Result<()> {
    let explicit_path = path.is_some();
    let path = match path {
        Some(path) => path,
        None => default_config_path().context("could not determine default config path")?,
    };
    let config = if !explicit_path && !path.exists() {
        by_config::ConfigDocument::empty()
    } else {
        by_config::read_config(&path)?
    };
    let llm = config.llm();
    let agent = config.agent();
    let permissions = config.permissions();
    println!(
        "agent.default-agent\t{}",
        agent.default_agent.unwrap_or_default()
    );
    println!(
        "agent.max-iterations\t{}",
        agent
            .max_iterations
            .map(|value| value.to_string())
            .unwrap_or_default()
    );
    println!("permissions.mode\t{}", permissions.mode.unwrap_or_default());
    println!(
        "permissions.allowed-dirs\t{}",
        permissions.allowed_dirs.join(",")
    );
    println!(
        "llm.default-provider\t{}",
        llm.default_provider.unwrap_or_default()
    );
    println!(
        "llm.default-model\t{}",
        llm.default_model.unwrap_or_default()
    );
    println!(
        "llm.available-providers\t{}",
        llm.available_providers.join(",")
    );
    Ok(())
}

fn print_memory_search(
    db: Option<PathBuf>,
    user_id: Option<String>,
    query: String,
    limit: usize,
) -> Result<()> {
    let db = resolve_memory_db_path(db, user_id)?;
    let request = by_memory::MemorySearchRequest { query, limit };
    for hit in by_memory::search_memory(&db, request)? {
        println!("{}\t{}\t{}", hit.layer.as_str(), hit.kind, hit.content);
    }
    Ok(())
}

struct MemoryRecallOptions {
    db: Option<PathBuf>,
    user_id: Option<String>,
    session_id: Option<String>,
    query: String,
    layer: Option<String>,
    limit: usize,
    match_mode: String,
    kind: Option<String>,
    min_confidence: Option<f64>,
}

fn print_memory_recall(opts: MemoryRecallOptions) -> Result<()> {
    let resolved_user_id = resolve_memory_user_id(opts.user_id.as_deref());
    let db = resolve_memory_db_path(opts.db, Some(resolved_user_id.clone()))?;
    let mut report = by_memory::recall_memory(
        &db,
        by_memory::MemoryRecallRequest {
            user_id: resolved_user_id.clone(),
            session_id: opts.session_id.clone(),
            query: opts.query.clone(),
            layer: opts.layer.clone(),
            limit: opts.limit,
            match_mode: opts.match_mode.clone(),
            kind: opts.kind,
            min_confidence: opts.min_confidence,
        },
    )?;
    if let serde_json::Value::Object(ref mut object) = report {
        object.insert(
            "projection".to_string(),
            serde_json::json!("common.commands/memory$recall"),
        );
        object.insert("source".to_string(), serde_json::json!("local-sqlite"));
        object.insert("live-skipped?".to_string(), serde_json::json!(true));
        object.insert(
            "current-agent-skipped?".to_string(),
            serde_json::json!(true),
        );
        object.insert(
            "db".to_string(),
            serde_json::json!(db.display().to_string()),
        );
        object.insert("user-id".to_string(), serde_json::json!(resolved_user_id));
        object.insert("query".to_string(), serde_json::json!(opts.query));
        object.insert("requested-layer".to_string(), serde_json::json!(opts.layer));
        object.insert("limit".to_string(), serde_json::json!(opts.limit));
    }
    println!("{}", serde_json::to_string_pretty(&report)?);
    Ok(())
}

struct MemoryReadOptions {
    db: Option<PathBuf>,
    user_id: Option<String>,
    layer: String,
    query: String,
    limit: usize,
    include_archived: bool,
}

fn print_memory_read(opts: MemoryReadOptions) -> Result<()> {
    let resolved_user_id = resolve_memory_user_id(opts.user_id.as_deref());
    let db = resolve_memory_db_path(opts.db, Some(resolved_user_id.clone()))?;
    let query = match parse_rlm_json_or_edn(&opts.query) {
        Ok(value) if value.is_object() => value,
        Ok(_) => {
            print_json_error("query must be a JSON or EDN map")?;
            return Ok(());
        }
        Err(error) => {
            print_json_error(&error.to_string())?;
            return Ok(());
        }
    };
    let mut report = by_memory::read_memory(
        &db,
        by_memory::MemoryReadRequest {
            user_id: resolved_user_id.clone(),
            layer: opts.layer.clone(),
            query: query.clone(),
            limit: opts.limit,
            include_archived: opts.include_archived,
        },
    )?;
    if let serde_json::Value::Object(ref mut object) = report {
        object.insert(
            "projection".to_string(),
            serde_json::json!("memory-agent/memory$read"),
        );
        object.insert("source".to_string(), serde_json::json!("local-sqlite"));
        object.insert("live-skipped?".to_string(), serde_json::json!(true));
        object.insert(
            "current-agent-skipped?".to_string(),
            serde_json::json!(true),
        );
        object.insert(
            "db".to_string(),
            serde_json::json!(db.display().to_string()),
        );
        object.insert("user-id".to_string(), serde_json::json!(resolved_user_id));
        object.insert("requested-layer".to_string(), serde_json::json!(opts.layer));
        object.insert("query".to_string(), query);
        object.insert("limit".to_string(), serde_json::json!(opts.limit));
        object.insert(
            "include-archived?".to_string(),
            serde_json::json!(opts.include_archived),
        );
    }
    println!("{}", serde_json::to_string_pretty(&report)?);
    Ok(())
}

struct MemoryWriteOptions {
    db: Option<PathBuf>,
    user_id: Option<String>,
    layer: String,
    entry: String,
}

fn print_memory_write(opts: MemoryWriteOptions) -> Result<()> {
    let (db, resolved_user_id) = resolve_memory_db_context(opts.db, opts.user_id)?;
    let entry = match parse_rlm_json_or_edn(&opts.entry) {
        Ok(value) if value.is_object() => value,
        Ok(_) => {
            let mut report = serde_json::json!({
                "error": "entry must be a JSON or EDN map",
            });
            insert_memory_persisted_write_metadata(
                &mut report,
                &db,
                &resolved_user_id,
                "memory-agent/memory$write",
                &opts.layer,
            );
            println!("{}", serde_json::to_string_pretty(&report)?);
            return Ok(());
        }
        Err(error) => {
            let mut report = serde_json::json!({
                "error": format!("failed to parse entry as JSON or EDN: {error}"),
            });
            insert_memory_persisted_write_metadata(
                &mut report,
                &db,
                &resolved_user_id,
                "memory-agent/memory$write",
                &opts.layer,
            );
            println!("{}", serde_json::to_string_pretty(&report)?);
            return Ok(());
        }
    };
    let rendered_entry = serde_json::to_string(&entry)?;
    let mut report =
        if let Some(violation) = guard_content_violation_value(&rendered_entry, None, false) {
            violation
        } else {
            by_memory::write_memory_entry(
                &db,
                by_memory::MemoryWriteRequest {
                    user_id: resolved_user_id.clone(),
                    layer: opts.layer.clone(),
                    entry: entry.clone(),
                },
            )?
        };
    insert_memory_persisted_write_metadata(
        &mut report,
        &db,
        &resolved_user_id,
        "memory-agent/memory$write",
        &opts.layer,
    );
    if let serde_json::Value::Object(ref mut object) = report {
        object.insert("input-entry".to_string(), entry);
    }
    println!("{}", serde_json::to_string_pretty(&report)?);
    Ok(())
}

