fn print_workflow_bootstrap_preview(opts: WorkflowBootstrapPreviewOptions) -> Result<()> {
    if opts.id.trim().is_empty() {
        print_json_error(":id is required (string)")?;
        return Ok(());
    }
    if opts.purpose.trim().is_empty() {
        print_json_error(":purpose is required (string)")?;
        return Ok(());
    }
    if let Some(error) = workflow_bootstrap_guard_error(&opts.purpose, &opts.acceptance) {
        println!("{}", serde_json::to_string_pretty(&error)?);
        return Ok(());
    }
    let acceptance = match parse_bootstrap_acceptance(&opts.acceptance, "acceptance") {
        Ok(acceptance) => acceptance,
        Err(error) => {
            print_json_error(&error)?;
            return Ok(());
        }
    };
    let stages = match parse_workflow_bootstrap_stages(&opts.stages) {
        Ok(stages) => stages,
        Err(error) => {
            print_json_error(&error)?;
            return Ok(());
        }
    };
    let template_id = opts
        .template_id
        .as_deref()
        .map(normalize_keywordish)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "ad-hoc".to_string());
    let hitl_mode = opts
        .hitl_mode
        .as_deref()
        .map(normalize_keywordish)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "gates".to_string());
    if !WORKFLOW_HITL_MODES.contains(&hitl_mode.as_str()) {
        print_json_error(&format!(
            ":hitl-mode must be one of {}",
            workflow_status_error_list(WORKFLOW_HITL_MODES)
        ))?;
        return Ok(());
    }

    let base_dir = opts
        .base_dir
        .map(Ok)
        .unwrap_or_else(std::env::current_dir)?;
    let dir_rel = format!("{WORKFLOW_RESULTS_BASE_REL}/{}", opts.id);
    let dossier_rel = format!("{dir_rel}/dossier.md");
    let stages_rel = format!("{dir_rel}/stages.edn");
    if base_dir.join(&dir_rel).is_dir() {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "projection": "common.workflow/workflow$bootstrap-preview",
                "write-skipped?": true,
                "exists?": true,
                "dir": dir_rel,
                "dossier-path": dossier_rel,
                "stages-path": stages_rel,
            }))?
        );
        return Ok(());
    }

    let created = opts.created.unwrap_or_else(current_iso_utc);
    let purpose_md = format!("{}\n", opts.purpose);
    let acceptance_md =
        render_bootstrap_acceptance_md("Acceptance criteria (workflow-level)", &acceptance);
    let stages_data = serde_json::json!({
        "workflow/id": opts.id,
        "template-id": template_id,
        "created": created,
        "stages": stages,
    });
    let stages_edn = format!("{}\n", render_json_as_edn(&stages_data));
    let dossier_md = render_workflow_bootstrap_dossier(
        &opts.id,
        &template_id,
        &created,
        &hitl_mode,
        &opts.purpose,
        &acceptance,
        &stages,
    );
    let template_edn = render_workflow_bootstrap_template_edn(
        opts.template_edn.as_deref(),
        opts.template_path.as_deref(),
        &base_dir,
        &opts.id,
    )?;

    let files = serde_json::json!({
        "purpose.md": purpose_md,
        "acceptance.md": acceptance_md,
        "stages.edn": stages_edn,
        "dossier.md": dossier_md,
        "findings.log": "",
        "template.edn": template_edn,
    });
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "common.workflow/workflow$bootstrap-preview",
            "write-skipped?": true,
            "exists?": false,
            "dir": dir_rel,
            "dossier-path": dossier_rel,
            "stages-path": stages_rel,
            "dirs": ["artifacts/"],
            "files": files,
            "acceptance": acceptance,
            "stages": stages,
            "template-id": template_id,
            "hitl-mode": hitl_mode,
        }))?
    );
    Ok(())
}

