fn render_workflow_bootstrap_template_edn(
    template_edn: Option<&str>,
    template_path: Option<&Path>,
    base_dir: &Path,
    workflow_id: &str,
) -> Result<String> {
    if let Some(raw) = template_edn.filter(|value| !value.trim().is_empty()) {
        let parsed = parse_rlm_json_or_edn(raw).map_err(|error| {
            anyhow::anyhow!("failed to parse :template-edn as JSON or EDN: {error}")
        })?;
        return Ok(format!("{}\n", render_json_as_edn(&parsed)));
    }
    if let Some(path) = template_path {
        let resolved = if path.is_absolute() {
            path.to_path_buf()
        } else {
            base_dir.join(path)
        };
        if resolved.is_file() {
            return Ok(std::fs::read_to_string(resolved)?);
        }
        return Ok(String::new());
    }
    Ok(format!(
        "{}\n",
        render_json_as_edn(&serde_json::json!({
            "template": "ad-hoc",
            "workflow/id": workflow_id,
        }))
    ))
}

fn bootstrap_acceptance_parts(item: &serde_json::Value) -> (String, String, String) {
    let object = item.as_object();
    let id = object
        .and_then(|object| rlm_map_get(object, "id"))
        .map(bootstrap_string_value)
        .map(|value| normalize_keywordish(&value))
        .unwrap_or_default();
    let text = object
        .and_then(|object| rlm_map_get(object, "text"))
        .map(bootstrap_string_value)
        .unwrap_or_default();
    let status = object
        .and_then(|object| rlm_map_get(object, "status"))
        .map(bootstrap_string_value)
        .map(|value| normalize_keywordish(&value))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "open".to_string());
    (id, text, status)
}

fn bootstrap_stage_parts(item: &serde_json::Value) -> (String, String, String) {
    let object = item.as_object();
    let id = object
        .and_then(|object| rlm_map_get(object, "id"))
        .map(bootstrap_string_value)
        .map(|value| normalize_keywordish(&value))
        .unwrap_or_default();
    let agent = object
        .and_then(|object| rlm_map_get(object, "agent"))
        .map(bootstrap_string_value)
        .map(|value| normalize_keywordish(&value))
        .unwrap_or_default();
    let status = object
        .and_then(|object| rlm_map_get(object, "status"))
        .map(bootstrap_string_value)
        .map(|value| normalize_keywordish(&value))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "pending".to_string());
    (id, agent, status)
}

fn bootstrap_yaml_acceptance_block(acceptance: &[serde_json::Value]) -> String {
    let mut out = String::new();
    for item in acceptance {
        let (id, text, status) = bootstrap_acceptance_parts(item);
        out.push_str(&format!("  - id: {id}\n"));
        out.push_str(&format!("    text: {}\n", yaml_string(&text)));
        out.push_str(&format!("    status: {status}\n"));
    }
    out
}

fn bootstrap_yaml_direction_block(direction: &[String]) -> String {
    let mut out = String::new();
    for bullet in direction {
        out.push_str(&format!("  - {}\n", yaml_string(bullet)));
    }
    out
}

fn bootstrap_yaml_stages_summary_block(stages: &[serde_json::Value]) -> String {
    let mut out = String::new();
    for item in stages {
        let (id, agent, status) = bootstrap_stage_parts(item);
        out.push_str(&format!("  - id: {id}\n"));
        out.push_str(&format!("    agent: {agent}\n"));
        out.push_str(&format!("    status: {status}\n"));
        if let Some(object) = item.as_object() {
            if let Some(artifact) = rlm_map_get(object, "artifact").map(bootstrap_string_value) {
                out.push_str(&format!("    artifact: {}\n", yaml_string(&artifact)));
            }
            if let Some(plan_slug) = rlm_map_get(object, "plan-slug").map(bootstrap_string_value) {
                out.push_str(&format!("    plan_slug: {}\n", yaml_string(&plan_slug)));
            }
            if let Some(todo_slug) = rlm_map_get(object, "todo-slug").map(bootstrap_string_value) {
                out.push_str(&format!("    todo_slug: {}\n", yaml_string(&todo_slug)));
            }
        }
    }
    out
}

fn yaml_folded_scalar(value: &str) -> String {
    let collapsed = value.split_whitespace().collect::<Vec<_>>().join(" ");
    format!(">\n  {collapsed}")
}

fn print_workflow_append_log_preview(opts: WorkflowAppendLogPreviewOptions) -> Result<()> {
    if opts.id.trim().is_empty() {
        print_json_error(":id is required (string)")?;
        return Ok(());
    }
    let stage = normalize_keywordish(&opts.stage);
    if stage.trim().is_empty() {
        print_json_error(":stage is required (string or keyword)")?;
        return Ok(());
    }
    if opts.agent.trim().is_empty() {
        print_json_error(":agent is required (string)")?;
        return Ok(());
    }
    if opts.summary.trim().is_empty() {
        print_json_error(":summary is required (string)")?;
        return Ok(());
    }
    let pointers = match parse_preview_pointer_map(opts.pointers.as_deref(), "pointers") {
        Ok(pointers) => pointers,
        Err(error) => {
            print_json_error(&error)?;
            return Ok(());
        }
    };
    let base_dir = opts
        .base_dir
        .map(Ok)
        .unwrap_or_else(std::env::current_dir)?;
    let log_path = base_dir
        .join(WORKFLOW_RESULTS_BASE_REL)
        .join(&opts.id)
        .join("findings.log");
    if !log_path.is_file() {
        print_json_error(&format!(
            "findings.log not found at {WORKFLOW_RESULTS_BASE_REL}/{}/findings.log — run workflow$bootstrap first",
            opts.id
        ))?;
        return Ok(());
    }

    let mut entry = serde_json::Map::new();
    entry.insert("iter".to_string(), serde_json::json!(opts.iter));
    entry.insert("stage".to_string(), serde_json::json!(stage));
    entry.insert("agent".to_string(), serde_json::json!(opts.agent));
    entry.insert("summary".to_string(), serde_json::json!(opts.summary));
    if let Some(action) = opts.action {
        entry.insert("action".to_string(), serde_json::json!(action));
    }
    append_preview_pointer_fields(&mut entry, pointers);
    let line = format!(
        "{}\n",
        serde_json::to_string(&serde_json::Value::Object(entry.clone()))?
    );

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "common.workflow/workflow$append-log-preview",
            "write-skipped?": true,
            "existing?": true,
            "path": log_path.display().to_string(),
            "line": line,
            "entry": entry,
        }))?
    );
    Ok(())
}

