fn print_research_update_status_preview(
    id: String,
    criterion_id: String,
    status: String,
    base_dir: Option<PathBuf>,
) -> Result<()> {
    if id.trim().is_empty() {
        print_json_error(":id is required (string)")?;
        return Ok(());
    }
    let criterion_id = normalize_keywordish(&criterion_id);
    if criterion_id.trim().is_empty() {
        print_json_error(":criterion-id is required (string or keyword)")?;
        return Ok(());
    }
    let status = normalize_keywordish(&status);
    if !RESEARCH_CRITERION_STATUSES.contains(&status.as_str()) {
        print_json_error(&format!(
            ":status must be one of {}",
            workflow_status_error_list(RESEARCH_CRITERION_STATUSES)
        ))?;
        return Ok(());
    }
    let base_dir = base_dir.map(Ok).unwrap_or_else(std::env::current_dir)?;
    let dossier = base_dir
        .join(RESEARCH_RESULTS_BASE_REL)
        .join(&id)
        .join("dossier.md");
    if !dossier.is_file() {
        print_json_error(&format!("dossier.md not found for id {id}"))?;
        return Ok(());
    }
    let content = std::fs::read_to_string(&dossier)?;
    let pattern = format!(
        r"(?m)^(\s*-\s*id:\s*{}\s*\n\s+text:[^\n]*\n\s+status:\s*)(\S+)",
        regex::escape(&criterion_id)
    );
    let regex = regex::Regex::new(&pattern)?;
    let Some(captures) = regex.captures(&content) else {
        print_json_error(&format!("criterion {criterion_id} not found in dossier.md"))?;
        return Ok(());
    };
    let old_status = captures
        .get(2)
        .map(|value| normalize_keywordish(value.as_str()))
        .unwrap_or_else(|| "open".to_string());
    let replacement = format!("${{1}}{status}");
    let new_content = regex.replace(&content, replacement.as_str()).to_string();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "common.research/research$update-status-preview",
            "write-skipped?": true,
            "path": dossier.display().to_string(),
            "updated?": true,
            "criterion-id": criterion_id,
            "from": old_status,
            "to": status,
            "content": new_content,
        }))?
    );
    Ok(())
}

const WORKFLOW_TERMINAL_STATUSES: &[&str] = &["in-progress", "achieved", "partial", "abandoned"];
const RESEARCH_TERMINAL_STATUSES: &[&str] = &["achieved", "partial", "abandoned"];
const WORKFLOW_STAGE_STATUSES: &[&str] = &[
    "pending",
    "in-progress",
    "satisfied",
    "failed",
    "skipped",
    "abandoned",
];
const WORKFLOW_TERMINAL_STAGE_STATUSES: &[&str] = &["satisfied", "failed", "skipped", "abandoned"];
const WORKFLOW_CRITERION_STATUSES: &[&str] =
    &["open", "satisfied", "partial", "descoped", "contradicted"];
const RESEARCH_CRITERION_STATUSES: &[&str] =
    &["open", "satisfied", "partial", "descoped", "contradicted"];
const WORKFLOW_HITL_MODES: &[&str] = &["auto", "gates", "checkpoint", "co-pilot", "step"];

fn parse_preview_pointer_map(
    raw: Option<&str>,
    label: &str,
) -> std::result::Result<serde_json::Map<String, serde_json::Value>, String> {
    let Some(raw) = raw.filter(|value| !value.trim().is_empty()) else {
        return Ok(serde_json::Map::new());
    };
    let parsed = parse_rlm_json_or_edn(raw)
        .map_err(|error| format!("failed to parse :{label} as JSON or EDN: {error}"))?;
    let Some(object) = parsed.as_object() else {
        return Err(format!(":{label} must be a map/object"));
    };
    Ok(object.clone())
}

fn append_preview_pointer_fields(
    entry: &mut serde_json::Map<String, serde_json::Value>,
    pointers: serde_json::Map<String, serde_json::Value>,
) {
    for (key, value) in pointers {
        entry.insert(normalize_keywordish(&key), value);
    }
}

fn normalize_terminal_status(value: &str, allowed: &[&str]) -> Option<String> {
    let status = normalize_keywordish(value);
    allowed.contains(&status.as_str()).then_some(status)
}

fn workflow_status_error_list(allowed: &[&str]) -> String {
    allowed.join(", ")
}

fn json_i64_from_scalar(value: &serde_json::Value) -> Option<i64> {
    value
        .as_i64()
        .or_else(|| json_scalar_string(value).and_then(|scalar| scalar.trim().parse::<i64>().ok()))
}

fn read_workflow_stages_json_data(path: &Path) -> Result<Option<serde_json::Value>> {
    if !path.is_file() {
        return Ok(None);
    }
    let content = std::fs::read_to_string(path)?;
    let Ok(value) = by_contracts::parse_value(&content) else {
        return Ok(None);
    };
    let by_contracts::EdnValue::Map(map) = value else {
        return Ok(None);
    };
    Ok(Some(edn_map_to_json(&map)))
}

fn render_json_as_edn(value: &serde_json::Value) -> String {
    render_json_as_edn_for_key(None, value)
}

fn render_json_as_edn_for_key(parent_key: Option<&str>, value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => "nil".to_string(),
        serde_json::Value::Bool(value) => value.to_string(),
        serde_json::Value::Number(value) => value.to_string(),
        serde_json::Value::String(value) => {
            if should_render_edn_keyword(parent_key, value) {
                format!(":{}", normalize_keywordish(value))
            } else {
                serde_json::to_string(value).unwrap_or_else(|_| format!("{value:?}"))
            }
        }
        serde_json::Value::Array(values) => format!(
            "[{}]",
            values
                .iter()
                .map(|value| render_json_as_edn_for_key(None, value))
                .collect::<Vec<_>>()
                .join(" ")
        ),
        serde_json::Value::Object(object) => {
            let entries = object
                .iter()
                .map(|(key, value)| {
                    format!(":{} {}", key, render_json_as_edn_for_key(Some(key), value))
                })
                .collect::<Vec<_>>()
                .join(" ");
            format!("{{{entries}}}")
        }
    }
}

fn should_render_edn_keyword(parent_key: Option<&str>, value: &str) -> bool {
    let Some(parent_key) = parent_key else {
        return false;
    };
    matches!(
        parent_key,
        "agent" | "id" | "status" | "template" | "template-id"
    ) && edn_keyword_token(&normalize_keywordish(value))
}

fn edn_keyword_token(value: &str) -> bool {
    !value.is_empty()
        && value
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '/' | '?' | '!'))
}

fn block_mismatched_terminal_claim(
    status: &str,
    acceptance: &serde_json::Value,
    update_tool: &str,
) -> Option<String> {
    if status != "achieved" {
        return None;
    }
    let bad = acceptance
        .as_object()
        .map(|object| {
            object
                .iter()
                .filter_map(|(id, value)| {
                    let status = json_scalar_string(value)
                        .map(|value| normalize_keywordish(&value))
                        .unwrap_or_else(|| "open".to_string());
                    (!matches!(status.as_str(), "satisfied" | "descoped"))
                        .then(|| format!("{id}:{status}"))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    if bad.is_empty() {
        None
    } else {
        Some(format!(
            ":achieved requires every criterion to be :satisfied or :descoped; the following are not: {}. Call {update_tool} to flip each criterion's status before writing the verdict, or use :partial / :abandoned instead.",
            bad.join(", ")
        ))
    }
}

fn read_workflow_stage_pairs(path: &Path) -> Result<Vec<serde_json::Value>> {
    let stages = read_workflow_stages(path)?;
    Ok(stages
        .into_iter()
        .filter_map(|stage| {
            let object = stage.as_object()?;
            let id = object
                .get("id")
                .and_then(json_scalar_string)
                .map(|value| normalize_keywordish(&value))
                .unwrap_or_else(|| "_unknown".to_string());
            let status = object
                .get("status")
                .and_then(json_scalar_string)
                .map(|value| normalize_keywordish(&value))
                .unwrap_or_else(|| "pending".to_string());
            Some(serde_json::json!([id, status]))
        })
        .collect())
}

#[allow(clippy::too_many_arguments)]
fn render_workflow_verdict_content(
    id: &str,
    template_id: Option<&str>,
    status: &str,
    terminated: &str,
    iterations: Option<i64>,
    acceptance: &serde_json::Value,
    stages: &[serde_json::Value],
    narrative: &str,
) -> String {
    let mut content = String::from("---\n");
    content.push_str(&format!("workflow_id: {id}\n"));
    if let Some(template_id) = template_id.filter(|value| !value.trim().is_empty()) {
        content.push_str(&format!("workflow_template: {template_id}\n"));
    }
    content.push_str(&format!("status: {status}\n"));
    content.push_str(&format!("terminated: {terminated}\n"));
    if let Some(iterations) = iterations {
        content.push_str(&format!("iterations: {iterations}\n"));
    }
    push_acceptance_outcome_block(&mut content, acceptance);
    push_stage_outcomes_block(&mut content, stages);
    content.push_str("---\n\n## Verdict\n");
    content.push_str(strip_leading_verdict_heading(narrative, true).trim());
    content.push('\n');
    content
}

fn render_research_verdict_content(
    id: &str,
    status: &str,
    terminated: &str,
    iterations: Option<i64>,
    acceptance: &serde_json::Value,
    narrative: &str,
) -> String {
    let mut content = String::from("---\n");
    content.push_str(&format!("research_id: {id}\n"));
    content.push_str(&format!("status: {status}\n"));
    content.push_str(&format!("terminated: {terminated}\n"));
    if let Some(iterations) = iterations {
        content.push_str(&format!("iterations: {iterations}\n"));
    }
    push_acceptance_outcome_block(&mut content, acceptance);
    content.push_str("---\n\n## Verdict\n");
    content.push_str(strip_leading_verdict_heading(narrative, false).trim());
    content.push('\n');
    content
}

fn push_acceptance_outcome_block(content: &mut String, acceptance: &serde_json::Value) {
    let Some(object) = acceptance.as_object() else {
        return;
    };
    if object.is_empty() {
        return;
    }
    content.push_str("acceptance_outcome:\n");
    for (id, status) in object {
        let status = json_scalar_string(status)
            .map(|value| normalize_keywordish(&value))
            .unwrap_or_else(|| "open".to_string());
        content.push_str(&format!("  {id}: {status}\n"));
    }
}

fn push_stage_outcomes_block(content: &mut String, stages: &[serde_json::Value]) {
    if stages.is_empty() {
        return;
    }
    content.push_str("stage_outcomes:\n");
    for stage in stages {
        let Some(items) = stage.as_array() else {
            continue;
        };
        let id = items
            .first()
            .and_then(json_scalar_string)
            .map(|value| normalize_keywordish(&value))
            .unwrap_or_else(|| "_unknown".to_string());
        let status = items
            .get(1)
            .and_then(json_scalar_string)
            .map(|value| normalize_keywordish(&value))
            .unwrap_or_else(|| "pending".to_string());
        content.push_str(&format!("  {id}: {status}\n"));
    }
}

fn strip_leading_verdict_heading(narrative: &str, workflow: bool) -> String {
    let pattern = if workflow {
        r"(?i)\A#+\s*(Workflow\s+)?Verdict\s*\n+"
    } else {
        r"(?i)\A#+\s*Verdict\s*\n+"
    };
    regex::Regex::new(pattern)
        .map(|regex| regex.replace(narrative, "").to_string())
        .unwrap_or_else(|_| narrative.to_string())
}

