fn print_chart_create_plotly(
    data: Option<String>,
    layout: Option<String>,
    title: Option<String>,
) -> Result<()> {
    let data = match data.as_deref() {
        Some(raw) => match parse_rlm_json_or_edn(raw) {
            Ok(value) => value,
            Err(error) => {
                return print_chart_projection_error(
                    "chart-command/create-plotly",
                    "data",
                    format!("failed to parse --data: {error}"),
                );
            }
        },
        None => serde_json::json!([]),
    };
    let layout = match layout.as_deref() {
        Some(raw) => match parse_rlm_json_or_edn(raw) {
            Ok(serde_json::Value::Object(object)) => serde_json::Value::Object(object),
            Ok(_) => {
                return print_chart_projection_error(
                    "chart-command/create-plotly",
                    "layout",
                    "--layout must be an object/map",
                );
            }
            Err(error) => {
                return print_chart_projection_error(
                    "chart-command/create-plotly",
                    "layout",
                    format!("failed to parse --layout: {error}"),
                );
            }
        },
        None => serde_json::json!({}),
    };

    let layout = chart_plotly_layout(layout, title.clone());
    let spec = serde_json::json!({
        "data": data,
        "layout": layout,
    });
    let trace_count = chart_trace_count(&spec["data"]);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "artifact-type": "chart",
            "artifact-data": {
                "chart-spec": spec,
                "format": "plotly",
            },
            "summary": format!(
                "Created {} with {} trace(s)",
                title.as_deref().unwrap_or("chart"),
                trace_count,
            ),
            "projection": "chart-command/create-plotly",
            "render-skipped?": true,
            "write-skipped?": true,
        }))?
    );
    Ok(())
}

fn print_chart_export_html_preview(
    chart_spec: String,
    filepath: Option<String>,
    timestamp_ms: i64,
) -> Result<()> {
    let chart_spec = match parse_rlm_json_or_edn(&chart_spec) {
        Ok(value) => value,
        Err(error) => {
            return print_chart_projection_error(
                "chart-command/export-html-preview",
                "chart-spec",
                format!("failed to parse --chart-spec: {error}"),
            );
        }
    };
    let filepath = filepath.unwrap_or_else(|| format!("/tmp/chart-{timestamp_ms}.html"));
    let spec_json = serde_json::to_string(&chart_spec)?;
    let html = chart_plotly_html(&spec_json);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "success": true,
            "filepath": filepath,
            "size": html.len(),
            "html": html,
            "projection": "chart-command/export-html-preview",
            "write-skipped?": true,
        }))?
    );
    Ok(())
}

fn print_chart_projection_error(
    projection: &str,
    stage: &str,
    error: impl Into<String>,
) -> Result<()> {
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "success": false,
            "ok?": false,
            "stage": stage,
            "error": error.into(),
            "projection": projection,
            "write-skipped?": true,
        }))?
    );
    Ok(())
}

fn chart_plotly_layout(layout: serde_json::Value, title: Option<String>) -> serde_json::Value {
    let mut object = serde_json::Map::new();
    object.insert("template".to_string(), serde_json::json!("plotly_dark"));
    object.insert(
        "paper_bgcolor".to_string(),
        serde_json::json!("rgba(0,0,0,0)"),
    );
    object.insert(
        "plot_bgcolor".to_string(),
        serde_json::json!("rgba(0,0,0,0)"),
    );
    object.insert("font".to_string(), serde_json::json!({ "color": "#ccc" }));
    if let serde_json::Value::Object(layout) = layout {
        for (key, value) in layout {
            object.insert(key, value);
        }
    }
    if let Some(title) = title {
        object.insert("title".to_string(), serde_json::json!(title));
    }
    serde_json::Value::Object(object)
}

fn chart_trace_count(data: &serde_json::Value) -> usize {
    match data {
        serde_json::Value::Array(items) => items.len(),
        serde_json::Value::Object(items) => items.len(),
        serde_json::Value::Null => 0,
        _ => 1,
    }
}

fn chart_plotly_html(spec_json: &str) -> String {
    format!(
        "<!DOCTYPE html>\n<html><head>\n<script src='https://cdn.plot.ly/plotly-2.32.0.min.js'></script>\n<style>body{{margin:0;padding:16px;font-family:sans-serif;background:#1a1a2e;}}\n#chart{{width:100%;height:90vh;}}</style>\n</head><body>\n<div id='chart'></div>\n<script>\nvar spec = {spec_json};\nPlotly.newPlot('chart', spec.data, spec.layout, {{responsive: true}});\n</script></body></html>"
    )
}

fn print_chart_recommend_type(
    description: Option<String>,
    data_shape: Option<String>,
) -> Result<()> {
    let joined = format!(
        "{} {}",
        description.unwrap_or_default(),
        data_shape.unwrap_or_default()
    );
    let (recommended, reason) = chart_recommendation(&joined);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "recommended": recommended,
            "reason": reason,
        }))?
    );
    Ok(())
}

fn chart_recommendation(description: &str) -> (&'static str, &'static str) {
    let description = description.to_ascii_lowercase();
    if text_contains_any(&description, &["time", "trend", "series", "over time"]) {
        ("line", "Time-series data is best shown as a line chart")
    } else if text_contains_any(
        &description,
        &["compar", "categor", "group", "versus", "vs"],
    ) {
        ("bar", "Categorical comparisons work well with bar charts")
    } else if text_contains_any(
        &description,
        &["proportion", "percent", "share", "composition", "breakdown"],
    ) {
        ("pie", "Proportional data is best shown as a pie chart")
    } else if text_contains_any(&description, &["distribut", "spread", "range", "quartile"]) {
        ("box", "Distribution data is best shown as a box plot")
    } else if text_contains_any(&description, &["correlat", "relationship", "scatter", "xy"]) {
        (
            "scatter",
            "Variable relationships work well with scatter plots",
        )
    } else if text_contains_any(&description, &["matrix", "grid", "heat"]) {
        ("heatmap", "Matrix data is best shown as a heatmap")
    } else if text_contains_any(&description, &["hierarch", "tree", "nested"]) {
        ("treemap", "Hierarchical data is best shown as a treemap")
    } else if text_contains_any(&description, &["cumulat", "stack", "area"]) {
        ("area", "Cumulative data works well with area charts")
    } else {
        ("bar", "Bar chart is a versatile default for most data")
    }
}

struct EmailPreflightOptions {
    to: String,
    subject: String,
    body: Option<String>,
    cc: Option<String>,
    bcc: Option<String>,
    html: Option<String>,
    sender: Option<String>,
    sender_name: Option<String>,
    reply_to: Option<String>,
}

fn print_email_validate_address(email: String) -> Result<()> {
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "email-command/valid-email",
            "email": email,
            "valid?": email_valid_address(&email),
        }))?
    );
    Ok(())
}

fn print_email_send_preflight(opts: EmailPreflightOptions) -> Result<()> {
    if !email_valid_address(&opts.to) {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "success": false,
                "ok?": false,
                "error": format!("Invalid email address: {}", opts.to),
                "projection": "email-command/send-email-preflight",
                "ses-skipped?": true,
            }))?
        );
        return Ok(());
    }

    if opts.subject.trim().is_empty() {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "success": false,
                "ok?": false,
                "error": "Subject is required",
                "projection": "email-command/send-email-preflight",
                "ses-skipped?": true,
            }))?
        );
        return Ok(());
    }

    let sender = email_resolve_sender(opts.sender, opts.sender_name);
    let reply_to = opts
        .reply_to
        .or_else(|| std::env::var("MAIL_REPLY_TO").ok());
    let body_content = match opts.html {
        Some(html) => serde_json::json!({
            "html": html,
            "text": opts.body.unwrap_or_default(),
        }),
        None => serde_json::json!(opts.body.unwrap_or_default()),
    };

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "success": true,
            "ok?": true,
            "to": opts.to,
            "subject": opts.subject,
            "sender": sender,
            "body-content": body_content,
            "cc": email_singleton_array(opts.cc),
            "bcc": email_singleton_array(opts.bcc),
            "reply-to": email_singleton_array(reply_to),
            "projection": "email-command/send-email-preflight",
            "ses-skipped?": true,
        }))?
    );
    Ok(())
}

fn print_email_notification_preview(
    to: Option<String>,
    subject: String,
    title: Option<String>,
    message: String,
    severity: Option<String>,
) -> Result<()> {
    let severity = severity.unwrap_or_else(|| "info".to_string());
    let background = match severity.as_str() {
        "error" => "#fee2e2",
        "warning" => "#fef3c7",
        _ => "#dbeafe",
    };
    let title = title.unwrap_or_else(|| subject.clone());
    let html = format!(
        "<div style='font-family:sans-serif;max-width:600px;margin:auto;'><div style='padding:16px;background:{background};'><h2>{title}</h2></div><div style='padding:16px;'><p>{message}</p></div></div>"
    );
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "success": true,
            "ok?": true,
            "to": to,
            "subject": subject,
            "title": title,
            "message": message,
            "severity": severity,
            "body-content": {
                "html": html,
                "text": message,
            },
            "projection": "email-command/send-notification-preview",
            "ses-skipped?": true,
        }))?
    );
    Ok(())
}

fn print_email_verify_config_preview(
    identities: Option<String>,
    sender: Option<String>,
    sender_name: Option<String>,
    region: Option<String>,
) -> Result<()> {
    let sender = email_resolve_sender(sender, sender_name);
    let region = region
        .or_else(|| std::env::var("AWS_REGION").ok())
        .unwrap_or_else(|| "us-east-1".to_string());
    let Some(raw_identities) = identities else {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "projection": "email-command/verify-config-preview",
                "configured": false,
                "error": "AWS SES client not available",
                "sender": sender,
                "region": region,
                "ses-skipped?": true,
            }))?
        );
        return Ok(());
    };
    let Some(identities) = email_parse_fixture_array(
        raw_identities,
        "email-identities",
        "--identities",
        "email-command/verify-config-preview",
    )?
    else {
        return Ok(());
    };
    let identity_names = identities
        .iter()
        .filter_map(email_identity_name)
        .collect::<Vec<_>>();
    let sender_verified = identity_names.iter().any(|identity| identity == &sender);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "email-command/verify-config-preview",
            "configured": true,
            "sender": sender,
            "sender-verified": sender_verified,
            "region": region,
            "identity-count": identity_names.len(),
            "identities": identity_names,
            "ses-skipped?": true,
        }))?
    );
    Ok(())
}

