fn print_slack_send_preflight(opts: SlackSendPreflightOptions) -> Result<()> {
    let token = match slack_resolve_token(opts.token, opts.agent_config) {
        Ok(token) => token,
        Err(error) => {
            return print_slack_projection_error("slack-command/send-message-preflight", error)
        }
    };
    let Some(token_value) = token.token.as_deref() else {
        return print_slack_projection_error(
            "slack-command/send-message-preflight",
            "SLACK_BOT_TOKEN not configured",
        );
    };
    let Some((channels, users)) = slack_parse_recipient_fixtures(
        opts.channels,
        opts.users,
        "slack-command/send-message-preflight",
    )?
    else {
        return Ok(());
    };
    let resolved =
        match slack_resolve_recipient(&opts.recipient, channels.as_deref(), users.as_deref()) {
            Ok(resolved) => resolved,
            Err(error) => {
                return print_slack_projection_error("slack-command/send-message-preflight", error)
            }
        };

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "success": true,
            "ok?": true,
            "channel": resolved.id,
            "recipient-type": resolved.type_,
            "display-name": resolved.display_name,
            "message": opts.message,
            "thread-ts": opts.thread_ts,
            "token-source": token.source,
            "masked-token": slack_mask_token(token_value),
            "projection": "slack-command/send-message-preflight",
            "post-skipped?": true,
        }))?
    );
    Ok(())
}

