fn print_slack_verify_token_preview(
    token: Option<String>,
    agent_config: Option<String>,
    auth_test: Option<String>,
) -> Result<()> {
    let token = match slack_resolve_token(token, agent_config) {
        Ok(token) => token,
        Err(error) => {
            return print_slack_projection_error("slack-command/verify-token-preview", error)
        }
    };
    let Some(token_value) = token.token.as_deref() else {
        return print_slack_projection_error(
            "slack-command/verify-token-preview",
            "SLACK_BOT_TOKEN not configured",
        );
    };
    let Some(raw_auth_test) = auth_test else {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "success": false,
                "ok?": false,
                "error": "Slack component not available",
                "token-source": token.source,
                "masked-token": slack_mask_token(token_value),
                "projection": "slack-command/verify-token-preview",
                "auth-test-skipped?": true,
                "api-skipped?": true,
            }))?
        );
        return Ok(());
    };
    let value = match parse_rlm_json_or_edn(&raw_auth_test) {
        Ok(value) => value,
        Err(error) => {
            return print_slack_projection_error(
                "slack-command/verify-token-preview",
                format!("failed to parse --auth-test: {error}"),
            )
        }
    };
    let Some(map) = value.as_object() else {
        return print_slack_projection_error(
            "slack-command/verify-token-preview",
            "--auth-test must be a map/object",
        );
    };
    if slack_map_bool(map, &["ok"]).is_some_and(|ok| !ok) {
        let detail =
            slack_map_string(map, &["error"]).unwrap_or_else(|| "auth.test failed".to_string());
        return print_slack_projection_error(
            "slack-command/verify-token-preview",
            format!("Token verification failed: {detail}"),
        );
    }
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "ok": true,
            "ok?": true,
            "bot-id": slack_map_string(map, &["bot_id", "bot-id"]),
            "team": slack_map_string(map, &["team"]),
            "user": slack_map_string(map, &["user"]),
            "token-source": token.source,
            "masked-token": slack_mask_token(token_value),
            "projection": "slack-command/verify-token-preview",
            "auth-test-skipped?": true,
        }))?
    );
    Ok(())
}

