fn print_sandbox_list(category: Option<String>, query: Option<String>) -> Result<()> {
    let category = category
        .as_deref()
        .map(normalize_keywordish)
        .filter(|value| !value.trim().is_empty());
    let query = query
        .as_deref()
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty());
    let functions = sandbox_functions_filtered(category.as_deref(), query.as_deref())
        .into_iter()
        .map(sandbox_function_json)
        .collect::<Vec<_>>();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "functions": functions,
            "count": functions.len(),
        }))?
    );
    Ok(())
}

fn print_sandbox_read(name: String) -> Result<()> {
    let name = name.trim();
    if name.is_empty() {
        print_json_error(":name is required (string)")?;
        return Ok(());
    }
    let Some(function) = SANDBOX_FUNCTIONS
        .iter()
        .copied()
        .find(|function| function.name == name)
    else {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "not-found": true,
                "name": name,
            }))?
        );
        return Ok(());
    };
    println!(
        "{}",
        serde_json::to_string_pretty(&sandbox_function_json(function))?
    );
    Ok(())
}

fn print_sandbox_menu() -> Result<()> {
    let menu_items = SANDBOX_FUNCTIONS
        .iter()
        .map(|function| {
            serde_json::json!([
                format!("/sandbox {}", function.name),
                format!("({}) {}", function.category, function.description),
            ])
        })
        .collect::<Vec<_>>();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "menu-items": menu_items,
            "count": menu_items.len(),
        }))?
    );
    Ok(())
}

fn print_sandbox_help() -> Result<()> {
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "help": format_sandbox_help(),
        }))?
    );
    Ok(())
}

fn sandbox_functions_filtered(category: Option<&str>, query: Option<&str>) -> Vec<SandboxFunction> {
    SANDBOX_FUNCTIONS
        .iter()
        .copied()
        .filter(|function| {
            category.is_none_or(|category| normalize_keywordish(function.category) == category)
        })
        .filter(|function| {
            query.is_none_or(|query| {
                function.name.to_ascii_lowercase().contains(query)
                    || function.description.to_ascii_lowercase().contains(query)
            })
        })
        .collect()
}

fn sandbox_function_json(function: SandboxFunction) -> serde_json::Value {
    serde_json::json!({
        "name": function.name,
        "category": function.category,
        "description": function.description,
        "args": function.args.unwrap_or("none"),
        "code-template": function.code_template,
    })
}

fn format_sandbox_help() -> String {
    const CATEGORY_ORDER: &[&str] = &[
        "context",
        "knowledge",
        "tools",
        "mcp",
        "doc",
        "skill",
        "inspect",
        "memory",
        "config",
        "file",
        "exec",
    ];
    let mut sections = Vec::new();
    for category in CATEGORY_ORDER {
        let functions = SANDBOX_FUNCTIONS
            .iter()
            .filter(|function| function.category == *category)
            .collect::<Vec<_>>();
        if functions.is_empty() {
            continue;
        }
        let mut section = format!("  [{category}]");
        for function in functions {
            let args = function
                .args
                .map_or(String::new(), |args| format!(" {args}"));
            section.push_str(&format!(
                "\n    {}{}  — {}",
                function.name, args, function.description
            ));
        }
        sections.push(section);
    }
    format!("Sandbox Functions:\n{}", sections.join("\n"))
}

