fn print_delegation_use_tree(
    id_prefix: String,
    question_key: String,
    result_key: String,
    rewrite_signature: Option<String>,
    describe_signature: String,
) -> Result<()> {
    let id_prefix = normalize_keywordish(&id_prefix);
    let question_key = normalize_keywordish(&question_key);
    let result_key = normalize_keywordish(&result_key);
    let rewrite_signature = rewrite_signature
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToString::to_string);
    let describe_signature = describe_signature.trim().to_string();
    let seq_id = format!("{id_prefix}.sequence/{result_key}");
    let rewrite_id = format!("{id_prefix}.action/rewrite-question");
    let ask_id = format!("{id_prefix}.action/ask-agent");
    let describe_id = format!("{id_prefix}.action/describe-result");

    let mut tree = vec![
        serde_json::Value::String("sequence".to_string()),
        serde_json::json!({"id": seq_id}),
    ];
    if let Some(signature) = &rewrite_signature {
        tree.push(serde_json::json!([
            "action",
            {
                "id": rewrite_id,
                "signature": signature,
                "operation": "chain-of-thought",
                "debug": {"source": "reasoning"},
            },
            "dspy-fn"
        ]));
    }
    tree.push(serde_json::json!(["action", {"id": ask_id}, "ask-agent-fn"]));
    tree.push(serde_json::json!([
        "action",
        {
            "id": describe_id,
            "signature": describe_signature,
            "operation": "chain-of-thought",
            "debug": {"source": "reasoning"},
        },
        "dspy-fn"
    ]));

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "common.delegation-use/delegation-use",
            "tree": tree,
            "question-key": question_key,
            "result-key": result_key,
            "node-ids": {
                "sequence": format!("{id_prefix}.sequence/{result_key}"),
                "rewrite": rewrite_signature.as_ref().map(|_| format!("{id_prefix}.action/rewrite-question")),
                "ask": format!("{id_prefix}.action/ask-agent"),
                "describe": format!("{id_prefix}.action/describe-result"),
            },
            "rewrite-skipped?": rewrite_signature.is_none(),
            "calls-skipped?": true,
        }))?
    );
    Ok(())
}

#[derive(Debug)]
struct WorkflowTemplateSource {
    source: &'static str,
    display_path: String,
    content: String,
}

fn resolve_workflow_template_source(
    id: Option<&str>,
    path: Option<&Path>,
    base_dir: &Path,
    user_dir: Option<PathBuf>,
) -> Result<Option<WorkflowTemplateSource>> {
    if let Some(path) = path {
        let resolved = if path.is_absolute() {
            path.to_path_buf()
        } else {
            base_dir.join(path)
        };
        if resolved.is_file() {
            return Ok(Some(WorkflowTemplateSource {
                source: "explicit",
                display_path: resolved.display().to_string(),
                content: std::fs::read_to_string(resolved)?,
            }));
        }
        return Ok(None);
    }

    let Some(id) = id
        .map(normalize_keywordish)
        .filter(|value| !value.is_empty())
    else {
        return Ok(None);
    };
    let filename = format!("{id}.edn");
    let project_path = base_dir.join(WORKFLOW_TEMPLATES_REL).join(&filename);
    if project_path.is_file() {
        return Ok(Some(WorkflowTemplateSource {
            source: "project",
            display_path: project_path.display().to_string(),
            content: std::fs::read_to_string(project_path)?,
        }));
    }
    if let Some(user_dir) = resolve_workflow_user_dir(user_dir) {
        let user_path = user_dir.join(WORKFLOW_TEMPLATES_REL).join(&filename);
        if user_path.is_file() {
            return Ok(Some(WorkflowTemplateSource {
                source: "user",
                display_path: user_path.display().to_string(),
                content: std::fs::read_to_string(user_path)?,
            }));
        }
    }
    BUILTIN_WORKFLOW_TEMPLATES
        .iter()
        .find(|(builtin_id, _)| *builtin_id == id)
        .map(|(builtin_id, content)| {
            Ok(WorkflowTemplateSource {
                source: "built-in",
                display_path: format!("classpath:workflows/{builtin_id}.edn"),
                content: (*content).to_string(),
            })
        })
        .transpose()
}

fn resolve_workflow_user_dir(user_dir: Option<PathBuf>) -> Option<PathBuf> {
    user_dir.or_else(|| std::env::var_os("HOME").map(PathBuf::from))
}

fn read_workflow_template_dir(dir: &Path, source: &'static str) -> Result<Vec<serde_json::Value>> {
    if !dir.is_dir() {
        return Ok(Vec::new());
    }
    let mut files = std::fs::read_dir(dir)?
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.path())
        .filter(|path| path.is_file() && path.extension().is_some_and(|ext| ext == "edn"))
        .collect::<Vec<_>>();
    files.sort();

    let mut templates = Vec::new();
    for path in files {
        if let Ok(content) = std::fs::read_to_string(&path) {
            templates.push(workflow_template_meta_from_content(
                &content,
                source,
                &path.display().to_string(),
                None,
                path.file_stem().and_then(|stem| stem.to_str()),
            ));
        }
    }
    Ok(templates)
}

fn workflow_template_meta_from_content(
    content: &str,
    source: &'static str,
    display_path: &str,
    resource: Option<&str>,
    fallback_id: Option<&str>,
) -> serde_json::Value {
    let parsed = parse_workflow_template(content, display_path).ok();
    let object = parsed.as_ref().and_then(|value| value.as_object());
    let id = object
        .and_then(|object| json_string_field(object, "workflow/id"))
        .unwrap_or_else(|| fallback_id.unwrap_or("unknown").to_string());
    let name = object
        .and_then(|object| json_string_field(object, "workflow/name"))
        .unwrap_or_else(|| id.clone());
    let description = object.and_then(|object| json_string_field(object, "workflow/description"));
    let mut result = serde_json::Map::new();
    result.insert("id".to_string(), serde_json::json!(id));
    result.insert("name".to_string(), serde_json::json!(name));
    result.insert(
        "description".to_string(),
        description.map_or(serde_json::Value::Null, serde_json::Value::String),
    );
    result.insert("source".to_string(), serde_json::json!(source));
    if let Some(resource) = resource {
        result.insert("resource".to_string(), serde_json::json!(resource));
    } else {
        result.insert("path".to_string(), serde_json::json!(display_path));
    }
    serde_json::Value::Object(result)
}

fn parse_workflow_template(
    content: &str,
    display_path: &str,
) -> std::result::Result<serde_json::Value, String> {
    let value = by_contracts::parse_value(content)
        .map_err(|error| format!("failed to read template: {error}"))?;
    let by_contracts::EdnValue::Map(map) = value else {
        return Err(format!(
            "invalid template at {display_path}: template is not a map"
        ));
    };
    let json = edn_map_to_json(&map);
    let Some(object) = json.as_object() else {
        return Err(format!(
            "invalid template at {display_path}: template is not a map"
        ));
    };
    match object.get("workflow/id") {
        Some(serde_json::Value::String(value)) if !value.trim().is_empty() => {}
        _ => {
            return Err(format!(
                "invalid template at {display_path}: :workflow/id must be a keyword"
            ))
        }
    }
    match object.get("workflow/name") {
        Some(serde_json::Value::String(_)) => {}
        _ => {
            return Err(format!(
                "invalid template at {display_path}: :workflow/name must be a string"
            ))
        }
    }
    match object.get("stages") {
        Some(serde_json::Value::Array(values))
            if values.iter().all(|value| value.as_object().is_some()) => {}
        _ => {
            return Err(format!(
                "invalid template at {display_path}: :stages must be a vector of maps"
            ))
        }
    }
    match object.get("acceptance") {
        Some(serde_json::Value::Array(values))
            if values.iter().all(|value| value.as_object().is_some()) => {}
        _ => {
            return Err(format!(
                "invalid template at {display_path}: :acceptance must be a vector of maps"
            ))
        }
    }
    Ok(json)
}

fn read_workflow_stages(path: &Path) -> Result<Vec<serde_json::Value>> {
    if !path.is_file() {
        return Ok(Vec::new());
    }
    let content = std::fs::read_to_string(path)?;
    let Ok(value) = by_contracts::parse_value(&content) else {
        return Ok(Vec::new());
    };
    let by_contracts::EdnValue::Map(map) = value else {
        return Ok(Vec::new());
    };
    let json = edn_map_to_json(&map);
    Ok(json
        .get("stages")
        .and_then(|value| value.as_array())
        .cloned()
        .unwrap_or_default())
}

fn workflow_frontmatter_scalar(lines: &[String], key: &str) -> Option<String> {
    lines.iter().find_map(|line| {
        let (candidate, value) = line.split_once(':')?;
        if candidate.trim() != key {
            return None;
        }
        let value = parse_dossier_yaml_scalar(value);
        value
            .as_str()
            .map(normalize_keywordish)
            .or_else(|| value.as_i64().map(|value| value.to_string()))
    })
}

fn parse_workflow_acceptance_state(lines: &[String]) -> serde_json::Value {
    let mut state = serde_json::Map::new();
    let mut in_acceptance = false;
    let mut pending_id: Option<String> = None;
    let mut pending_status: Option<String> = None;

    for line in lines {
        let trimmed = line.trim_end();
        if trimmed == "acceptance:" {
            in_acceptance = true;
            pending_id = None;
            pending_status = None;
            continue;
        }
        if !in_acceptance {
            continue;
        }
        if !line.starts_with(char::is_whitespace) && !trimmed.is_empty() {
            if let Some(id) = pending_id.take() {
                state.insert(
                    id,
                    serde_json::json!(pending_status.take().unwrap_or_else(|| "open".to_string())),
                );
            }
            break;
        }
        if let Some(value) = trimmed.trim().strip_prefix("- id:") {
            if let Some(id) = pending_id.take() {
                state.insert(
                    id,
                    serde_json::json!(pending_status.take().unwrap_or_else(|| "open".to_string())),
                );
            }
            pending_id = Some(normalize_keywordish(value.trim()));
            continue;
        }
        if let Some(value) = trimmed.trim().strip_prefix("status:") {
            pending_status = Some(normalize_keywordish(value.trim()));
        }
    }
    if let Some(id) = pending_id.take() {
        state.insert(
            id,
            serde_json::json!(pending_status.unwrap_or_else(|| "open".to_string())),
        );
    }
    serde_json::Value::Object(state)
}

fn workflow_slugify(value: &str, max_chars: usize) -> String {
    const WORKFLOW_STOPWORDS: [&str; 64] = [
        "a", "an", "the", "is", "are", "and", "or", "of", "in", "on", "at", "to", "for", "by",
        "with", "from", "as", "but", "if", "then", "than", "so", "what", "where", "when", "who",
        "whom", "why", "how", "which", "do", "does", "did", "can", "could", "would", "should",
        "shall", "will", "this", "that", "these", "those", "it", "its", "we", "they", "you", "i",
        "be", "been", "being", "was", "were", "have", "has", "had", "run", "runs", "running",
        "ship", "ships", "shipped", "shipping",
    ];
    common_agent_slugify(value, max_chars, "workflow", &WORKFLOW_STOPWORDS)
}

fn research_slugify(value: &str, max_chars: usize) -> String {
    const RESEARCH_STOPWORDS: [&str; 57] = [
        "a", "an", "the", "is", "are", "and", "or", "of", "in", "on", "at", "to", "for", "by",
        "with", "from", "as", "but", "if", "then", "than", "so", "what", "where", "when", "who",
        "whom", "why", "how", "which", "do", "does", "did", "can", "could", "would", "should",
        "shall", "will", "this", "that", "these", "those", "it", "its", "we", "they", "you", "i",
        "be", "been", "being", "was", "were", "have", "has", "had",
    ];
    common_agent_slugify(value, max_chars, "research", &RESEARCH_STOPWORDS)
}

fn common_agent_slugify(
    value: &str,
    max_chars: usize,
    fallback: &str,
    stopwords: &[&str],
) -> String {
    let mut normalized = String::new();
    for ch in value.chars().flat_map(char::to_lowercase) {
        if ch.is_ascii_alphanumeric() {
            normalized.push(ch);
        } else {
            normalized.push('-');
        }
    }
    let kept = normalized
        .split('-')
        .filter(|token| !token.is_empty() && !stopwords.contains(token))
        .collect::<Vec<_>>();
    let joined = if kept.is_empty() {
        fallback.to_string()
    } else {
        kept.join("-")
    };
    truncate_chars(&joined, max_chars)
}

fn normalize_keywordish(value: &str) -> String {
    let value = value.trim();
    let value = value.strip_prefix(':').unwrap_or(value);
    value.trim_matches('"').to_string()
}

