fn print_debug_agent_promote_hot_patch(
    drift_index: Option<i64>,
    target_file: String,
    target_symbol: String,
    pattern: String,
    replacement: String,
    rationale: String,
    validation_evidence: String,
) -> Result<()> {
    let error = if let Some(index) = drift_index {
        format!("drift-index {index} out of range — current count: 0")
    } else {
        "no drift markers recorded yet — apply + validate the hot-patch via code$eval :backend :nrepl first"
            .to_string()
    };

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "error": error,
            "path": null,
            "status": null,
            "next-step": null,
            "projection": "debug-agent/debug$promote-hot-patch",
            "source": "live-nrepl-skipped",
            "live-skipped?": true,
            "nrepl-live-skipped?": true,
            "write-skipped?": true,
            "input-contract-only?": true,
            "drift-count": 0,
            "drift-index": drift_index,
            "target-file": target_file,
            "target-symbol": target_symbol,
            "edit-mode": "pattern",
            "pattern-bytes": pattern.len(),
            "replacement-bytes": replacement.len(),
            "rationale-bytes": rationale.len(),
            "validation-evidence-bytes": validation_evidence.len(),
        }))?
    );
    Ok(())
}

fn parse_debug_agent_promotion_arg(
    value: &str,
) -> Result<Option<serde_json::Map<String, serde_json::Value>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse :promotion-json as JSON or EDN: {error}"
            ))?;
            return Ok(None);
        }
    };
    let Some(map) = parsed.as_object() else {
        print_json_error(":promotion-json must be a map/object")?;
        return Ok(None);
    };
    Ok(Some(map.clone()))
}

fn debug_agent_format_frontmatter(
    promotion: &serde_json::Map<String, serde_json::Value>,
) -> String {
    let mut rendered = String::from("---\n");
    rendered.push_str(&format!(
        "created-at: {}\n",
        debug_agent_field_string(promotion, "created-at")
    ));
    if let Some(value) = debug_agent_optional_string(promotion, "debug-session") {
        rendered.push_str(&format!("debug-session: {value}\n"));
    }
    if let Some(value) = debug_agent_optional_string(promotion, "nrepl-session") {
        rendered.push_str(&format!("nrepl-session: {value}\n"));
    }
    if let Some(value) = debug_agent_optional_string(promotion, "drift-index") {
        rendered.push_str(&format!("drift-marker-index: {value}\n"));
    }
    rendered.push_str(&format!(
        "target-file: {}\n",
        debug_agent_field_string(promotion, "target-file")
    ));
    rendered.push_str(&format!(
        "target-symbol: {}\n",
        debug_agent_field_string(promotion, "target-symbol")
    ));
    rendered.push_str(&format!(
        "edit-mode: {}\n",
        debug_agent_name_field_string(promotion, "edit-mode")
    ));
    rendered.push_str(&format!(
        "status: {}\n",
        debug_agent_name_field_string(promotion, "status")
    ));
    rendered.push_str("---\n");
    rendered
}

fn debug_agent_format_body(promotion: &serde_json::Map<String, serde_json::Value>) -> String {
    let drift_marker =
        rlm_map_get(promotion, "drift-marker").and_then(serde_json::Value::as_object);
    let drift_timestamp = drift_marker
        .and_then(|map| rlm_map_get(map, "timestamp"))
        .map(coact_value_string)
        .unwrap_or_default();
    let drift_code = drift_marker
        .and_then(|map| rlm_map_get(map, "code-preview"))
        .filter(|value| debug_agent_truthy(value))
        .map(coact_value_string)
        .unwrap_or_else(|| {
            "<no drift marker — promotion requested without prior mutation>".to_string()
        });
    let validation_evidence = debug_agent_field_or_default(
        promotion,
        "validation-evidence",
        "<no validation evidence supplied>",
    );
    let rationale = debug_agent_field_or_default(promotion, "rationale", "<no rationale supplied>");
    let pattern = debug_agent_field_string(promotion, "pattern");
    let replacement = debug_agent_field_string(promotion, "replacement");
    let artifact_path = debug_agent_field_string(promotion, "artifact-path");

    format!(
        "\n## What changed in the live runtime\n\n\
         Drift marker recorded at {drift_timestamp}:\n\n\
         ```clojure\n{drift_code}\n```\n\n\
         ## Validation evidence\n\n\
         {validation_evidence}\n\n\
         ## Proposed source change (pattern mode)\n\n\
         Apply via `update-file` with `:pattern` / `:replacement`.\n\n\
         ### Current (pattern)\n\n\
         ```clojure\n{pattern}\n```\n\n\
         ### Replacement\n\n\
         ```clojure\n{replacement}\n```\n\n\
         ## Notes for update-agent\n\n\
         {rationale}\n\n\
         Saved hot-patch: {artifact_path}\n\
         Promotion request: bb tui ask \"@{artifact_path}\" -a update-agent\n"
    )
}

fn debug_agent_field_string(map: &serde_json::Map<String, serde_json::Value>, key: &str) -> String {
    rlm_map_get(map, key)
        .map(coact_value_string)
        .unwrap_or_default()
}

fn debug_agent_name_field_string(
    map: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> String {
    let value = debug_agent_field_string(map, key);
    let value = value.trim().trim_start_matches(':').trim_matches('"');
    value
        .rsplit_once('/')
        .map(|(_, name)| name)
        .unwrap_or(value)
        .to_string()
}

fn debug_agent_optional_string(
    map: &serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<String> {
    rlm_map_get(map, key)
        .filter(|value| debug_agent_truthy(value))
        .map(coact_value_string)
}

fn debug_agent_field_or_default(
    map: &serde_json::Map<String, serde_json::Value>,
    key: &str,
    default: &str,
) -> String {
    rlm_map_get(map, key)
        .filter(|value| debug_agent_truthy(value))
        .map(coact_value_string)
        .unwrap_or_else(|| default.to_string())
}

fn debug_agent_truthy(value: &serde_json::Value) -> bool {
    !matches!(
        value,
        serde_json::Value::Null | serde_json::Value::Bool(false)
    )
}

