fn parse_coact_vector_arg(value: &str, label: &str) -> Result<Option<Vec<serde_json::Value>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :{label} as JSON or EDN: {error}"))?;
            return Ok(None);
        }
    };
    let Some(items) = parsed.as_array() else {
        print_json_error(&format!(":{label} must be a vector/array"))?;
        return Ok(None);
    };
    Ok(Some(items.clone()))
}

fn coact_format_live_artifacts(artifacts: &[serde_json::Value]) -> Option<String> {
    if artifacts.is_empty() {
        return None;
    }
    Some(
        artifacts
            .iter()
            .map(|artifact| {
                let map = artifact.as_object();
                let name = map
                    .and_then(|map| rlm_map_get(map, "name"))
                    .map(coact_value_string)
                    .filter(|value| !value.is_empty())
                    .unwrap_or_else(|| "artifact".to_string());
                let content = map
                    .and_then(|map| rlm_map_get(map, "content"))
                    .map(coact_value_string)
                    .unwrap_or_else(|| coact_value_string(artifact));
                format!("### {name}\n{}", coact_truncate_ellipsis(&content, 2_000))
            })
            .collect::<Vec<_>>()
            .join("\n\n"),
    )
}

fn coact_format_previous_turns(previous_turns: &[serde_json::Value]) -> Option<String> {
    if previous_turns.is_empty() {
        return None;
    }
    Some(
        previous_turns
            .iter()
            .enumerate()
            .filter_map(|(idx, turn)| {
                let map = turn.as_object()?;
                let question = rlm_map_get(map, "question")
                    .map(coact_value_string)
                    .unwrap_or_default();
                let answer = rlm_map_get(map, "answer")
                    .map(coact_value_string)
                    .unwrap_or_default();
                let depth = rlm_map_get(map, "depth")
                    .map(coact_value_string)
                    .map(|value| normalize_tui_format_map_key(&value))
                    .filter(|value| !value.is_empty());
                let q_snip = coact_truncate_ellipsis(&question, 500);
                let a_snip = coact_truncate_ellipsis(&answer, 1_000);
                let header = match depth.as_deref() {
                    Some(depth) => format!("[Turn {} · {depth}]", idx + 1),
                    None => format!("[Turn {}]", idx + 1),
                };
                let iter_lines = if depth.as_deref() == Some("full") {
                    rlm_map_get(map, "iterations")
                        .and_then(serde_json::Value::as_array)
                        .map(|iterations| {
                            iterations
                                .iter()
                                .rev()
                                .take(3)
                                .collect::<Vec<_>>()
                                .into_iter()
                                .rev()
                                .filter_map(coact_previous_turn_iteration_line)
                                .collect::<Vec<_>>()
                                .join("\n")
                        })
                        .filter(|value| !value.is_empty())
                } else {
                    None
                };
                let mut rendered = format!("{header}\n  Q: {q_snip}");
                if !a_snip.trim().is_empty() {
                    rendered.push_str(&format!("\n  A: {a_snip}"));
                }
                if let Some(iter_lines) = iter_lines {
                    rendered.push_str(&format!("\n  Iterations:\n{iter_lines}"));
                }
                Some(rendered)
            })
            .collect::<Vec<_>>()
            .join("\n\n"),
    )
}

fn coact_previous_turn_iteration_line(iteration: &serde_json::Value) -> Option<String> {
    let map = iteration.as_object()?;
    let iteration_id = rlm_map_get(map, "iteration")
        .map(coact_value_string)
        .unwrap_or_default();
    let code_str = rlm_map_get(map, "code")
        .map(coact_join_sequence)
        .unwrap_or_default();
    let code_snip = coact_truncate_ellipsis(&code_str, 300);
    let result_s = rlm_map_get(map, "result")
        .and_then(coact_first_sequence_value)
        .map(|value| coact_truncate_ellipsis(&value, 300));
    let mut rendered = format!("    {iteration_id}. {code_snip}");
    if let Some(result_s) = result_s {
        rendered.push_str(&format!("\n       → {result_s}"));
    }
    Some(rendered)
}

fn coact_format_iterations_block(iterations: &[serde_json::Value]) -> Option<String> {
    if iterations.is_empty() {
        return None;
    }
    Some(
        iterations
            .iter()
            .enumerate()
            .filter_map(|(idx, iteration)| coact_format_iteration_line(idx, iteration))
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

fn coact_format_iteration_line(idx: usize, iteration: &serde_json::Value) -> Option<String> {
    let map = iteration.as_object()?;
    let n = rlm_map_get(map, "iteration")
        .map(coact_value_string)
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| (idx + 1).to_string());
    if tui_format_bool_field(map, &["in-flight-roster?"]).unwrap_or(false) {
        return Some(coact_format_in_flight_roster_line(&n, map));
    }
    if tui_format_bool_field(map, &["async-completion?"]).unwrap_or(false) {
        return Some(coact_format_async_completion_line(&n, map));
    }

    let channel = rlm_map_get(map, "channel")
        .map(coact_value_string)
        .unwrap_or_default();
    let thought = rlm_map_get(map, "thought")
        .map(coact_value_string)
        .unwrap_or_default();
    let result_snip = coact_iteration_result_snip(map);
    let mut rendered = format!(
        "({n}) [{channel}] {}",
        coact_truncate_ellipsis(&thought, 200)
    );
    if !result_snip.trim().is_empty() {
        rendered.push_str(&format!(" => {result_snip}"));
    }
    Some(rendered)
}

fn coact_format_in_flight_roster_line(
    iteration: &str,
    map: &serde_json::Map<String, serde_json::Value>,
) -> String {
    let head = format!("({iteration}) [🚦 ACTIVE BG]");
    let tasks = rlm_map_get(map, "tasks")
        .and_then(serde_json::Value::as_array)
        .map(|tasks| {
            tasks
                .iter()
                .filter_map(|task| {
                    let task = task.as_object()?;
                    let task_id = rlm_map_get(task, "task-id")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    let lang = rlm_map_get(task, "lang")
                        .map(coact_value_string)
                        .filter(|value| !value.is_empty())
                        .unwrap_or_else(|| "?".to_string());
                    let lang = match lang.as_str() {
                        "clojure" => "clj".to_string(),
                        "javascript" => "js".to_string(),
                        _ => lang,
                    };
                    let submitted_iter = rlm_map_get(task, "submitted-iter")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    let age_s = rlm_map_get(task, "age-s")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    Some(format!(
                        "{task_id}({lang}, iter {submitted_iter}, {age_s}s)"
                    ))
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    if tasks.is_empty() {
        head
    } else {
        format!("{head} {}", tasks.join("; "))
    }
}

fn coact_format_async_completion_line(
    iteration: &str,
    map: &serde_json::Map<String, serde_json::Value>,
) -> String {
    let entries = rlm_map_get(map, "eval-results")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let mut sources = entries
        .iter()
        .filter_map(|entry| {
            entry
                .as_object()
                .and_then(|entry| rlm_map_get(entry, "from-iteration"))
                .map(coact_value_string)
                .filter(|value| !value.is_empty())
        })
        .collect::<Vec<_>>();
    sources.sort();
    sources.dedup();
    let from_tag = if sources.is_empty() {
        "from iter ?".to_string()
    } else {
        format!(
            "from iter{} {}",
            if sources.len() > 1 { "s" } else { "" },
            sources.join(",")
        )
    };
    let head = format!("({iteration}) [↺ async {from_tag}]");
    let per_entry = entries
        .iter()
        .filter_map(|entry| {
            let entry = entry.as_object()?;
            let task_id = rlm_map_get(entry, "task-id")
                .map(coact_value_string)
                .unwrap_or_default();
            let status = rlm_map_get(entry, "status")
                .map(coact_value_string)
                .map(|value| normalize_tui_format_map_key(&value))
                .filter(|value| !value.is_empty())
                .unwrap_or_else(|| "resolved".to_string());
            let error = rlm_map_get(entry, "error")
                .map(coact_value_string)
                .unwrap_or_default();
            let result = rlm_map_get(entry, "result")
                .map(coact_value_string)
                .unwrap_or_default();
            let payload = if !error.trim().is_empty() {
                Some(format!("error={}", coact_truncate_ellipsis(&error, 100)))
            } else if !result.trim().is_empty() {
                Some(coact_truncate_ellipsis(&result, 100))
            } else {
                None
            };
            let mut rendered = format!("task-id={task_id} status={status}");
            if let Some(payload) = payload {
                rendered.push_str(&format!(" => {payload}"));
            }
            Some(rendered)
        })
        .collect::<Vec<_>>();
    if per_entry.is_empty() {
        head
    } else {
        format!("{head} {}", per_entry.join(" ; "))
    }
}

fn coact_iteration_result_snip(map: &serde_json::Map<String, serde_json::Value>) -> String {
    if let Some(tool_results) =
        rlm_map_get(map, "tool-results").and_then(serde_json::Value::as_array)
    {
        if !tool_results.is_empty() {
            return tool_results
                .iter()
                .filter_map(|result| {
                    let result = result.as_object()?;
                    let tool_name = rlm_map_get(result, "tool-name")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    let tool_result = rlm_map_get(result, "tool-result")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    Some(format!(
                        "{tool_name}→{}",
                        coact_truncate_ellipsis(&tool_result, 100)
                    ))
                })
                .collect::<Vec<_>>()
                .join("; ");
        }
    }
    if let Some(eval_results) =
        rlm_map_get(map, "eval-results").and_then(serde_json::Value::as_array)
    {
        if !eval_results.is_empty() {
            return eval_results
                .iter()
                .filter_map(|result| {
                    let result = result.as_object()?;
                    let lang = rlm_map_get(result, "lang")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    let value = rlm_map_get(result, "result")
                        .map(coact_value_string)
                        .unwrap_or_default();
                    Some(format!("{lang}:{}", coact_truncate_ellipsis(&value, 100)))
                })
                .collect::<Vec<_>>()
                .join("; ");
        }
    }
    String::new()
}

fn coact_join_sequence(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => String::new(),
        serde_json::Value::Array(values) => values
            .iter()
            .map(coact_value_string)
            .collect::<Vec<_>>()
            .join("; "),
        other => coact_value_string(other),
    }
}

fn coact_first_sequence_value(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Null => None,
        serde_json::Value::Array(values) => values.first().map(coact_value_string),
        other => Some(coact_value_string(other)),
    }
}

fn coact_value_string(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => String::new(),
        serde_json::Value::String(value) => value.clone(),
        serde_json::Value::Bool(value) => value.to_string(),
        serde_json::Value::Number(value) => value.to_string(),
        serde_json::Value::Array(_) | serde_json::Value::Object(_) => {
            serde_json::to_string(value).unwrap_or_else(|_| value.to_string())
        }
    }
}

fn coact_truncate_ellipsis(value: &str, max_chars: usize) -> String {
    if value.chars().count() > max_chars {
        format!("{}{}", truncate_chars(value, max_chars), by_tui::ELLIPSIS)
    } else {
        value.to_string()
    }
}

fn parse_evaluation_iterations(value: &str) -> Result<Option<Vec<serde_json::Value>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse :iterations as JSON or EDN: {error}"
            ))?;
            return Ok(None);
        }
    };
    let Some(iterations) = parsed.as_array() else {
        print_json_error(":iterations must be a vector/array")?;
        return Ok(None);
    };
    Ok(Some(iterations.clone()))
}

fn print_evaluation_evidence_string(evidence: String) -> Result<()> {
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "evidence": evidence,
            "length": evidence.chars().count(),
        }))?
    );
    Ok(())
}

fn evaluation_build_iteration_evidence(iterations: &[serde_json::Value]) -> String {
    let evidence = iterations
        .iter()
        .filter_map(|iteration| {
            let map = iteration.as_object()?;
            let iteration_label = rlm_map_get(map, "iteration")
                .map(evaluation_display_value)
                .unwrap_or_default();
            let eval_results = rlm_map_get(map, "eval-results")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default();
            let error = rlm_map_get(map, "error").and_then(evaluation_text_value);
            let outputs = eval_results
                .iter()
                .filter_map(|result| {
                    result
                        .as_object()
                        .and_then(|map| rlm_map_get(map, "output"))
                        .and_then(evaluation_text_value)
                })
                .filter(|output| !output.trim().is_empty())
                .map(|output| evaluation_recover_truncated_text(&output).0)
                .collect::<Vec<_>>();
            let result_strings = if !eval_results.is_empty() && outputs.is_empty() {
                eval_results
                    .iter()
                    .filter_map(|result| {
                        result
                            .as_object()
                            .and_then(|map| rlm_map_get(map, "result"))
                            .filter(|value| !value.is_null())
                            .map(evaluation_pr_str)
                            .filter(|value| !value.trim().is_empty())
                    })
                    .collect::<Vec<_>>()
            } else {
                Vec::new()
            };
            let codes = eval_results
                .iter()
                .filter_map(|result| {
                    result
                        .as_object()
                        .and_then(|map| rlm_map_get(map, "code"))
                        .and_then(evaluation_text_value)
                })
                .collect::<Vec<_>>();
            let script_contents = eval_results
                .iter()
                .filter_map(|result| {
                    result
                        .as_object()
                        .and_then(|map| rlm_map_get(map, "script-content"))
                        .and_then(evaluation_text_value)
                })
                .filter(|value| !value.trim().is_empty())
                .collect::<Vec<_>>();

            if outputs.is_empty() && result_strings.is_empty() && error.is_none() {
                return None;
            }

            let mut section = format!("--- Iteration {iteration_label} ---\n");
            if let Some(code) = codes.first() {
                section.push_str(&format!("Code: {code}\n"));
            }
            if let Some(script_content) = script_contents.first() {
                section.push_str(&format!("Script content:\n{script_content}\n"));
            }
            if let Some(error) = error {
                section.push_str(&format!("Error: {error}\n"));
            }
            if !outputs.is_empty() {
                section.push_str(&format!("Output:\n{}\n", outputs.join("\n")));
            }
            if !result_strings.is_empty() {
                section.push_str(&format!("Result: {}\n", result_strings.join(", ")));
            }
            Some(section)
        })
        .collect::<Vec<_>>()
        .join("\n");
    truncate_chars(&evidence, EVALUATION_EVIDENCE_MAX_CHARS)
}

fn evaluation_build_react_evidence(iterations: &[serde_json::Value]) -> String {
    let evidence = iterations
        .iter()
        .filter_map(|iteration| {
            let map = iteration.as_object()?;
            let actions = rlm_map_get(map, "actions")
                .and_then(serde_json::Value::as_array)
                .cloned()
                .unwrap_or_default();
            let observation = rlm_map_get(map, "observation").and_then(evaluation_text_value);
            if actions.is_empty() && observation.is_none() {
                return None;
            }

            let iteration_label = rlm_map_get(map, "iteration")
                .map(evaluation_display_value)
                .unwrap_or_default();
            let mut section = format!("--- Iteration {iteration_label} ---\n");
            if let Some(thought) = rlm_map_get(map, "thought").and_then(evaluation_text_value) {
                section.push_str(&format!("Thought: {thought}\n"));
            }
            if !actions.is_empty() {
                let rendered_actions = actions
                    .iter()
                    .filter_map(|action| {
                        let action = action.as_object()?;
                        let tool_name = rlm_map_get(action, "tool-name")
                            .map(evaluation_display_value)
                            .unwrap_or_default();
                        let tool_args = rlm_map_get(action, "tool-args")
                            .map(|value| format!(" {}", evaluation_pr_str(value)))
                            .unwrap_or_default();
                        let tool_result = rlm_map_get(action, "tool-result")
                            .map(evaluation_display_value)
                            .unwrap_or_default();
                        Some(format!(
                            "Tool: {tool_name}{tool_args}\nResult: {tool_result}"
                        ))
                    })
                    .collect::<Vec<_>>()
                    .join("\n");
                section.push_str(&rendered_actions);
                section.push('\n');
            }
            if let Some(observation) = observation {
                section.push_str(&format!("Observation: {observation}\n"));
            }
            Some(section)
        })
        .collect::<Vec<_>>()
        .join("\n");
    truncate_chars(&evidence, EVALUATION_EVIDENCE_MAX_CHARS)
}

fn react_agent_format_indexed_block(items: &[serde_json::Value]) -> Option<String> {
    if items.is_empty() {
        return None;
    }
    Some(
        items
            .iter()
            .enumerate()
            .map(|(idx, item)| {
                format!(
                    "({}) {}",
                    idx + 1,
                    react_agent_truncate_with_ellipsis(&evaluation_display_value(item), 200)
                )
            })
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

fn react_agent_format_iterations_block(iterations: &[serde_json::Value]) -> Option<String> {
    if iterations.is_empty() {
        return None;
    }
    Some(
        iterations
            .iter()
            .enumerate()
            .map(|(idx, iteration)| {
                let map = iteration.as_object();
                let n = map
                    .and_then(|map| rlm_map_get(map, "iteration"))
                    .map(evaluation_display_value)
                    .filter(|value| !value.trim().is_empty())
                    .unwrap_or_else(|| (idx + 1).to_string());
                let thought = map
                    .and_then(|map| rlm_map_get(map, "thought"))
                    .map(evaluation_display_value)
                    .unwrap_or_default();
                let thought = react_agent_truncate_with_ellipsis(&thought, 200);
                let action_snip = map
                    .and_then(|map| rlm_map_get(map, "actions"))
                    .and_then(serde_json::Value::as_array)
                    .filter(|actions| !actions.is_empty())
                    .map(|actions| {
                        actions
                            .iter()
                            .map(|action| {
                                action
                                    .as_object()
                                    .and_then(|map| rlm_map_get(map, "tool-name"))
                                    .map(evaluation_display_value)
                                    .unwrap_or_default()
                            })
                            .collect::<Vec<_>>()
                            .join("; ")
                    });
                let observation = map
                    .and_then(|map| rlm_map_get(map, "observation"))
                    .map(evaluation_display_value)
                    .unwrap_or_default();
                let observation = if observation.trim().is_empty() {
                    String::new()
                } else {
                    react_agent_truncate_with_ellipsis(&observation, 150)
                };

                let mut line = format!("({n}) {thought}");
                if let Some(action_snip) = action_snip {
                    line.push_str(" => ");
                    line.push_str(&action_snip);
                }
                if !observation.trim().is_empty() {
                    line.push_str(" | ");
                    line.push_str(&observation);
                }
                line
            })
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

fn react_agent_truncate_with_ellipsis(value: &str, limit: usize) -> String {
    if value.chars().count() <= limit {
        value.to_string()
    } else {
        let mut out = value.chars().take(limit).collect::<String>();
        out.push('…');
        out
    }
}

fn evaluation_build_context(snapshot: &serde_json::Map<String, serde_json::Value>) -> String {
    let mut context = String::new();
    if let Some(instruction) = rlm_map_get(snapshot, "instruction").and_then(evaluation_text_value)
    {
        if !instruction.is_empty() {
            context.push_str(&format!(
                "Agent instruction:\n{}\n\n",
                evaluation_truncate(&instruction, 500)
            ));
        }
    }
    if let Some(agent_context) =
        rlm_map_get(snapshot, "agent-context").and_then(evaluation_text_value)
    {
        if !agent_context.is_empty() {
            context.push_str(&format!(
                "Agent context:\n{}\n\n",
                evaluation_truncate(&agent_context, 500)
            ));
        }
    }
    if let Some(tool_context) =
        rlm_map_get(snapshot, "tool-context").and_then(evaluation_text_value)
    {
        if !tool_context.is_empty() {
            context.push_str(&format!(
                "Tool context:\n{}",
                evaluation_truncate(&tool_context, 500)
            ));
        }
    }
    context
}

fn evaluation_recover_truncated_text(text: &str) -> (String, bool) {
    let marker =
        regex::Regex::new(r"--- Full content saved to: (.+?) ---").expect("valid marker regex");
    let Some(captures) = marker.captures(text) else {
        return (text.to_string(), false);
    };
    let Some(path) = captures.get(1).map(|value| value.as_str()) else {
        return (text.to_string(), false);
    };
    match std::fs::read_to_string(path) {
        Ok(content) => (content, true),
        Err(_) => (text.to_string(), false),
    }
}

fn evaluation_text_value(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Null => None,
        serde_json::Value::String(value) => Some(value.clone()),
        serde_json::Value::Bool(value) => Some(value.to_string()),
        serde_json::Value::Number(value) => Some(value.to_string()),
        value => Some(value.to_string()),
    }
}

fn evaluation_display_value(value: &serde_json::Value) -> String {
    evaluation_text_value(value).unwrap_or_default()
}

fn evaluation_pr_str(value: &serde_json::Value) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| evaluation_display_value(value))
}

fn evaluation_truncate(value: &str, max_len: usize) -> String {
    if value.chars().count() <= max_len {
        value.to_string()
    } else {
        format!("{}...", truncate_chars(value, max_len))
    }
}

fn print_cache_threshold(query: String) -> Result<()> {
    let word_count = cache_word_count(&query);
    let threshold = cache_default_threshold(&query);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "threshold": threshold,
            "word-count": word_count,
        }))?
    );
    Ok(())
}

fn print_cache_cosine(a: String, b: String) -> Result<()> {
    let Some(a) = parse_cache_vector_arg(&a, "a")? else {
        return Ok(());
    };
    let Some(b) = parse_cache_vector_arg(&b, "b")? else {
        return Ok(());
    };
    let similarity = cache_cosine_similarity(&a, &b);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "similarity": similarity,
            "a-dim": a.len(),
            "b-dim": b.len(),
        }))?
    );
    Ok(())
}

fn print_cache_lookup(
    query: String,
    embedding: String,
    entries: String,
    threshold: Option<f64>,
) -> Result<()> {
    let Some(embedding) = parse_cache_vector_arg(&embedding, "embedding")? else {
        return Ok(());
    };
    let entries = match parse_rlm_json_or_edn(&entries) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :entries as JSON or EDN: {error}"))?;
            return Ok(());
        }
    };
    let Some(entries) = entries.as_array() else {
        print_json_error(":entries must be a vector/array")?;
        return Ok(());
    };
    let threshold = threshold.unwrap_or_else(|| cache_default_threshold(&query));
    let mut best: Option<serde_json::Value> = None;
    let mut best_similarity = f64::NEG_INFINITY;
    for entry in entries {
        let Some(map) = entry.as_object() else {
            continue;
        };
        let Some(entry_embedding) = rlm_map_get(map, "embedding").and_then(cache_vector_value)
        else {
            continue;
        };
        let similarity = cache_cosine_similarity(&embedding, &entry_embedding);
        if similarity > threshold && similarity > best_similarity {
            best_similarity = similarity;
            best = Some(serde_json::json!({
                "response": rlm_map_get(map, "response").cloned().unwrap_or(serde_json::Value::Null),
                "similarity": similarity,
                "cached-query": rlm_map_get(map, "query").cloned().unwrap_or(serde_json::Value::Null),
                "attributes": rlm_map_get(map, "attributes").cloned().unwrap_or_else(|| serde_json::json!({})),
            }));
        }
    }
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "hit?": best.is_some(),
            "threshold": threshold,
            "result": best.unwrap_or(serde_json::Value::Null),
        }))?
    );
    Ok(())
}

fn print_cache_stats(entries: String, hits: u64, misses: u64) -> Result<()> {
    let entries = match parse_rlm_json_or_edn(&entries) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :entries as JSON or EDN: {error}"))?;
            return Ok(());
        }
    };
    let Some(entries) = entries.as_array() else {
        print_json_error(":entries must be a vector/array")?;
        return Ok(());
    };
    let total = hits + misses;
    let hit_rate = if total > 0 {
        hits as f64 / total as f64
    } else {
        0.0
    };
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "entries": entries.len(),
            "hits": hits,
            "misses": misses,
            "hit-rate": hit_rate,
        }))?
    );
    Ok(())
}

fn parse_cache_vector_arg(value: &str, name: &str) -> Result<Option<Vec<f64>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :{name} as JSON or EDN: {error}"))?;
            return Ok(None);
        }
    };
    let Some(vector) = cache_vector_value(&parsed) else {
        print_json_error(&format!(":{name} must be a numeric vector/array"))?;
        return Ok(None);
    };
    Ok(Some(vector))
}

fn cache_default_threshold(query: &str) -> f64 {
    match cache_word_count(query) {
        0..=3 => 0.98,
        4..=6 => 0.96,
        _ => 0.94,
    }
}

fn cache_word_count(query: &str) -> usize {
    query.split_whitespace().count()
}

fn cache_cosine_similarity(a: &[f64], b: &[f64]) -> f64 {
    let mag_a = cache_magnitude(a);
    let mag_b = cache_magnitude(b);
    if mag_a == 0.0 || mag_b == 0.0 {
        return 0.0;
    }
    let dot = a.iter().zip(b.iter()).map(|(a, b)| a * b).sum::<f64>();
    dot / (mag_a * mag_b)
}

fn cache_magnitude(value: &[f64]) -> f64 {
    value.iter().map(|item| item * item).sum::<f64>().sqrt()
}

fn cache_vector_value(value: &serde_json::Value) -> Option<Vec<f64>> {
    let items = value.as_array()?;
    let mut result = Vec::with_capacity(items.len());
    for item in items {
        result.push(rlm_json_to_f64(item)?);
    }
    Some(result)
}

const LOOP_GUARD_ANSWER_PREFIX: &str =
    "*(Loop guard: detected 3 consecutive identical tool calls. Stopping early. Latest tool result:)*\n\n```\n";
const LOOP_GUARD_IDEMPOTENT_ANSWER_PREFIX: &str =
    "*(Loop guard: an idempotent read-only tool was called repeatedly with varying args. Stopping early to break the loop. Latest tool result:)*\n\n```\n";
const LOOP_GUARD_IDEMPOTENT_TOOL_NAMES: &[&str] = &[
    "config$read",
    "env-detect$rescan",
    "agent-runtime$config",
    "config$list-snapshots",
    "mcp$lifecycle",
];

fn print_loop_guard_decision(
    iterations: String,
    tool_name: String,
    args: String,
    depth: i64,
) -> Result<()> {
    let iterations = match parse_rlm_json_or_edn(&iterations) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse :iterations as JSON or EDN: {error}"
            ))?;
            return Ok(());
        }
    };
    let Some(iterations) = iterations.as_array() else {
        print_json_error(":iterations must be a vector/array")?;
        return Ok(());
    };
    let args = match parse_rlm_json_or_edn(&args) {
        Ok(value) => loop_guard_normalize_tool_args(&value),
        Err(error) => {
            print_json_error(&format!("failed to parse :args as JSON or EDN: {error}"))?;
            return Ok(());
        }
    };
    let decision = loop_guard_redundant_tool_call_decision(iterations, &tool_name, &args, depth);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "blocked?": decision.is_some(),
            "decision": decision.unwrap_or(serde_json::Value::Null),
        }))?
    );
    Ok(())
}

fn loop_guard_redundant_tool_call_decision(
    iterations: &[serde_json::Value],
    tool_name: &str,
    args: &serde_json::Map<String, serde_json::Value>,
    depth: i64,
) -> Option<serde_json::Value> {
    if depth != 0 {
        return None;
    }
    let priors = loop_guard_iterations_history(iterations);
    if priors.len() != 2 {
        return None;
    }

    if priors
        .iter()
        .all(|record| loop_guard_prior_record_has_call(record, tool_name, args))
    {
        return Some(serde_json::json!({
            "result": "block",
            "reason": "Same tool call issued in each of the last 2 iterations.",
            "answer": loop_guard_synthesize_answer(priors.last().unwrap(), LOOP_GUARD_ANSWER_PREFIX),
        }));
    }

    if LOOP_GUARD_IDEMPOTENT_TOOL_NAMES.contains(&tool_name)
        && loop_guard_count_prior_tool_uses(&priors, tool_name) >= 2
    {
        let count = loop_guard_count_prior_tool_uses(&priors, tool_name);
        return Some(serde_json::json!({
            "result": "block",
            "reason": format!(
                "Idempotent tool '{tool_name}' already called {count} time(s) in the last 2 iterations. Reuse the prior result from iteration history instead of re-fetching."
            ),
            "answer": loop_guard_synthesize_answer(priors.last().unwrap(), LOOP_GUARD_IDEMPOTENT_ANSWER_PREFIX),
        }));
    }

    None
}

fn loop_guard_iterations_history(iterations: &[serde_json::Value]) -> Vec<serde_json::Value> {
    let mut records = iterations
        .iter()
        .filter(|record| !loop_guard_iter_tool_calls(record).is_empty())
        .cloned()
        .collect::<Vec<_>>();
    if records.len() > 2 {
        records.drain(0..records.len() - 2);
    }
    records
}

fn loop_guard_iter_tool_calls(record: &serde_json::Value) -> Vec<serde_json::Value> {
    let Some(map) = record.as_object() else {
        return Vec::new();
    };
    if let Some(actions) = rlm_map_get(map, "actions")
        .and_then(serde_json::Value::as_array)
        .filter(|items| !items.is_empty())
    {
        return actions.clone();
    }
    let channel = rlm_map_get(map, "channel")
        .and_then(evaluation_text_value)
        .unwrap_or_default();
    if channel == "tool" {
        if let Some(tool_results) = rlm_map_get(map, "tool-results")
            .and_then(serde_json::Value::as_array)
            .filter(|items| !items.is_empty())
        {
            return tool_results.clone();
        }
    }
    Vec::new()
}

fn loop_guard_prior_record_has_call(
    record: &serde_json::Value,
    tool_name: &str,
    current_args: &serde_json::Map<String, serde_json::Value>,
) -> bool {
    loop_guard_iter_tool_calls(record).iter().any(|call| {
        let Some(call) = call.as_object() else {
            return false;
        };
        let prior_name = rlm_map_get(call, "tool-name")
            .map(evaluation_display_value)
            .map(|value| normalize_keywordish(&value))
            .unwrap_or_default();
        let prior_args = rlm_map_get(call, "tool-args")
            .map(loop_guard_normalize_tool_args)
            .unwrap_or_default();
        prior_name == tool_name && prior_args == *current_args
    })
}

fn loop_guard_count_prior_tool_uses(iterations: &[serde_json::Value], tool_name: &str) -> usize {
    iterations
        .iter()
        .flat_map(loop_guard_iter_tool_calls)
        .filter(|call| {
            call.as_object()
                .and_then(|call| rlm_map_get(call, "tool-name"))
                .map(evaluation_display_value)
                .map(|value| normalize_keywordish(&value) == tool_name)
                .unwrap_or(false)
        })
        .count()
}

fn loop_guard_latest_tool_result(record: &serde_json::Value) -> Option<String> {
    loop_guard_iter_tool_calls(record)
        .last()
        .and_then(serde_json::Value::as_object)
        .and_then(|call| rlm_map_get(call, "tool-result"))
        .and_then(evaluation_text_value)
}

fn loop_guard_synthesize_answer(record: &serde_json::Value, prefix: &str) -> String {
    format!(
        "{}{}\n```",
        prefix,
        loop_guard_latest_tool_result(record)
            .unwrap_or_else(|| "(no prior result captured)".to_string())
    )
}

fn loop_guard_normalize_tool_args(
    tool_args: &serde_json::Value,
) -> serde_json::Map<String, serde_json::Value> {
    if let Some(map) = tool_args.as_object() {
        return map
            .iter()
            .map(|(key, value)| (normalize_keywordish(key), value.clone()))
            .collect();
    }
    let Some(items) = tool_args.as_array() else {
        return serde_json::Map::new();
    };

    let standard = items
        .iter()
        .filter_map(|item| {
            let item = item.as_object()?;
            let name = rlm_map_get(item, "name")?;
            let value = rlm_map_get(item, "value")?;
            Some((
                normalize_keywordish(&evaluation_display_value(name)),
                value.clone(),
            ))
        })
        .collect::<Vec<_>>();
    if !standard.is_empty() {
        return standard.into_iter().collect();
    }

    let mut compact = serde_json::Map::new();
    for item in items {
        if let Some(map) = item.as_object() {
            for (key, value) in map {
                compact.insert(normalize_keywordish(key), value.clone());
            }
        }
    }
    compact
}

