fn print_schema_list(query: Option<String>) -> Result<()> {
    let query = query
        .as_deref()
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty());
    let schemas = COMMON_SCHEMA_ENTRIES
        .iter()
        .copied()
        .filter(|entry| {
            query.as_deref().is_none_or(|query| {
                entry.name.contains(query)
                    || entry.description.to_ascii_lowercase().contains(query)
                    || entry.form.to_ascii_lowercase().contains(query)
            })
        })
        .map(schema_entry_json)
        .collect::<Vec<_>>();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "schemas": schemas,
            "count": schemas.len(),
        }))?
    );
    Ok(())
}

fn print_schema_read(name: String) -> Result<()> {
    let normalized = normalize_schema_name(&name);
    if normalized.is_empty() {
        print_json_error(":name is required (string)")?;
        return Ok(());
    }
    let Some(entry) = COMMON_SCHEMA_ENTRIES
        .iter()
        .copied()
        .find(|entry| entry.name == normalized)
    else {
        println!(
            "{}",
            serde_json::to_string_pretty(&serde_json::json!({
                "not-found": true,
                "name": normalized,
            }))?
        );
        return Ok(());
    };
    println!(
        "{}",
        serde_json::to_string_pretty(&schema_entry_json(entry))?
    );
    Ok(())
}

fn schema_entry_json(entry: SchemaEntry) -> serde_json::Value {
    serde_json::json!({
        "name": entry.name,
        "qualified-name": format!("ai.brainyard.agent.common.schema/{}", entry.name),
        "description": entry.description,
        "form": entry.form,
    })
}

fn normalize_schema_name(name: &str) -> String {
    let trimmed = name.trim();
    let without_namespace = trimmed.rsplit('/').next().unwrap_or(trimmed);
    normalize_keywordish(without_namespace)
        .trim_start_matches(':')
        .to_string()
}

fn print_artifact_add(artifacts: String, artifact: String) -> Result<()> {
    let artifacts = match parse_rlm_json_or_edn(&artifacts) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse :artifacts as JSON or EDN: {error}"
            ))?;
            return Ok(());
        }
    };
    let Some(existing) = artifacts.as_array() else {
        print_json_error(":artifacts must be a vector/array")?;
        return Ok(());
    };
    let artifact = match parse_rlm_json_or_edn(&artifact) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse :artifact as JSON or EDN: {error}"
            ))?;
            return Ok(());
        }
    };
    if !artifact.is_object() {
        print_json_error(":artifact must be a map/object")?;
        return Ok(());
    }

    let before_count = existing.len();
    let artifacts = conj_artifact_projection(existing, artifact);
    let removed_count = before_count + 1 - artifacts.len();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "artifacts": artifacts,
            "count": artifacts.len(),
            "removed-count": removed_count,
            "replaced?": removed_count > 0,
        }))?
    );
    Ok(())
}

fn conj_artifact_projection(
    existing: &[serde_json::Value],
    new_artifact: serde_json::Value,
) -> Vec<serde_json::Value> {
    let mut artifacts = existing
        .iter()
        .filter(|artifact| !artifact_is_duplicate(artifact, &new_artifact))
        .cloned()
        .collect::<Vec<_>>();
    artifacts.push(new_artifact);
    artifacts
}

fn artifact_is_duplicate(existing: &serde_json::Value, new_artifact: &serde_json::Value) -> bool {
    let Some(existing_type) = artifact_type(existing) else {
        return false;
    };
    let Some(new_type) = artifact_type(new_artifact) else {
        return false;
    };
    if existing_type != new_type {
        return false;
    }
    match existing_type.as_str() {
        "chart" => {
            artifact_data_field(existing, "chart-spec")
                == artifact_data_field(new_artifact, "chart-spec")
        }
        "ui-layout" => {
            artifact_data_field(existing, "ui-layout")
                == artifact_data_field(new_artifact, "ui-layout")
        }
        "image" => artifact_data_field(existing, "url") == artifact_data_field(new_artifact, "url"),
        _ => false,
    }
}

fn artifact_type(artifact: &serde_json::Value) -> Option<String> {
    artifact
        .as_object()
        .and_then(|map| rlm_map_get(map, "artifact-type"))
        .map(evaluation_display_value)
        .map(|value| normalize_keywordish(&value))
        .filter(|value| !value.is_empty())
}

fn artifact_data_field<'a>(
    artifact: &'a serde_json::Value,
    field: &str,
) -> Option<&'a serde_json::Value> {
    artifact
        .as_object()
        .and_then(|map| rlm_map_get(map, "artifact-data"))
        .and_then(serde_json::Value::as_object)
        .and_then(|data| rlm_map_get(data, field))
}

