fn print_rag_add_document_preview(
    text: String,
    metadata: Option<String>,
    id: Option<String>,
    embedding: Option<String>,
    timestamp: Option<i64>,
) -> Result<()> {
    let Some(embedding) = embedding else {
        print_json_error("RAG embedding function skipped; pass --embedding fixture")?;
        return Ok(());
    };
    let Some(embedding) = parse_cache_vector_arg(&embedding, "embedding")? else {
        return Ok(());
    };
    let metadata = match metadata.as_deref() {
        Some(value) if !value.trim().is_empty() => match parse_rlm_json_or_edn(value) {
            Ok(value) => value,
            Err(error) => {
                print_json_error(&format!(
                    "failed to parse :metadata as JSON or EDN: {error}"
                ))?;
                return Ok(());
            }
        },
        _ => serde_json::json!({}),
    };
    let timestamp = timestamp
        .or_else(|| system_time_millis(SystemTime::now()))
        .unwrap_or(0);
    let id = id
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| format!("preview-{timestamp}"));
    let text_length = text.chars().count();
    let document = serde_json::json!({
        "id": id.clone(),
        "text": text,
        "embedding": embedding,
        "metadata": metadata,
        "timestamp": timestamp,
    });

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "success": true,
            "id": id,
            "text-length": text_length,
            "document": document,
            "projection": "common.rag-commands/rag-command$add-document-preview",
            "embedding-skipped?": false,
            "store-skipped?": true,
        }))?
    );
    Ok(())
}

