fn parse_previous_turns_vector_arg(
    value: &str,
    name: &str,
) -> Result<Option<Vec<serde_json::Value>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :{name} as JSON or EDN: {error}"))?;
            return Ok(None);
        }
    };
    let Some(turns) = parsed.as_array() else {
        print_json_error(&format!(":{name} must be a vector/array"))?;
        return Ok(None);
    };
    Ok(Some(turns.clone()))
}

fn previous_turns_append_projection(
    existing: &[serde_json::Value],
    turn: serde_json::Value,
    max_turns: usize,
    full_depth: usize,
    summary_depth: usize,
) -> Vec<serde_json::Value> {
    let mut all_turns = existing.to_vec();
    all_turns.push(turn);
    let mut compressed = previous_turns_recompress(&all_turns, full_depth, summary_depth, 4000);
    if compressed.len() > max_turns {
        compressed.drain(0..compressed.len() - max_turns);
    }
    compressed
}

fn compact_previous_turns_projection(
    previous_turns: &[serde_json::Value],
    target_tokens: usize,
) -> Vec<serde_json::Value> {
    if previous_turns.is_empty() {
        return Vec::new();
    }

    let passes = [
        (3usize, 10usize, 2000usize),
        (1, 5, 1000),
        (0, 0, 400),
        (0, 0, 200),
    ];
    let mut turns = previous_turns.to_vec();
    for (index, (full_depth, summary_depth, answer_limit)) in passes.iter().enumerate() {
        let compressed =
            previous_turns_recompress(&turns, *full_depth, *summary_depth, *answer_limit);
        let estimated = estimate_previous_turns_tokens(&compressed);
        if estimated <= target_tokens {
            return compressed;
        }
        if index + 1 == passes.len() {
            return keep_last_previous_turns(&compressed, 10);
        }
        turns = compressed;
    }
    keep_last_previous_turns(&turns, 10)
}

fn keep_last_previous_turns(
    turns: &[serde_json::Value],
    max_turns: usize,
) -> Vec<serde_json::Value> {
    if turns.len() <= max_turns {
        return turns.to_vec();
    }
    turns[turns.len() - max_turns..].to_vec()
}

fn previous_turns_recompress(
    turns: &[serde_json::Value],
    full_depth: usize,
    summary_depth: usize,
    answer_limit: usize,
) -> Vec<serde_json::Value> {
    let n = turns.len();
    turns
        .iter()
        .enumerate()
        .map(|(i, turn)| {
            let recency = n.saturating_sub(1 + i);
            previous_turns_compress_turn(turn, recency, full_depth, summary_depth, answer_limit)
        })
        .collect()
}

fn previous_turns_compress_turn(
    turn: &serde_json::Value,
    recency: usize,
    full_depth: usize,
    summary_depth: usize,
    answer_limit: usize,
) -> serde_json::Value {
    if recency < full_depth {
        let mut full = turn.as_object().cloned().unwrap_or_default();
        full.insert("depth".to_string(), serde_json::json!("full"));
        return serde_json::Value::Object(full);
    }

    if recency < full_depth + summary_depth {
        let mut summary = turn.as_object().cloned().unwrap_or_default();
        summary.remove("iterations");
        summary.insert(
            "answer".to_string(),
            previous_turns_project_answer(turn, answer_limit),
        );
        summary.insert("depth".to_string(), serde_json::json!("summary"));
        return serde_json::Value::Object(summary);
    }

    let question = turn
        .as_object()
        .and_then(|map| rlm_map_get(map, "question"))
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let answer = previous_turns_project_answer(turn, answer_limit.min(400));
    serde_json::json!({
        "question": question,
        "answer": answer,
        "depth": "minimal",
    })
}

fn previous_turns_project_answer(turn: &serde_json::Value, max_chars: usize) -> serde_json::Value {
    let Some(answer) = turn
        .as_object()
        .and_then(|map| rlm_map_get(map, "answer"))
        .filter(|value| !value.is_null())
        .and_then(evaluation_text_value)
    else {
        return serde_json::Value::Null;
    };
    serde_json::json!(previous_turns_inline_truncate(
        &answer,
        max_chars,
        "prior answer"
    ))
}

fn previous_turns_inline_truncate(value: &str, max_chars: usize, label: &str) -> String {
    let total_chars = value.chars().count();
    if total_chars <= max_chars {
        return value.to_string();
    }

    let head_len = ((max_chars as f64) * 0.7).floor() as usize;
    let tail_len = ((max_chars as f64) * 0.2).floor() as usize;
    let total_lines = value.lines().count();
    let head = value.chars().take(head_len).collect::<String>();
    let tail = value
        .chars()
        .skip(total_chars.saturating_sub(tail_len))
        .collect::<String>();
    format!(
        "{head}\n\n--- {label} TRUNCATED inline (original: {total_chars} chars, {total_lines} lines) ---\n--- Full content not saved: by-rs live-free projection does not write recovery files. ---\n--- Truncation limit: {max_chars} chars. ---\n\n{tail}"
    )
}

fn previous_turns_depth_counts(turns: &[serde_json::Value]) -> BTreeMap<String, serde_json::Value> {
    let mut counts = BTreeMap::<String, usize>::new();
    for turn in turns {
        let depth = turn
            .as_object()
            .and_then(|map| rlm_map_get(map, "depth"))
            .map(evaluation_display_value)
            .map(|value| normalize_keywordish(&value))
            .filter(|value| !value.is_empty())
            .unwrap_or_else(|| "unknown".to_string());
        *counts.entry(depth).or_default() += 1;
    }
    counts
        .into_iter()
        .map(|(key, count)| (key, serde_json::json!(count)))
        .collect()
}

fn previous_turns_projection_string(turns: &[serde_json::Value]) -> String {
    serde_json::to_string(turns).unwrap_or_default()
}

fn estimate_previous_turns_tokens(turns: &[serde_json::Value]) -> usize {
    if turns.is_empty() {
        0
    } else {
        estimate_tokens_from_text(&previous_turns_projection_string(turns))
    }
}

fn estimate_tokens_from_text(text: &str) -> usize {
    if text.is_empty() {
        0
    } else {
        ((text.chars().count() as f64) / 4.0).ceil() as usize
    }
}

