#[allow(clippy::type_complexity)]
fn parse_context_budget_sections_order(
    sections: &str,
    order: &str,
) -> Result<Option<(serde_json::Map<String, serde_json::Value>, Vec<String>)>> {
    let sections = match parse_rlm_json_or_edn(sections) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!(
                "failed to parse :sections as JSON or EDN: {error}"
            ))?;
            return Ok(None);
        }
    };
    let Some(sections) = sections.as_object().cloned() else {
        print_json_error(":sections must be a map/object")?;
        return Ok(None);
    };
    let Some(order) = parse_context_budget_key_vec_arg(order, "order")? else {
        return Ok(None);
    };
    Ok(Some((sections, order)))
}

fn parse_context_budget_key_vec_arg(value: &str, name: &str) -> Result<Option<Vec<String>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :{name} as JSON or EDN: {error}"))?;
            return Ok(None);
        }
    };
    let Some(items) = parsed.as_array() else {
        print_json_error(&format!(":{name} must be a vector/array"))?;
        return Ok(None);
    };
    Ok(Some(
        items
            .iter()
            .map(evaluation_display_value)
            .map(|value| normalize_keywordish(&value))
            .filter(|value| !value.is_empty())
            .collect(),
    ))
}

fn parse_context_budget_key_set_arg(value: &str, name: &str) -> Result<Option<BTreeSet<String>>> {
    Ok(parse_context_budget_key_vec_arg(value, name)?
        .map(|items| items.into_iter().collect::<BTreeSet<_>>()))
}

fn context_budget_section_tokens(
    sections: &serde_json::Map<String, serde_json::Value>,
    order: &[String],
) -> BTreeMap<String, usize> {
    let mut tokens = BTreeMap::new();
    for key in order {
        if let Some(text) = rlm_map_get(sections, key).and_then(serde_json::Value::as_str) {
            tokens.insert(key.clone(), estimate_tokens_from_text(text));
        }
    }
    tokens
}

fn context_budget_total_tokens(
    sections: &serde_json::Map<String, serde_json::Value>,
    order: &[String],
) -> usize {
    context_budget_section_tokens(sections, order)
        .values()
        .sum::<usize>()
}

fn context_budget_compose(
    sections: &serde_json::Map<String, serde_json::Value>,
    order: &[String],
) -> String {
    order
        .iter()
        .filter_map(|key| rlm_map_get(sections, key).and_then(serde_json::Value::as_str))
        .filter(|text| !text.trim().is_empty())
        .map(ToString::to_string)
        .collect::<Vec<_>>()
        .join("\n\n")
}

fn context_budget_model_budget(
    max_context_tokens: usize,
    max_output_tokens: usize,
    safety_ratio: f64,
) -> usize {
    let usable = max_context_tokens.saturating_sub(max_output_tokens);
    let margin = ((usable as f64) * safety_ratio.max(0.0)).ceil() as usize;
    usable.saturating_sub(margin)
}

fn context_budget_compactable_keys(
    sections: &serde_json::Map<String, serde_json::Value>,
    order: &[String],
    strategies: &BTreeSet<String>,
) -> Vec<serde_json::Value> {
    let mut compactable = order
        .iter()
        .filter_map(|key| {
            let value = rlm_map_get(sections, key)?;
            if value.is_null() {
                return None;
            }
            let policy = context_budget_policy_for(key)?;
            let strategy = policy.compact?;
            if !strategies.contains(strategy) {
                return None;
            }
            Some((
                policy.priority,
                key.clone(),
                serde_json::json!({
                    "section": key,
                    "priority": policy.priority,
                    "strategy": strategy,
                    "tokens": value.as_str().map(estimate_tokens_from_text).unwrap_or(0),
                }),
            ))
        })
        .collect::<Vec<_>>();
    compactable.sort_by(
        |(left_priority, left_key, _), (right_priority, right_key, _)| {
            left_priority
                .cmp(right_priority)
                .then_with(|| left_key.cmp(right_key))
        },
    );
    compactable.into_iter().map(|(_, _, value)| value).collect()
}

fn context_budget_policy_for(key: &str) -> Option<ContextSectionPolicy> {
    DEFAULT_CONTEXT_SECTION_POLICIES
        .iter()
        .copied()
        .find(|policy| policy.key == key)
}

fn context_budget_policy_json(policy: &ContextSectionPolicy) -> serde_json::Value {
    serde_json::json!({
        "section": policy.key,
        "priority": policy.priority,
        "compact": policy.compact,
    })
}

