fn parse_context_format_array(value: &str, arg_name: &str) -> Result<Vec<serde_json::Value>> {
    let parsed = parse_rlm_json_or_edn(value)
        .with_context(|| format!("failed to parse {arg_name} as JSON or EDN"))?;
    let Some(items) = parsed.as_array() else {
        bail!("{arg_name} must be a JSON or EDN vector");
    };
    Ok(items.clone())
}

fn context_format_conversation(messages: &[serde_json::Value]) -> Option<String> {
    if messages.is_empty() {
        return None;
    }

    Some(
        messages
            .iter()
            .map(|message| {
                let map = message.as_object();
                let role = map
                    .and_then(|map| context_format_field(map, &["role"]))
                    .and_then(context_format_name_value)
                    .unwrap_or_else(|| "unknown".to_string());
                let content = map
                    .and_then(|map| context_format_field(map, &["content"]))
                    .map(context_format_value_string)
                    .unwrap_or_default();
                format!("- **{role}**: {}", context_format_snippet(&content, 500))
            })
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

fn context_format_agent_tools(tools: &[serde_json::Value]) -> Option<String> {
    if tools.is_empty() {
        return None;
    }

    Some(
        tools
            .iter()
            .map(context_format_agent_tool)
            .collect::<Vec<_>>()
            .join("\n\n"),
    )
}

fn context_format_agent_tool(tool: &serde_json::Value) -> String {
    let map = tool.as_object();
    let name = map
        .and_then(|map| context_format_field(map, &["name", "id"]))
        .map(context_format_value_string)
        .unwrap_or_default();
    let description = map
        .and_then(|map| context_format_field(map, &["description", "desc"]))
        .map(context_format_value_string)
        .unwrap_or_default();
    let type_tag = map
        .and_then(|map| context_format_field(map, &["tool-fn-type", "toolFnType", "type"]))
        .and_then(context_format_name_value)
        .filter(|value| !value.trim().is_empty())
        .map(|value| format!(" [{value}]"))
        .unwrap_or_default();

    let mut rendered = format!("- `{name}`{type_tag}");
    if !description.trim().is_empty() {
        rendered.push_str(&format!(" — {description}"));
    }
    if let Some(input_lines) = map.and_then(context_format_input_lines) {
        rendered.push_str("\n  Inputs:\n");
        rendered.push_str(&input_lines);
    }
    if let Some(output_lines) = map.and_then(context_format_output_lines) {
        rendered.push_str("\n  Outputs:\n");
        rendered.push_str(&output_lines);
    }
    rendered
}

fn context_format_agent_tools_compact(tools: &[serde_json::Value]) -> Option<String> {
    if tools.is_empty() {
        return None;
    }

    Some(
        tools
            .iter()
            .map(|tool| {
                let map = tool.as_object();
                let name = map
                    .and_then(|map| context_format_field(map, &["name", "id"]))
                    .map(context_format_value_string)
                    .unwrap_or_default();
                let type_tag = map
                    .and_then(|map| {
                        context_format_field(map, &["tool-fn-type", "toolFnType", "type"])
                    })
                    .and_then(context_format_name_value)
                    .filter(|value| !value.trim().is_empty())
                    .map(|value| format!(" ({value})"))
                    .unwrap_or_default();
                format!("- `{name}`{type_tag}")
            })
            .collect::<Vec<_>>()
            .join("\n"),
    )
}

fn context_format_input_lines(map: &serde_json::Map<String, serde_json::Value>) -> Option<String> {
    let parameters = context_format_field(map, &["parameters"]);
    if let Some(parameters_map) = parameters.and_then(serde_json::Value::as_object) {
        if let Some(properties) = context_format_field(parameters_map, &["properties"])
            .and_then(serde_json::Value::as_object)
        {
            let required = context_format_required_set(parameters_map);
            let lines = properties
                .iter()
                .map(|(arg, spec)| {
                    let arg_name = context_format_name_raw(arg);
                    context_format_arg_line(&arg_name, spec, required.contains(&arg_name))
                })
                .collect::<Vec<_>>();
            if !lines.is_empty() {
                return Some(lines.join("\n"));
            }
        }
    }

    let input_schema = context_format_field(map, &["input-schema", "inputSchema"])?;
    let lines = context_format_malli_map_entries(input_schema)
        .into_iter()
        .map(|entry| context_format_arg_line(&entry.name, &entry.spec, !entry.optional))
        .collect::<Vec<_>>();
    (!lines.is_empty()).then(|| lines.join("\n"))
}

fn context_format_output_lines(map: &serde_json::Map<String, serde_json::Value>) -> Option<String> {
    if let Some(outputs) = context_format_field(map, &["outputs"]) {
        let lines = match outputs {
            serde_json::Value::Array(items) => items
                .iter()
                .filter_map(|item| {
                    let item_map = item.as_object()?;
                    let key = context_format_field(item_map, &["name", "key", "id"])
                        .and_then(context_format_name_value)?;
                    Some(context_format_output_line(&key, item))
                })
                .collect::<Vec<_>>(),
            serde_json::Value::Object(object) => object
                .iter()
                .map(|(key, spec)| context_format_output_line(&context_format_name_raw(key), spec))
                .collect::<Vec<_>>(),
            _ => Vec::new(),
        };
        if !lines.is_empty() {
            return Some(lines.join("\n"));
        }
    }

    let output_schema = context_format_field(map, &["output-schema", "outputSchema"])?;
    let entries = context_format_malli_map_entries(output_schema);
    if !entries.is_empty() {
        return Some(
            entries
                .into_iter()
                .map(|entry| context_format_output_line(&entry.name, &entry.spec))
                .collect::<Vec<_>>()
                .join("\n"),
        );
    }

    let meta = context_format_malli_field(output_schema);
    Some(format!(
        "    {}{}",
        meta.type_name,
        meta.description
            .filter(|description| !description.trim().is_empty())
            .map(|description| format!(" — {description}"))
            .unwrap_or_default()
    ))
}

fn context_format_required_set(
    map: &serde_json::Map<String, serde_json::Value>,
) -> BTreeSet<String> {
    context_format_field(map, &["required"])
        .and_then(serde_json::Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(context_format_name_value)
                .collect::<BTreeSet<_>>()
        })
        .unwrap_or_default()
}

fn context_format_arg_line(arg_name: &str, spec: &serde_json::Value, required: bool) -> String {
    let meta = context_format_json_or_malli_field(spec);
    let optional = if required { "" } else { " (optional)" };
    format!(
        "    - `{arg_name}` : {}{}{}",
        meta.type_name,
        optional,
        meta.description
            .filter(|description| !description.trim().is_empty())
            .map(|description| format!(" — {description}"))
            .unwrap_or_default()
    )
}

fn context_format_output_line(key: &str, spec: &serde_json::Value) -> String {
    let meta = context_format_json_or_malli_field(spec);
    format!(
        "    - `{key}` : {}{}",
        meta.type_name,
        meta.description
            .filter(|description| !description.trim().is_empty())
            .map(|description| format!(" — {description}"))
            .unwrap_or_default()
    )
}

#[derive(Clone, Debug)]
struct ContextFormatMalliEntry {
    name: String,
    spec: serde_json::Value,
    optional: bool,
}

#[derive(Clone, Debug)]
struct ContextFormatFieldMeta {
    type_name: String,
    description: Option<String>,
}

fn context_format_malli_map_entries(schema: &serde_json::Value) -> Vec<ContextFormatMalliEntry> {
    let Some(items) = schema.as_array() else {
        return Vec::new();
    };
    if items.first().and_then(context_format_name_value).as_deref() != Some("map") {
        return Vec::new();
    }

    items
        .iter()
        .skip(1)
        .filter_map(|entry| {
            let entry_items = entry.as_array()?;
            let name = entry_items.first().and_then(context_format_name_value)?;
            let mut optional = false;
            let spec = if entry_items.len() >= 3 {
                if let Some(options) = entry_items.get(1).and_then(serde_json::Value::as_object) {
                    optional = context_format_field(options, &["optional"])
                        .and_then(serde_json::Value::as_bool)
                        .unwrap_or(false);
                    entry_items.get(2).cloned()
                } else {
                    entry_items.get(1).cloned()
                }
            } else {
                entry_items.get(1).cloned()
            }?;
            Some(ContextFormatMalliEntry {
                name,
                spec,
                optional,
            })
        })
        .collect()
}

fn context_format_json_or_malli_field(spec: &serde_json::Value) -> ContextFormatFieldMeta {
    if let Some(map) = spec.as_object() {
        let type_name = context_format_field(map, &["type"])
            .map(context_format_value_string)
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| "any".to_string());
        let description = context_format_field(map, &["description", "desc"])
            .map(context_format_value_string)
            .filter(|value| !value.trim().is_empty());
        return ContextFormatFieldMeta {
            type_name,
            description,
        };
    }
    context_format_malli_field(spec)
}

fn context_format_malli_field(spec: &serde_json::Value) -> ContextFormatFieldMeta {
    match spec {
        serde_json::Value::Array(items) => {
            let type_name = items
                .first()
                .and_then(context_format_name_value)
                .unwrap_or_else(|| "any".to_string());
            let description = items
                .iter()
                .filter_map(serde_json::Value::as_object)
                .find_map(|map| {
                    context_format_field(map, &["desc", "description"])
                        .map(context_format_value_string)
                })
                .filter(|value| !value.trim().is_empty());
            ContextFormatFieldMeta {
                type_name,
                description,
            }
        }
        serde_json::Value::Object(map) => {
            let type_name = context_format_field(map, &["type", "schema"])
                .map(context_format_value_string)
                .filter(|value| !value.trim().is_empty())
                .unwrap_or_else(|| "any".to_string());
            let description = context_format_field(map, &["desc", "description"])
                .map(context_format_value_string)
                .filter(|value| !value.trim().is_empty());
            ContextFormatFieldMeta {
                type_name,
                description,
            }
        }
        _ => ContextFormatFieldMeta {
            type_name: context_format_name_value(spec).unwrap_or_else(|| "any".to_string()),
            description: None,
        },
    }
}

fn context_format_field<'a>(
    map: &'a serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<&'a serde_json::Value> {
    for key in keys {
        if let Some(value) = rlm_map_get(map, key) {
            return Some(value);
        }
    }
    None
}

fn context_format_name_value(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::String(value) => {
            let normalized = context_format_name_raw(value);
            (!normalized.is_empty()).then_some(normalized)
        }
        serde_json::Value::Bool(value) => Some(value.to_string()),
        serde_json::Value::Number(value) => Some(value.to_string()),
        _ => None,
    }
}

fn context_format_name_raw(value: &str) -> String {
    let trimmed = value.trim().trim_start_matches(':');
    trimmed
        .rsplit_once('/')
        .map(|(_, name)| name)
        .unwrap_or(trimmed)
        .to_string()
}

fn context_format_value_string(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => String::new(),
        serde_json::Value::String(value) => value.clone(),
        serde_json::Value::Bool(value) => value.to_string(),
        serde_json::Value::Number(value) => value.to_string(),
        serde_json::Value::Array(_) | serde_json::Value::Object(_) => value.to_string(),
    }
}

fn context_format_snippet(value: &str, max_chars: usize) -> String {
    if value.chars().count() <= max_chars {
        value.to_string()
    } else {
        let mut snippet = value.chars().take(max_chars).collect::<String>();
        snippet.push_str(by_tui::ELLIPSIS);
        snippet
    }
}

fn print_context_actions_recalled_memory(hits_json: String) -> Result<()> {
    let Some(hits) = parse_context_actions_vec_arg(&hits_json, "hits-json")? else {
        return Ok(());
    };
    let rendered = context_actions_format_recalled_memory(&hits);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/format-recalled-memory",
            "hit-count": hits.len(),
            "rendered": rendered,
        }))?
    );
    Ok(())
}

fn print_context_actions_conversation(
    messages_json: String,
    question: String,
    limit: usize,
) -> Result<()> {
    let Some(messages) = parse_context_actions_vec_arg(&messages_json, "messages-json")? else {
        return Ok(());
    };
    let recent_start = messages.len().saturating_sub(limit);
    let recent = messages[recent_start..].to_vec();
    let (conversation, dropped_question_tail) =
        context_actions_drop_question_tail(recent, &question);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/prepare-conversation",
            "original-count": messages.len(),
            "limit": limit,
            "dropped-question-tail?": dropped_question_tail,
            "count": conversation.len(),
            "conversation": conversation,
        }))?
    );
    Ok(())
}

fn print_context_actions_entity_terms(result: String) -> Result<()> {
    let terms = context_actions_extract_entity_terms(&result);
    let count = terms.len();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/extract-entity-terms",
            "terms": terms,
            "count": count,
        }))?
    );
    Ok(())
}

fn print_context_actions_novel_terms(terms_json: String, recalled_text: String) -> Result<()> {
    let Some(terms) = parse_context_actions_terms_arg(&terms_json, "terms-json")? else {
        return Ok(());
    };
    let novel = context_actions_novel_terms(&terms, &recalled_text);
    let count = novel.len();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/novel-terms",
            "terms": terms,
            "novel-terms": novel,
            "count": count,
        }))?
    );
    Ok(())
}

fn print_context_actions_merge_hits(
    existing_json: String,
    new_json: String,
    limit: usize,
) -> Result<()> {
    let Some(existing) = parse_context_actions_vec_arg(&existing_json, "existing-json")? else {
        return Ok(());
    };
    let Some(new_hits) = parse_context_actions_vec_arg(&new_json, "new-json")? else {
        return Ok(());
    };
    let merged = context_actions_merge_hits(&existing, &new_hits, limit);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/merge-hits",
            "existing-count": existing.len(),
            "new-count": new_hits.len(),
            "limit": limit,
            "merged-count": merged.len(),
            "merged": merged,
        }))?
    );
    Ok(())
}

fn print_context_actions_mid_turn_query(
    result: String,
    recalled_text: String,
    min_result_chars: usize,
) -> Result<()> {
    let result_chars = result.chars().count();
    let terms = context_actions_extract_entity_terms(&result);
    let novel = context_actions_novel_terms(&terms, &recalled_text);
    let should_recall = result_chars > min_result_chars && !novel.is_empty();
    let query = if should_recall {
        novel.iter().take(5).cloned().collect::<Vec<_>>().join(" ")
    } else {
        String::new()
    };
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/mid-turn-rerecall-query",
            "result-chars": result_chars,
            "min-result-chars": min_result_chars,
            "terms": terms,
            "novel-terms": novel,
            "should-recall?": should_recall,
            "query": query,
        }))?
    );
    Ok(())
}

fn print_context_actions_tool_cache_decision(
    tool_name: String,
    args: String,
    hits_json: String,
    ttl_s: i64,
) -> Result<()> {
    let args = match parse_rlm_json_or_edn(&args) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :args as JSON or EDN: {error}"))?;
            return Ok(());
        }
    };
    if !args.is_object() {
        print_json_error(":args must be a map/object")?;
        return Ok(());
    }
    let Some(hits) = parse_context_actions_vec_arg(&hits_json, "hits-json")? else {
        return Ok(());
    };
    let normalized_tool_name = normalize_keywordish(&tool_name);
    let normalized_args = loop_guard_normalize_tool_args(&args);
    let decision = if ttl_s > 0 {
        context_actions_tool_cache_decision(&normalized_tool_name, &normalized_args, &hits, ttl_s)
    } else {
        None
    };
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "context-actions/tool-cache-lookup-pre",
            "tool-name": normalized_tool_name,
            "ttl-s": ttl_s,
            "replace?": decision.is_some(),
            "decision": decision.unwrap_or(serde_json::Value::Null),
        }))?
    );
    Ok(())
}

fn parse_context_actions_vec_arg(
    value: &str,
    name: &str,
) -> Result<Option<Vec<serde_json::Value>>> {
    let parsed = match parse_rlm_json_or_edn(value) {
        Ok(value) => value,
        Err(error) => {
            print_json_error(&format!("failed to parse :{name} as JSON or EDN: {error}"))?;
            return Ok(None);
        }
    };
    let Some(items) = parsed.as_array() else {
        print_json_error(&format!(":{name} must be a vector/array"))?;
        return Ok(None);
    };
    Ok(Some(items.clone()))
}

fn parse_context_actions_terms_arg(value: &str, name: &str) -> Result<Option<Vec<String>>> {
    let Some(items) = parse_context_actions_vec_arg(value, name)? else {
        return Ok(None);
    };
    Ok(Some(
        items
            .iter()
            .filter_map(serde_json::Value::as_str)
            .map(ToString::to_string)
            .collect(),
    ))
}

fn context_actions_format_recalled_memory(hits: &[serde_json::Value]) -> String {
    if hits.is_empty() {
        return String::new();
    }

    let mut parts = vec!["## Recalled Memory".to_string()];
    let l2 = hits
        .iter()
        .filter(|hit| context_actions_layer(hit).as_deref() == Some("l2"))
        .map(context_actions_render_l2_hit)
        .collect::<Vec<_>>();
    if !l2.is_empty() {
        parts.push("\n### Episodes (L2 — recent activity)".to_string());
        parts.push(l2.join("\n"));
    }

    let l3 = hits
        .iter()
        .filter(|hit| context_actions_layer(hit).as_deref() == Some("l3"))
        .map(context_actions_render_l3_hit)
        .collect::<Vec<_>>();
    if !l3.is_empty() {
        parts.push("\n### Facts (L3 — long-term)".to_string());
        parts.push(l3.join("\n"));
    }

    let l1 = hits
        .iter()
        .filter(|hit| context_actions_layer(hit).as_deref() == Some("l1"))
        .map(context_actions_render_l1_hit)
        .collect::<Vec<_>>();
    if !l1.is_empty() {
        parts.push("\n### System overlays (L1)".to_string());
        parts.push(l1.join("\n"));
    }

    let other = hits
        .iter()
        .filter(|hit| {
            !matches!(
                context_actions_layer(hit).as_deref(),
                Some("l1" | "l2" | "l3")
            )
        })
        .map(|hit| format!("- {}", context_actions_snip(&context_actions_content(hit))))
        .collect::<Vec<_>>();
    if !other.is_empty() {
        parts.push("\n### Other".to_string());
        parts.push(other.join("\n"));
    }

    parts.join("\n")
}

fn context_actions_render_l2_hit(hit: &serde_json::Value) -> String {
    let date = context_actions_format_date(context_actions_field(hit, "created-at"));
    let role = context_actions_field(hit, "role")
        .map(evaluation_display_value)
        .unwrap_or_else(|| "unknown".to_string());
    let prefix = if !date.is_empty() && !role.is_empty() {
        format!("[{date} {role}] ")
    } else if !date.is_empty() {
        format!("[{date}] ")
    } else if !role.is_empty() {
        format!("[{role}] ")
    } else {
        String::new()
    };
    format!(
        "- {prefix}{}",
        context_actions_snip(&context_actions_content(hit))
    )
}

fn context_actions_render_l3_hit(hit: &serde_json::Value) -> String {
    let kind_label = context_actions_kind(hit).and_then(|kind| {
        if kind == "fact" {
            None
        } else {
            Some(format!("({kind}) "))
        }
    });
    let tag_label = context_actions_tags_label(hit);
    format!(
        "- {}{}{}",
        kind_label.unwrap_or_default(),
        tag_label.unwrap_or_default(),
        context_actions_snip(&context_actions_content(hit))
    )
}

fn context_actions_render_l1_hit(hit: &serde_json::Value) -> String {
    let kind = context_actions_kind(hit).unwrap_or_else(|| "overlay".to_string());
    format!(
        "- ({kind} overlay) {}",
        context_actions_snip(&context_actions_content(hit))
    )
}

fn context_actions_drop_question_tail(
    mut messages: Vec<serde_json::Value>,
    question: &str,
) -> (Vec<serde_json::Value>, bool) {
    let question = question.trim();
    if question.is_empty() {
        return (messages, false);
    }
    let should_drop = messages
        .last()
        .and_then(serde_json::Value::as_object)
        .is_some_and(|message| {
            let role = rlm_map_get(message, "role")
                .map(evaluation_display_value)
                .unwrap_or_default();
            let content = rlm_map_get(message, "content").and_then(serde_json::Value::as_str);
            role == "user" && content.is_some_and(|content| content.trim() == question)
        });
    if should_drop {
        messages.pop();
    }
    (messages, should_drop)
}

fn context_actions_extract_entity_terms(result: &str) -> Vec<String> {
    let camel = regex::Regex::new(r"\b[A-Z][A-Za-z0-9_-]{3,}\b")
        .expect("context-actions camel entity regex is valid");
    let ticked = regex::Regex::new(r"`([A-Za-z0-9._/\-$:]{4,})`")
        .expect("context-actions ticked entity regex is valid");
    let mut terms = Vec::new();
    for found in camel.find_iter(result).map(|found| found.as_str()) {
        if !terms.iter().any(|term| term == found) {
            terms.push(found.to_string());
        }
    }
    for captures in ticked.captures_iter(result) {
        if let Some(found) = captures.get(1).map(|found| found.as_str()) {
            if !terms.iter().any(|term| term == found) {
                terms.push(found.to_string());
            }
        }
    }
    terms
}

fn context_actions_novel_terms(terms: &[String], recalled_text: &str) -> Vec<String> {
    terms
        .iter()
        .filter(|term| !term.trim().is_empty() && !recalled_text.contains(term.as_str()))
        .cloned()
        .collect()
}

fn context_actions_merge_hits(
    existing: &[serde_json::Value],
    new_hits: &[serde_json::Value],
    limit: usize,
) -> Vec<serde_json::Value> {
    let seen = existing
        .iter()
        .filter_map(context_actions_hit_content_key)
        .collect::<Vec<_>>();
    existing
        .iter()
        .cloned()
        .chain(
            new_hits
                .iter()
                .filter(|hit| {
                    context_actions_hit_content_key(hit)
                        .is_none_or(|content| !seen.contains(&content))
                })
                .cloned(),
        )
        .take(limit)
        .collect()
}

fn context_actions_tool_cache_decision(
    tool_name: &str,
    args: &serde_json::Map<String, serde_json::Value>,
    hits: &[serde_json::Value],
    ttl_s: i64,
) -> Option<serde_json::Value> {
    hits.iter().enumerate().find_map(|(index, hit)| {
        let data = hit
            .as_object()
            .and_then(|hit| rlm_map_get(hit, "data"))
            .and_then(serde_json::Value::as_object)?;
        let hit_args = rlm_map_get(data, "args")
            .map(loop_guard_normalize_tool_args)
            .unwrap_or_default();
        if hit_args != *args {
            return None;
        }
        let replacement = rlm_map_get(data, "result")?.clone();
        Some(serde_json::json!({
            "result": "replace",
            "replacement": replacement,
            "reason": format!("tool-cache hit for {tool_name} (ttl={ttl_s}s)"),
            "matched-index": index,
        }))
    })
}

fn context_actions_layer(hit: &serde_json::Value) -> Option<String> {
    context_actions_field(hit, "_layer")
        .or_else(|| context_actions_field(hit, "layer"))
        .map(evaluation_display_value)
        .map(|value| normalize_keywordish(&value))
        .filter(|value| !value.is_empty())
}

fn context_actions_kind(hit: &serde_json::Value) -> Option<String> {
    context_actions_field(hit, "kind")
        .map(evaluation_display_value)
        .map(|value| normalize_keywordish(&value))
        .filter(|value| !value.is_empty())
}

fn context_actions_tags_label(hit: &serde_json::Value) -> Option<String> {
    let tags = context_actions_field(hit, "tags")?.as_array()?;
    let tag_str = tags
        .iter()
        .map(evaluation_display_value)
        .filter(|tag| !tag.trim().is_empty())
        .collect::<Vec<_>>()
        .join(", ");
    if tag_str.trim().is_empty() {
        None
    } else {
        Some(format!("[{tag_str}] "))
    }
}

fn context_actions_content(hit: &serde_json::Value) -> String {
    context_actions_field(hit, "content")
        .map(evaluation_display_value)
        .unwrap_or_default()
}

fn context_actions_hit_content_key(hit: &serde_json::Value) -> Option<String> {
    let content = context_actions_field(hit, "content").map(evaluation_display_value)?;
    if content.is_empty() {
        None
    } else {
        Some(content)
    }
}

fn context_actions_field<'a>(
    hit: &'a serde_json::Value,
    key: &str,
) -> Option<&'a serde_json::Value> {
    hit.as_object().and_then(|hit| rlm_map_get(hit, key))
}

fn context_actions_snip(value: &str) -> String {
    if value.chars().count() > 240 {
        format!("{}…", truncate_chars(value, 240))
    } else {
        value.to_string()
    }
}

fn context_actions_format_date(value: Option<&serde_json::Value>) -> String {
    match value {
        Some(serde_json::Value::Number(value)) => value
            .as_i64()
            .map(context_actions_epoch_millis_date)
            .unwrap_or_default(),
        Some(serde_json::Value::String(value)) if context_actions_date_prefix(value).is_some() => {
            context_actions_date_prefix(value).unwrap_or_default()
        }
        _ => String::new(),
    }
}

fn context_actions_date_prefix(value: &str) -> Option<String> {
    let prefix = value.get(0..10)?;
    let bytes = prefix.as_bytes();
    if bytes.len() == 10
        && bytes[0].is_ascii_digit()
        && bytes[1].is_ascii_digit()
        && bytes[2].is_ascii_digit()
        && bytes[3].is_ascii_digit()
        && bytes[4] == b'-'
        && bytes[5].is_ascii_digit()
        && bytes[6].is_ascii_digit()
        && bytes[7] == b'-'
        && bytes[8].is_ascii_digit()
        && bytes[9].is_ascii_digit()
    {
        Some(prefix.to_string())
    } else {
        None
    }
}

fn context_actions_epoch_millis_date(ms: i64) -> String {
    let days = ms.div_euclid(86_400_000);
    let (year, month, day) = civil_from_days(days);
    format!("{year:04}-{month:02}-{day:02}")
}

