fn tool_edit_apply_replacement(
    content: &str,
    pattern: &str,
    replacement: &str,
    regex: bool,
    all: bool,
) -> std::result::Result<(usize, String), String> {
    if regex {
        let re = regex::Regex::new(pattern).map_err(|error| format!("invalid regex: {error}"))?;
        let total = re.find_iter(content).count();
        if total == 0 {
            return Ok((0, content.to_string()));
        }
        let new_content = if all {
            re.replace_all(content, replacement).into_owned()
        } else {
            re.replacen(content, 1, replacement).into_owned()
        };
        Ok((if all { total } else { 1 }, new_content))
    } else {
        let total = content.matches(pattern).count();
        if total == 0 {
            return Ok((0, content.to_string()));
        }
        let new_content = if all {
            content.replace(pattern, replacement)
        } else {
            content.replacen(pattern, replacement, 1)
        };
        Ok((if all { total } else { 1 }, new_content))
    }
}

fn tool_edit_fallback_diff(old_content: &str, new_content: &str, path: &str) -> String {
    let old_lines = old_content.lines().collect::<Vec<_>>();
    let new_lines = new_content.lines().collect::<Vec<_>>();
    let line_count = old_lines.len().max(new_lines.len());
    let chunks = (0..line_count)
        .filter_map(|index| {
            let old_line = old_lines.get(index).copied();
            let new_line = new_lines.get(index).copied();
            (old_line != new_line).then(|| {
                let mut chunk = String::new();
                if let Some(line) = old_line {
                    chunk.push_str("- ");
                    chunk.push_str(line);
                    chunk.push('\n');
                }
                if let Some(line) = new_line {
                    chunk.push_str("+ ");
                    chunk.push_str(line);
                }
                chunk
            })
        })
        .collect::<Vec<_>>();
    format!("--- {path} (old)\n+++ {path} (new)\n{}", chunks.join("\n"))
}

fn tool_edit_query_tokens(query: &str, min_token_len: usize) -> Vec<String> {
    query
        .split_whitespace()
        .map(str::trim)
        .filter(|token| token.chars().count() >= min_token_len)
        .map(ToOwned::to_owned)
        .collect()
}

fn tool_edit_matches_all_tokens(tokens: &[String], text: &str) -> bool {
    if tokens.is_empty() {
        return false;
    }
    let text = text.to_lowercase();
    tokens
        .iter()
        .map(|token| token.to_lowercase())
        .all(|token| text.contains(&token))
}

