fn print_init_doc_detect_sources(
    scope: String,
    project_dir: String,
    user_dir: String,
) -> Result<()> {
    let scope = normalize_keywordish(&scope);
    let scope = if scope.is_empty() {
        "both".to_string()
    } else {
        scope
    };
    if !["both", "project", "user"].contains(&scope.as_str()) {
        print_json_error("scope must be one of: both, project, user")?;
        return Ok(());
    }

    let mut found = Vec::new();
    let mut missing = Vec::new();
    for mut source in init_doc_default_sources() {
        let source_scope = source
            .get("scope")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_string();
        if scope != "both" && source_scope != scope {
            continue;
        }
        let resolved = init_doc_resolve_source_path(&source, &project_dir, &user_dir);
        source.insert("path".to_string(), serde_json::json!(resolved));
        let metadata = std::fs::metadata(
            source
                .get("path")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default(),
        );
        match metadata {
            Ok(metadata) if metadata.is_file() => {
                source.insert("exists?".to_string(), serde_json::json!(true));
                source.insert("size".to_string(), serde_json::json!(metadata.len()));
                if let Ok(modified) = metadata.modified() {
                    if let Some(mtime) = system_time_millis(modified) {
                        source.insert("mtime".to_string(), serde_json::json!(mtime));
                    }
                }
                found.push(serde_json::Value::Object(source));
            }
            _ => {
                source.insert("exists?".to_string(), serde_json::json!(false));
                missing.push(serde_json::Value::Object(source));
            }
        }
    }

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "scope": scope,
            "found": found,
            "missing": missing,
            "projection": "common.init/init$detect-sources",
            "read-skipped?": true,
        }))?
    );
    Ok(())
}

