fn print_init_doc_list_snapshots(
    scope: String,
    limit: usize,
    project_dir: Option<PathBuf>,
    user_dir: Option<PathBuf>,
) -> Result<()> {
    let scopes = match init_doc_parse_scopes(&scope) {
        Ok(scopes) => scopes,
        Err(error) => {
            print_json_error(&error)?;
            return Ok(());
        }
    };
    let dirs = init_doc_dirs(project_dir, user_dir)?;
    let mut records = Vec::new();
    let mut base_dirs = Vec::new();
    for scope in &scopes {
        if let Some(base) = init_doc_scope_dir(&dirs, scope) {
            base_dirs.push(base.display().to_string());
            records.extend(init_doc_snapshot_records(&base, Some(scope))?);
        }
    }
    records.sort_by(|left, right| {
        right
            .ts
            .cmp(&left.ts)
            .then_with(|| right.filename.cmp(&left.filename))
    });
    let snapshots = records
        .iter()
        .take(limit)
        .map(init_doc_snapshot_record_json)
        .collect::<Vec<_>>();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "snapshots": snapshots,
            "scope": init_doc_normalize_list_scope(&scope),
            "base-dirs": base_dirs,
            "projection": "common.init/init$list-snapshots",
        }))?
    );
    Ok(())
}

