fn init_doc_slugify(value: &str, max_chars: usize) -> String {
    let stopwords = [
        "a", "an", "the", "is", "are", "and", "or", "of", "in", "on", "at", "to", "for", "by",
        "with", "from", "as", "but", "if", "then", "than", "so", "what", "where", "when", "who",
        "whom", "why", "how", "which", "do", "does", "did", "can", "could", "would", "should",
        "shall", "will", "this", "that", "these", "those", "it", "its", "we", "they", "you", "i",
        "be", "been", "being", "was", "were", "have", "has", "had",
    ]
    .into_iter()
    .collect::<BTreeSet<_>>();
    let tokens = value
        .to_ascii_lowercase()
        .split(|ch: char| !ch.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty() && !stopwords.contains(token))
        .map(ToOwned::to_owned)
        .collect::<Vec<_>>();
    let mut joined = if tokens.is_empty() {
        "change".to_string()
    } else {
        tokens.join("-")
    };
    if joined.len() > max_chars {
        joined.truncate(max_chars);
    }
    joined
}

fn init_doc_normalize_heading(value: &str) -> String {
    value
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .trim()
        .to_ascii_lowercase()
}

fn init_doc_canonical_heading(value: &str) -> String {
    let normalized = init_doc_normalize_heading(value);
    INIT_DOC_KNOWN_SECTIONS
        .iter()
        .find(|heading| init_doc_normalize_heading(heading) == normalized)
        .map(|heading| (*heading).to_string())
        .unwrap_or_else(|| value.trim().to_string())
}

fn init_doc_parse_sections(body: &str) -> Vec<InitDocSection> {
    if body.trim().is_empty() {
        return Vec::new();
    }
    let mut sections = Vec::<InitDocSection>::new();
    let mut current = Vec::<String>::new();
    let mut heading: Option<String> = None;
    for line in body.lines() {
        let line_trimmed = line.trim_end();
        let maybe_heading = line_trimmed.strip_prefix("##").and_then(|rest| {
            rest.chars()
                .next()
                .is_some_and(char::is_whitespace)
                .then(|| init_doc_canonical_heading(rest.trim()))
        });
        if let Some(next_heading) = maybe_heading {
            if heading.is_some() || !current.is_empty() {
                sections.push(InitDocSection {
                    heading: heading.take(),
                    body: current.join("\n"),
                });
                current.clear();
            }
            heading = Some(next_heading);
        } else {
            current.push(line.to_string());
        }
    }
    if heading.is_some() || !current.is_empty() {
        sections.push(InitDocSection {
            heading,
            body: current.join("\n"),
        });
    }
    sections
}

fn init_doc_sections_json(sections: &[InitDocSection]) -> Vec<serde_json::Value> {
    sections
        .iter()
        .map(|section| {
            serde_json::json!({
                "heading": section.heading.clone(),
                "body": section.body.clone(),
                "body-chars": section.body.chars().count(),
            })
        })
        .collect()
}

fn init_doc_section_titles(sections: &[InitDocSection]) -> BTreeSet<String> {
    sections
        .iter()
        .filter_map(|section| section.heading.as_deref())
        .map(init_doc_normalize_heading)
        .collect()
}

fn init_doc_section_map(sections: &[InitDocSection]) -> BTreeMap<String, &str> {
    sections
        .iter()
        .filter_map(|section| {
            let key = section.heading.as_deref().map(init_doc_normalize_heading)?;
            Some((key, section.body.as_str()))
        })
        .collect()
}

fn init_doc_section_delta(
    before: &[InitDocSection],
    after: &[InitDocSection],
) -> serde_json::Value {
    let before_titles = init_doc_section_titles(before);
    let after_titles = init_doc_section_titles(after);
    let before_map = init_doc_section_map(before);
    let after_map = init_doc_section_map(after);
    let added = after_titles
        .difference(&before_titles)
        .cloned()
        .collect::<Vec<_>>();
    let removed = before_titles
        .difference(&after_titles)
        .cloned()
        .collect::<Vec<_>>();
    let changed = after_titles
        .intersection(&before_titles)
        .filter(|key| before_map.get(*key) != after_map.get(*key))
        .cloned()
        .collect::<Vec<_>>();
    serde_json::json!({
        "added": added,
        "removed": removed,
        "changed": changed,
    })
}

fn init_doc_notes_body(sections: &[InitDocSection]) -> Option<String> {
    sections
        .iter()
        .find(|section| {
            section
                .heading
                .as_deref()
                .is_some_and(|heading| init_doc_normalize_heading(heading) == "notes")
        })
        .map(|section| section.body.trim().to_string())
}

fn init_doc_secret_scan_redacted(body: &str) -> Vec<String> {
    [
        r"sk-[A-Za-z0-9]{20,}",
        r"AKIA[0-9A-Z]{16}",
        r"ASIA[0-9A-Z]{16}",
        r"ghp_[A-Za-z0-9]{20,}",
        r"github_pat_[A-Za-z0-9_]{20,}",
        r"xox[bpoars]-[A-Za-z0-9-]{10,}",
        r"-----BEGIN [A-Z ]*PRIVATE KEY-----",
        r"AIza[0-9A-Za-z_-]{20,}",
    ]
    .iter()
    .filter_map(|pattern| regex::Regex::new(pattern).ok())
    .flat_map(|re| {
        re.find_iter(body)
            .map(|hit| {
                let value = hit.as_str();
                let prefix = value.chars().take(8).collect::<String>();
                format!("{prefix}…")
            })
            .collect::<Vec<_>>()
    })
    .collect()
}

fn init_doc_append_only(before: &str, after: &str) -> bool {
    if before.trim().is_empty() {
        return true;
    }
    let mut need = BTreeMap::<&str, usize>::new();
    for line in before.lines() {
        *need.entry(line).or_default() += 1;
    }
    let mut have = BTreeMap::<&str, usize>::new();
    for line in after.lines() {
        *have.entry(line).or_default() += 1;
    }
    need.iter()
        .all(|(line, count)| have.get(line).copied().unwrap_or_default() >= *count)
}

fn init_doc_validate_apply(opts: InitDocValidateOptions) -> serde_json::Value {
    let scope = normalize_keywordish(&opts.scope);
    let op = normalize_keywordish(&opts.op);
    let valid_scopes = ["project", "user"];
    let valid_ops = ["init", "append", "curate", "reseed", "replace-section"];
    if !valid_scopes.contains(&scope.as_str()) {
        return serde_json::json!({
            "ok?": false,
            "stage": "validate",
            "error": format!("Unknown scope: {}", opts.scope),
        });
    }
    if !valid_ops.contains(&op.as_str()) {
        return serde_json::json!({
            "ok?": false,
            "stage": "validate",
            "error": format!(":op must be one of {:?}", valid_ops),
        });
    }
    if opts.reason.is_empty() {
        return serde_json::json!({
            "ok?": false,
            "stage": "validate",
            "error": ":reason is required (string)",
        });
    }
    let body_len = opts.body.chars().count();
    if body_len > INIT_DOC_SIZE_HARD_CAP {
        return serde_json::json!({
            "ok?": false,
            "stage": "budget-exceeded",
            "size": body_len,
            "cap": INIT_DOC_SIZE_HARD_CAP,
            "hint": "Propose :op :curate or split between :project and :user scopes.",
        });
    }
    let secrets = init_doc_secret_scan_redacted(&opts.body);
    if !secrets.is_empty() {
        return serde_json::json!({
            "ok?": false,
            "stage": "secret-detected",
            "matches": secrets,
            "hint": "BRAINYARD.md is loaded into every agent turn. Put secrets in .env.",
        });
    }

    let current_sections = init_doc_parse_sections(&opts.current);
    let body_sections = init_doc_parse_sections(&opts.body);
    let delta_chars = opts.body.chars().count() as isize - opts.current.chars().count() as isize;
    let notes_violation = matches!(op.as_str(), "curate" | "reseed")
        && init_doc_notes_body(&current_sections)
            .is_some_and(|notes| Some(notes) != init_doc_notes_body(&body_sections));
    if notes_violation {
        return serde_json::json!({
            "ok?": false,
            "stage": "notes-modified",
            "hint": "`## Notes` is the user's verbatim scratchpad; :curate / :reseed must preserve it unchanged. Re-propose with the original `## Notes` section intact.",
        });
    }

    let auto_ok = opts.auto
        && op == "append"
        && (0..=INIT_DOC_AUTO_APPEND_THRESHOLD).contains(&delta_chars)
        && init_doc_append_only(&opts.current, &opts.body);
    let confirmed = opts.confirm || auto_ok;
    let structural = init_doc_section_delta(&current_sections, &body_sections);
    if !confirmed {
        return serde_json::json!({
            "ok?": false,
            "stage": "unconfirmed",
            "hint": if opts.auto {
                "auto-confirmation-required: only an :op :append that adds <= 200 chars AND removes no existing line self-confirms; otherwise pass :confirm? true."
            } else {
                "Surface :diff to the user, then re-call with :confirm? true."
            },
            "diff": fallback_config_diff(&opts.current, &opts.body),
            "structural": structural,
            "delta-chars": delta_chars,
            "auto-ok?": auto_ok,
        });
    }

    if let (Some(expected), Some(actual)) = (opts.expected_mtime, opts.actual_mtime) {
        if expected != actual {
            return serde_json::json!({
                "ok?": false,
                "stage": "mtime-conflict",
                "expected": expected,
                "actual": actual,
                "hint": "BRAINYARD.md changed since you read it. Re-read with init$read.",
            });
        }
    }

    serde_json::json!({
        "ok?": true,
        "scope": scope,
        "op": op,
        "stage": "validated",
        "structural": structural,
        "size-after": body_len,
        "delta-chars": delta_chars,
        "auto-ok?": auto_ok,
        "projection": "common.init/init$apply-validate-prefix",
    })
}

fn init_doc_frontmatter(opts: &InitDocFrontmatterOptions) -> String {
    let scope = normalize_keywordish(&opts.scope);
    let scope = if scope.is_empty() {
        "project"
    } else {
        scope.as_str()
    };
    let mut out = String::new();
    out.push_str("---\n");
    out.push_str("agent: init-agent\n");
    out.push_str(&format!("session-id: {}\n", yaml_string(&opts.session_id)));
    out.push_str(&format!("question: {}\n", yaml_string(&opts.question)));
    out.push_str(&format!("slug: {}\n", opts.slug));
    out.push_str(&format!("scope: {scope}\n"));
    out.push_str(&format!(
        "started: {}\n",
        opts.started.clone().unwrap_or_else(current_iso_utc)
    ));
    if let Some(ended) = &opts.ended {
        out.push_str(&format!("ended: {ended}\n"));
    }
    out.push_str(&format!(
        "brainyard-path: {}\n",
        yaml_string(&opts.brainyard_path)
    ));
    out.push_str(&format!(
        "snapshots: {}\n",
        yaml_flow_vector(&opts.snapshots)
    ));
    out.push_str(&format!("writes: {}\n", opts.writes));
    out.push_str(&format!("reverts: {}\n", opts.reverts));
    out.push_str(&format!(
        "next-steps: {}\n",
        yaml_flow_vector(&opts.next_steps)
    ));
    out.push_str("---\n");
    out
}

fn init_doc_default_sources() -> Vec<serde_json::Map<String, serde_json::Value>> {
    [
        ("claude-md", "project", "CLAUDE.md", "high"),
        ("agents-md", "project", "AGENTS.md", "high"),
        ("readme-md", "project", "README.md", "medium"),
        ("claude-md", "user", "~/.claude/CLAUDE.md", "medium"),
        ("agents-md", "user", "~/.codex/AGENTS.md", "medium"),
        ("cursorrules", "user", "~/.cursorrules", "low"),
    ]
    .into_iter()
    .map(|(source, scope, path, priority)| {
        let mut map = serde_json::Map::new();
        map.insert("source".to_string(), serde_json::json!(source));
        map.insert("scope".to_string(), serde_json::json!(scope));
        map.insert("path".to_string(), serde_json::json!(path));
        map.insert("priority".to_string(), serde_json::json!(priority));
        map
    })
    .collect()
}

fn init_doc_resolve_source_path(
    source: &serde_json::Map<String, serde_json::Value>,
    project_dir: &str,
    user_dir: &str,
) -> String {
    let path = source
        .get("path")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let scope = source
        .get("scope")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    if path.starts_with('/') {
        path.to_string()
    } else if let Some(rest) = path.strip_prefix("~/") {
        format!("{}/{}", user_dir.trim_end_matches('/'), rest)
    } else if scope == "user" {
        format!("{}/{}", user_dir.trim_end_matches('/'), path)
    } else {
        format!("{}/{}", project_dir.trim_end_matches('/'), path)
    }
}

fn init_doc_dirs(project_dir: Option<PathBuf>, user_dir: Option<PathBuf>) -> Result<InitDocDirs> {
    let dirs = process_dirs();
    let project_dir = project_dir
        .or_else(|| dirs.as_ref().map(|dirs| dirs.project_dir.clone()))
        .or_else(|| std::env::current_dir().ok())
        .context("could not determine project directory")?;
    let user_dir = user_dir.or_else(|| dirs.and_then(|dirs| dirs.user_dir));
    Ok(InitDocDirs {
        project_dir,
        user_dir,
    })
}

fn init_doc_parse_scope(value: &str) -> Result<String, String> {
    match normalize_keywordish(value).as_str() {
        "project" => Ok("project".to_string()),
        "user" => Ok("user".to_string()),
        _ => Err(format!("Unknown scope: {}", value.trim())),
    }
}

fn init_doc_parse_scopes(value: &str) -> Result<Vec<String>, String> {
    match normalize_keywordish(value).as_str() {
        "" | "both" => Ok(vec!["project".to_string(), "user".to_string()]),
        "project" => Ok(vec!["project".to_string()]),
        "user" => Ok(vec!["user".to_string()]),
        _ => Err(format!("Unknown scope: {}", value.trim())),
    }
}

fn init_doc_normalize_list_scope(value: &str) -> String {
    let scope = normalize_keywordish(value);
    if scope.is_empty() {
        "both".to_string()
    } else {
        scope
    }
}

fn init_doc_scope_dir(dirs: &InitDocDirs, scope: &str) -> Option<PathBuf> {
    match scope {
        "project" => Some(dirs.project_dir.join(".brainyard")),
        "user" => dirs.user_dir.as_ref().map(|dir| dir.join(".brainyard")),
        _ => None,
    }
}

fn init_doc_brainyard_file(dirs: &InitDocDirs, scope: &str) -> Option<PathBuf> {
    init_doc_scope_dir(dirs, scope).map(|dir| dir.join("BRAINYARD.md"))
}

fn init_doc_read_content(path: &Path) -> Result<Option<String>> {
    if !path.is_file() {
        return Ok(None);
    }
    let raw = std::fs::read_to_string(path)
        .with_context(|| format!("failed to read BRAINYARD.md {}", path.display()))?;
    Ok(Some(raw.trim().to_string()))
}

fn init_doc_read_content_at(dirs: &InitDocDirs, scope: &str) -> Result<String> {
    let Some(path) = init_doc_brainyard_file(dirs, scope) else {
        return Ok(String::new());
    };
    Ok(init_doc_read_content(&path)?.unwrap_or_default())
}

fn init_doc_one_scope_read(dirs: &InitDocDirs, scope: &str) -> Result<serde_json::Value> {
    let Some(path) = init_doc_brainyard_file(dirs, scope) else {
        return Ok(serde_json::json!({
            "scope": scope,
            "path": serde_json::Value::Null,
            "exists?": false,
        }));
    };
    let Some(content) = init_doc_read_content(&path)? else {
        return Ok(serde_json::json!({
            "scope": scope,
            "path": path.display().to_string(),
            "exists?": false,
        }));
    };
    let metadata = std::fs::metadata(&path)
        .with_context(|| format!("failed to stat BRAINYARD.md {}", path.display()))?;
    Ok(serde_json::json!({
        "scope": scope,
        "path": path.display().to_string(),
        "exists?": true,
        "size": metadata.len(),
        "mtime": fs_modified_millis(&path),
        "content": content,
        "sections": init_doc_sections_json(&init_doc_parse_sections(&content)),
    }))
}

fn init_doc_smoke_test_scope(
    dirs: &InitDocDirs,
    scope: &str,
    projected_body: Option<&str>,
) -> Result<serde_json::Value> {
    let Some(path) = init_doc_brainyard_file(dirs, scope) else {
        return Ok(serde_json::json!({
            "ok?": false,
            "reason": "no-config-dir",
            "scope": scope,
        }));
    };
    let content = match projected_body {
        Some(body) => Some(body.trim().to_string()),
        None => init_doc_read_content(&path)?,
    };
    let Some(content) = content else {
        return Ok(serde_json::json!({
            "ok?": true,
            "reason": "absent",
            "scope": scope,
            "size": 0,
            "reload-skipped?": true,
        }));
    };
    let size = content.len();
    if size > INIT_DOC_SIZE_HARD_CAP {
        return Ok(serde_json::json!({
            "ok?": false,
            "reason": "over-hard-cap",
            "scope": scope,
            "size": size,
            "cap": INIT_DOC_SIZE_HARD_CAP,
            "reload-skipped?": true,
        }));
    }
    let sections = init_doc_parse_sections(&content);
    Ok(serde_json::json!({
        "ok?": true,
        "scope": scope,
        "size": size,
        "soft-target": if scope == "project" { 4096 } else { 2048 },
        "cap": INIT_DOC_SIZE_HARD_CAP,
        "section-count": sections.len(),
        "sections": sections.iter().map(|section| {
            section.heading.clone().unwrap_or_default()
        }).collect::<Vec<_>>(),
        "reload-skipped?": true,
        "projected?": projected_body.is_some(),
    }))
}

fn init_doc_now_ts() -> String {
    let seconds = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs() as i64)
        .unwrap_or(0);
    let days = seconds.div_euclid(86_400);
    let seconds_of_day = seconds.rem_euclid(86_400);
    let (year, month, day) = main_civil_from_days(days);
    let hour = seconds_of_day / 3_600;
    let minute = (seconds_of_day % 3_600) / 60;
    let second = seconds_of_day % 60;
    format!("{year:04}{month:02}{day:02}-{hour:02}{minute:02}{second:02}")
}

fn init_doc_snapshot_filename(timestamp: &str, scope: &str, reason: &str) -> String {
    format!(
        "{}-{}-{}.md",
        timestamp,
        scope,
        init_doc_slugify(
            if reason.is_empty() {
                "snapshot"
            } else {
                reason
            },
            60
        )
    )
}

fn init_doc_snapshot_dir(base: &Path) -> PathBuf {
    base.join("agents").join("init-agent").join("snapshots")
}

fn init_doc_snapshot_records(
    base: &Path,
    scope_filter: Option<&str>,
) -> Result<Vec<InitDocSnapshotRecord>> {
    let dir = init_doc_snapshot_dir(base);
    if !dir.is_dir() {
        return Ok(Vec::new());
    }
    let mut records = Vec::new();
    for entry in std::fs::read_dir(&dir)
        .with_context(|| format!("failed to read snapshot dir {}", dir.display()))?
    {
        let entry = entry?;
        if !entry.file_type()?.is_file() {
            continue;
        }
        let path = entry.path();
        let filename = entry.file_name().to_string_lossy().to_string();
        let Some(parsed) = init_doc_parse_snapshot_name_parts(&filename) else {
            continue;
        };
        if scope_filter.is_some_and(|scope| scope != parsed.1) {
            continue;
        }
        let metadata = std::fs::metadata(&path)
            .with_context(|| format!("failed to stat snapshot {}", path.display()))?;
        records.push(InitDocSnapshotRecord {
            ts: parsed.0,
            scope: parsed.1,
            reason: parsed.2,
            path,
            filename,
            size_bytes: metadata.len(),
            mtime: fs_modified_millis(&entry.path()),
        });
    }
    records.sort_by(|left, right| {
        right
            .ts
            .cmp(&left.ts)
            .then_with(|| right.filename.cmp(&left.filename))
    });
    Ok(records)
}

fn init_doc_snapshot_record_json(record: &InitDocSnapshotRecord) -> serde_json::Value {
    serde_json::json!({
        "ts": record.ts,
        "scope": record.scope,
        "reason": record.reason,
        "path": record.path.display().to_string(),
        "filename": record.filename,
        "size-bytes": record.size_bytes,
        "mtime": record.mtime,
    })
}

fn init_doc_find_snapshot(
    dirs: &InitDocDirs,
    snapshot_path: Option<&Path>,
    scope: Option<&str>,
    steps: Option<usize>,
) -> Result<std::result::Result<InitDocSnapshotRecord, String>> {
    if let Some(path) = snapshot_path {
        if !path.is_file() {
            return Ok(Err(format!("Snapshot not found: {}", path.display())));
        }
        let filename = path
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or_default()
            .to_string();
        let Some(parsed) = init_doc_parse_snapshot_name_parts(&filename) else {
            return Ok(Err(
                "Could not parse scope from snapshot filename.".to_string()
            ));
        };
        let metadata = std::fs::metadata(path)
            .with_context(|| format!("failed to stat snapshot {}", path.display()))?;
        return Ok(Ok(InitDocSnapshotRecord {
            ts: parsed.0,
            scope: parsed.1,
            reason: parsed.2,
            path: path.to_path_buf(),
            filename,
            size_bytes: metadata.len(),
            mtime: fs_modified_millis(path),
        }));
    }

    let Some(scope) = scope else {
        return Ok(Err(
            "Provide :snapshot-path, or (:scope + :steps).".to_string()
        ));
    };
    let scope = match init_doc_parse_scope(scope) {
        Ok(scope) => scope,
        Err(error) => return Ok(Err(error)),
    };
    let Some(steps) = steps else {
        return Ok(Err(
            "Provide :snapshot-path, or (:scope + :steps).".to_string()
        ));
    };
    let Some(base) = init_doc_scope_dir(dirs, &scope) else {
        return Ok(Err(format!("No .brainyard/ dir for scope {scope}")));
    };
    let records = init_doc_snapshot_records(&base, Some(&scope))?;
    if steps < 1 || records.is_empty() {
        return Ok(Err("No snapshots available at this scope.".to_string()));
    }
    if steps > records.len() {
        return Ok(Err(format!(
            ":steps {steps} exceeds {} available snapshots at {scope}.",
            records.len()
        )));
    }
    Ok(Ok(records
        .into_iter()
        .nth(steps - 1)
        .expect("bounded step")))
}

fn init_doc_parse_snapshot_name(filename: &str) -> Option<serde_json::Value> {
    let re = regex::Regex::new(r"^(\d{8}-\d{6})-(project|user)-(.+)\.md$").ok()?;
    let captures = re.captures(filename)?;
    Some(serde_json::json!({
        "ts": captures.get(1)?.as_str(),
        "scope": captures.get(2)?.as_str(),
        "reason": captures.get(3)?.as_str(),
    }))
}

fn init_doc_parse_snapshot_name_parts(filename: &str) -> Option<(String, String, String)> {
    let re = regex::Regex::new(r"^(\d{8}-\d{6})-(project|user)-(.+)\.md$").ok()?;
    let captures = re.captures(filename)?;
    Some((
        captures.get(1)?.as_str().to_string(),
        captures.get(2)?.as_str().to_string(),
        captures.get(3)?.as_str().to_string(),
    ))
}

fn print_aws_list_profiles(aws_dir: Option<PathBuf>, user_dir: Option<PathBuf>) -> Result<()> {
    let aws_dir = resolve_aws_dir(aws_dir, user_dir.as_deref())?;
    let profiles = read_aws_profiles(&aws_dir)?;
    let profile_list = profiles
        .iter()
        .map(|(name, data)| {
            serde_json::json!({
                "name": name,
                "region": data.get("region").map(String::as_str).unwrap_or("not set"),
                "source": data.get("_source").map(String::as_str).unwrap_or("unknown"),
            })
        })
        .collect::<Vec<_>>();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "common.aws-commands/aws$list-profiles",
            "result": {
                "profiles": profile_list,
                "total": profile_list.len(),
            }
        }))?
    );
    Ok(())
}

fn print_aws_get_profile(
    profile_name: Option<String>,
    aws_dir: Option<PathBuf>,
    user_dir: Option<PathBuf>,
) -> Result<()> {
    let Some(profile_name) = profile_name.map(|value| value.trim().to_string()) else {
        print_json_error("profile-name is required")?;
        return Ok(());
    };
    if profile_name.is_empty() {
        print_json_error("profile-name is required")?;
        return Ok(());
    }

    let aws_dir = resolve_aws_dir(aws_dir, user_dir.as_deref())?;
    let profiles = read_aws_profiles(&aws_dir)?;
    let Some(data) = profiles.get(&profile_name) else {
        print_json_error(&format!("Profile '{profile_name}' not found"))?;
        return Ok(());
    };

    let mut detail = serde_json::Map::new();
    detail.insert("name".to_string(), serde_json::json!(profile_name));
    detail.insert(
        "region".to_string(),
        serde_json::json!(data.get("region").map(String::as_str).unwrap_or("not set")),
    );
    detail.insert(
        "source".to_string(),
        serde_json::json!(data.get("_source").map(String::as_str).unwrap_or("unknown")),
    );
    for (source_key, output_key, masked) in [
        ("aws_access_key_id", "access-key-id", true),
        ("aws_secret_access_key", "secret-access-key", true),
        ("sso_start_url", "sso-start-url", false),
        ("sso_account_id", "sso-account-id", false),
        ("sso_role_name", "sso-role-name", false),
        ("sso_region", "sso-region", false),
        ("sso_session", "sso-session", false),
        ("role_arn", "role-arn", false),
        ("source_profile", "source-profile", false),
        ("credential_process", "credential-process", false),
    ] {
        if let Some(value) = data.get(source_key) {
            let value = if masked {
                mask_aws_value(value)
            } else {
                value.clone()
            };
            detail.insert(output_key.to_string(), serde_json::json!(value));
        }
    }

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "common.aws-commands/aws$get-profile",
            "result": detail
        }))?
    );
    Ok(())
}

