fn rlm_build_trajectory_entry(
    iteration: serde_json::Value,
    eval_results: &serde_json::Value,
    error: Option<&str>,
    response_text: Option<&str>,
) -> serde_json::Value {
    let mut code = Vec::new();
    let mut output = Vec::new();
    if let Some(items) = eval_results.as_array() {
        for item in items {
            if let Some(map) = item.as_object() {
                if let Some(value) = rlm_map_get(map, "code").and_then(rlm_trajectory_text_value) {
                    code.push(serde_json::json!(value));
                }
                if let Some(value) = rlm_map_get(map, "output").and_then(rlm_trajectory_text_value)
                {
                    if !value.trim().is_empty() {
                        output.push(serde_json::json!(value));
                    }
                }
            }
        }
    }
    if let Some(error) = error {
        output.push(serde_json::json!(format!("ERROR: {error}")));
    }

    let mut entry = serde_json::Map::new();
    entry.insert("iteration".to_string(), iteration);
    if !code.is_empty() {
        entry.insert("code".to_string(), serde_json::Value::Array(code));
    }
    if !output.is_empty() {
        entry.insert("output".to_string(), serde_json::Value::Array(output));
    }
    if let Some(response_text) = response_text {
        entry.insert(
            "reasoning".to_string(),
            rlm_extract_reasoning(response_text)
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null),
        );
    }
    serde_json::Value::Object(entry)
}

#[allow(clippy::too_many_arguments)]
fn rlm_build_trajectory(
    question: &str,
    result: &serde_json::Value,
    model: Option<&str>,
    usage_summary: Option<&serde_json::Value>,
    agent_id: Option<&str>,
    session_id: Option<&str>,
    depth: Option<i64>,
    context_keys: &[String],
    started_at: Option<i64>,
    ended_at: Option<i64>,
) -> serde_json::Value {
    let result_map = result.as_object();
    let iterations = result_map
        .and_then(|map| rlm_map_get(map, "iterations"))
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let trajectory_entries = iterations
        .iter()
        .enumerate()
        .map(|(idx, item)| {
            if let Some(map) = item.as_object() {
                let iteration = rlm_map_get(map, "iteration")
                    .cloned()
                    .unwrap_or_else(|| serde_json::json!(idx + 1));
                let eval_results = rlm_map_get(map, "eval-results")
                    .cloned()
                    .unwrap_or_else(|| serde_json::Value::Array(Vec::new()));
                let error = rlm_map_get(map, "error").and_then(rlm_trajectory_text_value);
                rlm_build_trajectory_entry(iteration, &eval_results, error.as_deref(), None)
            } else {
                rlm_build_trajectory_entry(
                    serde_json::json!(idx + 1),
                    &serde_json::Value::Array(Vec::new()),
                    None,
                    None,
                )
            }
        })
        .collect::<Vec<_>>();

    let terminated_by = result_map
        .and_then(|map| rlm_map_get(map, "terminated-by"))
        .and_then(json_scalar_string)
        .map(|value| normalize_rlm_key(&value));
    let success = terminated_by.as_deref() == Some("final");
    let total_iterations = result_map
        .and_then(|map| rlm_map_get(map, "total-iterations"))
        .cloned()
        .unwrap_or_else(|| serde_json::json!(iterations.len()));
    let cost = usage_summary.and_then(rlm_usage_total_cost);
    let context_keys = context_keys
        .iter()
        .map(|key| normalize_rlm_key(key))
        .filter(|key| !key.is_empty())
        .collect::<Vec<_>>();

    let mut trajectory = serde_json::Map::new();
    trajectory.insert("query".to_string(), serde_json::json!(question));
    trajectory.insert(
        "trajectory".to_string(),
        serde_json::Value::Array(trajectory_entries),
    );
    trajectory.insert("success".to_string(), serde_json::json!(success));
    trajectory.insert(
        "terminated-by".to_string(),
        terminated_by
            .map(serde_json::Value::String)
            .unwrap_or(serde_json::Value::Null),
    );
    trajectory.insert("total-iterations".to_string(), total_iterations);

    if let Some(answer) = result_map
        .and_then(|map| rlm_map_get(map, "answer"))
        .filter(|value| rlm_json_truthy(value))
        .cloned()
    {
        trajectory.insert("answer".to_string(), answer);
    }
    if !context_keys.is_empty() {
        trajectory.insert(
            "context-summary".to_string(),
            serde_json::json!(format!("Context keys: {}", context_keys.join(", "))),
        );
    }
    if let Some(cost) = cost {
        trajectory.insert("cost".to_string(), rlm_json_number(cost));
    }
    if let Some(model) = model {
        trajectory.insert("model".to_string(), serde_json::json!(model));
    }
    if let Some(started_at) = started_at {
        let ended_at = ended_at.unwrap_or_else(current_epoch_millis_i64);
        trajectory.insert(
            "timing".to_string(),
            serde_json::json!({
                "started-at": started_at,
                "ended-at": ended_at,
                "duration-ms": ended_at - started_at,
            }),
        );
    }
    if agent_id.is_some() || session_id.is_some() || depth.is_some() {
        let mut metadata = serde_json::Map::new();
        if let Some(agent_id) = agent_id {
            metadata.insert("agent-id".to_string(), serde_json::json!(agent_id));
        }
        if let Some(session_id) = session_id {
            metadata.insert("session-id".to_string(), serde_json::json!(session_id));
        }
        if let Some(depth) = depth {
            metadata.insert("depth".to_string(), serde_json::json!(depth));
        }
        trajectory.insert("metadata".to_string(), serde_json::Value::Object(metadata));
    }

    serde_json::Value::Object(trajectory)
}

fn rlm_trajectory_summary(trajectory: &serde_json::Value) -> serde_json::Value {
    let Some(map) = trajectory.as_object() else {
        return serde_json::json!({ "error": ":trajectory must be a map/object" });
    };

    let mut summary = serde_json::Map::new();
    summary.insert(
        "id".to_string(),
        rlm_map_get(map, "id")
            .cloned()
            .unwrap_or(serde_json::Value::Null),
    );
    summary.insert(
        "query".to_string(),
        rlm_map_get(map, "query")
            .map(|value| rlm_truncate_json_text(value, 100))
            .unwrap_or(serde_json::Value::Null),
    );
    summary.insert(
        "success".to_string(),
        rlm_map_get(map, "success")
            .cloned()
            .unwrap_or(serde_json::Value::Null),
    );
    summary.insert(
        "terminated-by".to_string(),
        rlm_map_get(map, "terminated-by")
            .cloned()
            .unwrap_or(serde_json::Value::Null),
    );
    summary.insert(
        "total-iterations".to_string(),
        rlm_map_get(map, "total-iterations")
            .cloned()
            .unwrap_or(serde_json::Value::Null),
    );

    if let Some(answer) = rlm_map_get(map, "answer").filter(|value| rlm_json_truthy(value)) {
        summary.insert("answer".to_string(), rlm_truncate_json_text(answer, 500));
    }
    if let Some(cost) = rlm_map_get(map, "cost") {
        summary.insert("cost".to_string(), cost.clone());
    }
    if let Some(model) = rlm_map_get(map, "model") {
        summary.insert("model".to_string(), model.clone());
    }
    if let Some(timing) = rlm_map_get(map, "timing").and_then(serde_json::Value::as_object) {
        if let Some(duration) = rlm_map_get(timing, "duration-ms") {
            summary.insert("duration-ms".to_string(), duration.clone());
        }
    }
    if let Some(metadata) = rlm_map_get(map, "metadata") {
        summary.insert("metadata".to_string(), metadata.clone());
    }
    if let Some(entries) = rlm_map_get(map, "trajectory")
        .and_then(serde_json::Value::as_array)
        .filter(|entries| !entries.is_empty())
    {
        let entries = entries
            .iter()
            .filter_map(rlm_trajectory_iteration_summary)
            .collect::<Vec<_>>();
        summary.insert("iterations".to_string(), serde_json::Value::Array(entries));
    }

    serde_json::Value::Object(summary)
}

fn rlm_trajectory_format_export(trajectory: &serde_json::Value) -> serde_json::Value {
    let Some(map) = trajectory.as_object() else {
        return serde_json::json!({ "error": ":trajectory must be a map/object" });
    };
    let mut export = serde_json::Map::new();
    for key in [
        "query",
        "context-summary",
        "trajectory",
        "answer",
        "success",
        "cost",
        "model",
        "total-iterations",
    ] {
        if let Some(value) = rlm_map_get(map, key) {
            export.insert(key.to_string(), value.clone());
        }
    }
    serde_json::Value::Object(export)
}

fn rlm_trajectory_iteration_summary(entry: &serde_json::Value) -> Option<serde_json::Value> {
    let map = entry.as_object()?;
    let output = rlm_map_get(map, "output")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    let output_strings = output
        .iter()
        .filter_map(rlm_trajectory_text_value)
        .collect::<Vec<_>>();
    let has_code = rlm_map_get(map, "code")
        .map(|value| match value {
            serde_json::Value::Array(items) => !items.is_empty(),
            serde_json::Value::Null => false,
            serde_json::Value::String(value) => !value.is_empty(),
            _ => true,
        })
        .unwrap_or(false);
    let has_error = output_strings
        .iter()
        .any(|value| value.starts_with("ERROR:"));
    let output_length = output_strings
        .iter()
        .map(|value| value.chars().count())
        .sum::<usize>();

    Some(serde_json::json!({
        "iteration": rlm_map_get(map, "iteration").cloned().unwrap_or(serde_json::Value::Null),
        "has-code": has_code,
        "has-error": has_error,
        "output-length": output_length,
    }))
}

fn rlm_extract_reasoning(response_text: &str) -> Option<String> {
    let code_block = regex::Regex::new(r"(?s)```(?:clojure|clj)\s*\n.*?```")
        .expect("trajectory code-fence regex is valid");
    let without_code = code_block.replace_all(response_text, "");
    let lines = without_code
        .lines()
        .filter(|line| !line.trim().is_empty())
        .collect::<Vec<_>>()
        .join("\n");
    let lines = lines.trim();
    if lines.is_empty() {
        None
    } else {
        Some(lines.to_string())
    }
}

fn rlm_usage_total_cost(usage_summary: &serde_json::Value) -> Option<f64> {
    let map = usage_summary.as_object()?;
    if let Some(totals) = rlm_map_get(map, "totals").and_then(serde_json::Value::as_object) {
        if let Some(cost) = rlm_map_get(totals, "total-cost").and_then(rlm_json_to_f64) {
            return Some(cost);
        }
    }
    rlm_map_get(map, "total-cost").and_then(rlm_json_to_f64)
}

fn rlm_json_to_f64(value: &serde_json::Value) -> Option<f64> {
    match value {
        serde_json::Value::Number(value) => value.as_f64(),
        serde_json::Value::String(value) => value.parse::<f64>().ok(),
        _ => None,
    }
}

fn rlm_json_truthy(value: &serde_json::Value) -> bool {
    !matches!(
        value,
        serde_json::Value::Null | serde_json::Value::Bool(false)
    )
}

fn rlm_trajectory_text_value(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Null => None,
        serde_json::Value::String(value) => Some(value.clone()),
        serde_json::Value::Bool(value) => Some(value.to_string()),
        serde_json::Value::Number(value) => Some(value.to_string()),
        value => Some(value.to_string()),
    }
}

fn rlm_truncate_json_text(value: &serde_json::Value, max_chars: usize) -> serde_json::Value {
    match rlm_trajectory_text_value(value) {
        Some(value) if value.chars().count() > max_chars => {
            serde_json::json!(format!("{}...", truncate_chars(&value, max_chars)))
        }
        Some(value) => serde_json::json!(value),
        None => serde_json::Value::Null,
    }
}

fn current_epoch_millis_i64() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis().min(i64::MAX as u128) as i64)
        .unwrap_or(0)
}

fn rlm_chunk_text(text: &str, size: usize, overlap: usize) -> serde_json::Value {
    if size == 0 {
        return serde_json::json!({ "error": ":size must be a positive integer" });
    }
    if overlap >= size {
        return serde_json::json!({ "error": ":overlap must be < :size" });
    }
    if text.trim().is_empty() {
        return serde_json::json!({ "chunks": [], "n-chunks": 0 });
    }

    let chars = text.chars().collect::<Vec<_>>();
    if chars.len() <= size {
        return serde_json::json!({ "chunks": [text], "n-chunks": 1 });
    }

    let step = std::cmp::max(1, size - overlap);
    let mut chunks = Vec::new();
    let mut start = 0usize;
    while start < chars.len() {
        let end = std::cmp::min(chars.len(), start + size);
        chunks.push(chars[start..end].iter().collect::<String>());
        if end >= chars.len() {
            break;
        }
        start += step;
    }
    serde_json::json!({ "chunks": chunks, "n-chunks": chunks.len() })
}

#[derive(Clone, Debug)]
struct RlmFileRead {
    path: String,
    content: Option<String>,
    error: Option<String>,
}

fn rlm_read_file_safely(path: &PathBuf) -> RlmFileRead {
    match std::fs::read_to_string(path) {
        Ok(content) => RlmFileRead {
            path: path.display().to_string(),
            content: Some(content),
            error: None,
        },
        Err(error) => RlmFileRead {
            path: path.display().to_string(),
            content: None,
            error: Some(error.to_string()),
        },
    }
}

fn rlm_pack_file_groups(
    files: &[RlmFileRead],
    group_size: usize,
    max_bytes: usize,
) -> Vec<Vec<RlmFileRead>> {
    let mut groups = Vec::new();
    let mut current = Vec::new();
    let mut current_bytes = 0usize;

    for file in files {
        let file_bytes = file.content.as_deref().unwrap_or_default().len();
        if !current.is_empty()
            && (current.len() >= group_size || current_bytes + file_bytes > max_bytes)
        {
            groups.push(current);
            current = Vec::new();
            current_bytes = 0;
        }
        current.push(file.clone());
        current_bytes += file_bytes;
    }

    if !current.is_empty() {
        groups.push(current);
    }
    groups
}

fn rlm_stitch_group(group: &[RlmFileRead], separator: &str) -> String {
    group
        .iter()
        .map(|file| {
            format!(
                "=== {} ===\n{}",
                file.path,
                file.content.as_deref().unwrap_or_default()
            )
        })
        .collect::<Vec<_>>()
        .join(separator)
}

fn rlm_parse_shape(value: &str) -> Option<String> {
    match normalize_rlm_key(value).as_str() {
        "json" => Some("json".to_string()),
        "edn" => Some("edn".to_string()),
        _ => None,
    }
}

fn rlm_parse_one(value: &str, shape: &str) -> Option<serde_json::Value> {
    if value.trim().is_empty() {
        return None;
    }

    let (first, second) = if shape == "edn" {
        (
            try_rlm_edn as fn(&str) -> Option<serde_json::Value>,
            try_rlm_json as fn(&str) -> Option<serde_json::Value>,
        )
    } else {
        (
            try_rlm_json as fn(&str) -> Option<serde_json::Value>,
            try_rlm_edn as fn(&str) -> Option<serde_json::Value>,
        )
    };
    first(value).or_else(|| second(value))
}

fn try_rlm_json(value: &str) -> Option<serde_json::Value> {
    serde_json::from_str(value).ok()
}

fn try_rlm_edn(value: &str) -> Option<serde_json::Value> {
    by_contracts::parse_value(value)
        .ok()
        .map(|value| edn_value_to_json(&value))
}

fn split_rlm_lines_non_blank(value: &str) -> Vec<String> {
    value
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(ToString::to_string)
        .collect()
}

fn parse_rlm_json_or_edn(value: &str) -> Result<serde_json::Value> {
    if let Some(parsed) = try_rlm_json(value) {
        return Ok(parsed);
    }
    by_contracts::parse_value(value)
        .map(|value| edn_value_to_json(&value))
        .with_context(|| "not valid JSON or EDN")
}

fn normalize_rlm_key(value: &str) -> String {
    value.trim().trim_start_matches(':').to_string()
}

fn rlm_as_rows(
    value: &serde_json::Value,
) -> Option<Vec<serde_json::Map<String, serde_json::Value>>> {
    value.as_array().map(|items| {
        items
            .iter()
            .filter_map(|item| item.as_object().cloned())
            .collect::<Vec<_>>()
    })
}

fn rlm_map_get<'a>(
    map: &'a serde_json::Map<String, serde_json::Value>,
    key: &str,
) -> Option<&'a serde_json::Value> {
    if let Some(value) = map.get(key) {
        return Some(value);
    }
    let dash = key.replace('_', "-");
    if dash != key {
        if let Some(value) = map.get(&dash) {
            return Some(value);
        }
    }
    let underscore = key.replace('-', "_");
    if underscore != key {
        if let Some(value) = map.get(&underscore) {
            return Some(value);
        }
    }
    None
}

fn rlm_truthy_parse_failed(map: &serde_json::Map<String, serde_json::Value>) -> bool {
    rlm_map_get(map, "parse-failed").and_then(serde_json::Value::as_bool) == Some(true)
}

fn rlm_count_value(map: &serde_json::Map<String, serde_json::Value>, count_key: &str) -> f64 {
    match rlm_map_get(map, count_key) {
        Some(serde_json::Value::Number(value)) => value.as_f64().unwrap_or(1.0),
        Some(serde_json::Value::String(value)) => value.parse::<f64>().unwrap_or(1.0),
        Some(serde_json::Value::Null) | None => 1.0,
        _ => 1.0,
    }
}

fn rlm_group_key(map: &serde_json::Map<String, serde_json::Value>, key: &str) -> String {
    rlm_map_get(map, key)
        .and_then(json_scalar_string)
        .map(|value| normalize_rlm_key(&value))
        .filter(|value| !value.is_empty())
        .unwrap_or_else(|| "_unkeyed".to_string())
}

fn rlm_json_number(value: f64) -> serde_json::Value {
    if value.is_finite()
        && value.fract() == 0.0
        && value >= i64::MIN as f64
        && value <= i64::MAX as f64
    {
        serde_json::json!(value as i64)
    } else {
        serde_json::json!(value)
    }
}

#[derive(Clone, Debug)]
struct LogQueryOptions {
    log: Option<PathBuf>,
    user_id: Option<String>,
    session_id: Option<String>,
    agent_id: Option<String>,
    turn_id: Option<i64>,
    event_type: Option<String>,
    query: Option<String>,
    last_n: Option<usize>,
}

fn print_log_turns(
    log: Option<PathBuf>,
    user_id: Option<String>,
    session_id: Option<String>,
    agent_id: Option<String>,
) -> Result<()> {
    let path = resolve_log_path(log);
    let events = parse_app_log(&path);
    let mut by_turn: BTreeMap<i64, Vec<&by_contracts::EdnMap>> = BTreeMap::new();

    for event in &events {
        if !log_event_matches_identity(
            event,
            user_id.as_deref(),
            session_id.as_deref(),
            agent_id.as_deref(),
            None,
        ) {
            continue;
        }
        if let Some(turn_id) = edn_i64(event.get("turn-id")) {
            by_turn.entry(turn_id).or_default().push(event);
        }
    }

    let turns = by_turn
        .into_iter()
        .map(|(turn_id, events)| {
            let timestamps = events
                .iter()
                .filter_map(|event| edn_i64(event.get("mulog/timestamp")))
                .collect::<Vec<_>>();
            let mut categories = Vec::<String>::new();
            for event in &events {
                let category = log_event_category(event);
                if !categories.contains(&category) {
                    categories.push(category);
                }
            }

            serde_json::json!({
                "turn-id": turn_id,
                "event-count": events.len(),
                "first-ts": timestamps.iter().min().copied(),
                "last-ts": timestamps.iter().max().copied(),
                "categories": categories,
            })
        })
        .collect::<Vec<_>>();

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({ "turns": turns }))?
    );
    Ok(())
}

fn print_log_events(options: LogQueryOptions) -> Result<()> {
    let path = resolve_log_path(options.log);
    let mut events = parse_app_log(&path)
        .into_iter()
        .filter(|event| {
            log_event_matches_identity(
                event,
                options.user_id.as_deref(),
                options.session_id.as_deref(),
                options.agent_id.as_deref(),
                options.turn_id,
            )
        })
        .filter(|event| {
            options.event_type.as_deref().is_none_or(|event_type| {
                log_event_category(event) == normalize_log_category_filter(event_type)
            })
        })
        .filter(|event| {
            options
                .query
                .as_deref()
                .is_none_or(|query| log_event_matches_text(event, query))
        })
        .map(|event| summarize_log_event(&event))
        .collect::<Vec<_>>();

    if let Some(last_n) = options.last_n {
        if events.len() > last_n {
            events = events.split_off(events.len() - last_n);
        }
    }

    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({ "events": events }))?
    );
    Ok(())
}

fn resolve_log_path(log: Option<PathBuf>) -> PathBuf {
    if let Some(log) = log {
        return log;
    }

    process_dirs()
        .and_then(|dirs| {
            dirs.user_dir
                .map(|user_dir| user_dir.join(".brainyard/logs/agent-tui-app.log"))
        })
        .unwrap_or_else(|| PathBuf::from("/tmp/agent-tui-app.log"))
}

fn parse_app_log(path: &Path) -> Vec<by_contracts::EdnMap> {
    let Ok(content) = std::fs::read_to_string(path) else {
        return Vec::new();
    };

    content
        .split("\n\n")
        .filter(|block| !block.trim().is_empty())
        .filter_map(|block| match by_contracts::parse_value(block) {
            Ok(by_contracts::EdnValue::Map(map)) => Some(map),
            _ => None,
        })
        .collect()
}

fn log_event_matches_identity(
    event: &by_contracts::EdnMap,
    user_id: Option<&str>,
    session_id: Option<&str>,
    agent_id: Option<&str>,
    turn_id: Option<i64>,
) -> bool {
    user_id
        .is_none_or(|expected| edn_filter_text(event.get("user-id")).as_deref() == Some(expected))
        && session_id.is_none_or(|expected| {
            edn_filter_text(event.get("session-id")).as_deref() == Some(expected)
        })
        && agent_id.is_none_or(|expected| {
            edn_filter_text(event.get("agent-id")).as_deref() == Some(expected)
        })
        && turn_id.is_none_or(|expected| edn_i64(event.get("turn-id")) == Some(expected))
}

fn log_event_category(event: &by_contracts::EdnMap) -> String {
    let event_name =
        edn_name_text(event.get("mulog/event-name")).unwrap_or_else(|| "unknown".to_string());
    for (suffix, category) in [
        ("coact-init", "turn-start"),
        ("store-results", "turn-complete"),
        ("task-execution", "task"),
        ("agent-conversation", "conversation"),
    ] {
        if event_name.ends_with(suffix) {
            return category.to_string();
        }
    }
    event_name
}

fn normalize_log_category_filter(value: &str) -> String {
    value
        .trim()
        .trim_start_matches(':')
        .rsplit_once('/')
        .map(|(_, name)| name)
        .unwrap_or_else(|| value.trim().trim_start_matches(':'))
        .to_string()
}

fn log_event_matches_text(event: &by_contracts::EdnMap, query: &str) -> bool {
    let query = query.to_ascii_lowercase();
    event.iter().any(|(_key, value)| {
        edn_search_text(value).is_some_and(|text| text.to_ascii_lowercase().contains(&query))
    })
}

fn summarize_log_event(event: &by_contracts::EdnMap) -> serde_json::Value {
    let category = log_event_category(event);
    let mut summary = serde_json::Map::new();
    summary.insert("category".to_string(), serde_json::json!(category));
    summary.insert(
        "timestamp".to_string(),
        event
            .get("mulog/timestamp")
            .map(edn_value_to_json)
            .unwrap_or(serde_json::Value::Null),
    );
    summary.insert(
        "agent-id".to_string(),
        event
            .get("agent-id")
            .map(edn_value_to_json)
            .unwrap_or(serde_json::Value::Null),
    );
    summary.insert(
        "turn-id".to_string(),
        event
            .get("turn-id")
            .map(edn_value_to_json)
            .unwrap_or(serde_json::Value::Null),
    );

    match category.as_str() {
        "turn-start" => {
            insert_edn_json(&mut summary, event, "total-turns");
            insert_renamed_edn_json(
                &mut summary,
                event,
                "previous-turns-count",
                "previous-turns",
            );
            insert_renamed_edn_json(&mut summary, event, "system-context-chars", "system-chars");
            insert_renamed_edn_json(&mut summary, event, "user-context-chars", "user-chars");
            insert_edn_json(&mut summary, event, "budget-tokens");
        }
        "turn-complete" => {
            insert_edn_json(&mut summary, event, "total-iterations");
            insert_edn_json(&mut summary, event, "terminated-by");
            insert_edn_json(&mut summary, event, "answer-length");
        }
        "task" => {
            insert_edn_json(&mut summary, event, "task-id");
            insert_edn_json(&mut summary, event, "task-name");
            insert_edn_json(&mut summary, event, "status");
            insert_edn_json(&mut summary, event, "duration-ms");
        }
        "conversation" => {
            let request = truncate_chars(&edn_display_text(event.get("request")), 120);
            let reply_length = edn_display_text(event.get("reply")).chars().count();
            summary.insert("request".to_string(), serde_json::json!(request));
            summary.insert("reply-length".to_string(), serde_json::json!(reply_length));
        }
        _ => {
            summary.insert(
                "event-name".to_string(),
                serde_json::json!(edn_name_text(event.get("mulog/event-name"))
                    .unwrap_or_else(|| "unknown".to_string())),
            );
            summary.insert(
                "keys".to_string(),
                serde_json::json!(event
                    .iter()
                    .map(|(key, _value)| key.as_str())
                    .filter(|key| !key.starts_with("mulog/"))
                    .collect::<Vec<_>>()),
            );
        }
    }

    serde_json::Value::Object(summary)
}

fn insert_edn_json(
    output: &mut serde_json::Map<String, serde_json::Value>,
    event: &by_contracts::EdnMap,
    key: &str,
) {
    insert_renamed_edn_json(output, event, key, key);
}

fn insert_renamed_edn_json(
    output: &mut serde_json::Map<String, serde_json::Value>,
    event: &by_contracts::EdnMap,
    source_key: &str,
    output_key: &str,
) {
    output.insert(
        output_key.to_string(),
        event
            .get(source_key)
            .map(edn_value_to_json)
            .unwrap_or(serde_json::Value::Null),
    );
}

