fn print_ansi_style(text: String, codes_json: String, no_color: bool) -> Result<()> {
    let code_names = parse_ansi_codes_arg(&codes_json)?;
    let mut codes = Vec::with_capacity(code_names.len());
    let mut unknown = Vec::new();
    for name in &code_names {
        match by_tui::ansi_code(name) {
            Some(code) => codes.push(code),
            None => unknown.push(name.clone()),
        }
    }
    if !unknown.is_empty() {
        bail!("unknown ANSI code(s): {}", unknown.join(", "));
    }
    let output = serde_json::json!({
        "projection": "tui.ansi/style",
        "color-enabled?": !no_color,
        "codes": code_names,
        "rendered": by_tui::ansi_style(&text, &codes, !no_color),
    });
    println!("{}", serde_json::to_string_pretty(&output)?);
    Ok(())
}

