fn parse_ansi_codes_arg(value: &str) -> Result<Vec<String>> {
    let parsed = parse_rlm_json_or_edn(value).context("failed to parse --codes-json")?;
    let Some(items) = parsed.as_array() else {
        bail!("--codes-json must be a JSON or EDN vector");
    };
    Ok(items
        .iter()
        .filter_map(|item| item.as_str().map(ToString::to_string))
        .collect())
}

fn parse_tui_format_todo_items_arg(value: &str) -> Result<Vec<by_tui::TodoItem>> {
    let parsed = parse_rlm_json_or_edn(value).context("failed to parse --items-json")?;
    let Some(items) = parsed.as_array() else {
        bail!("--items-json must be a JSON or EDN vector");
    };

    items
        .iter()
        .enumerate()
        .map(|(index, item)| {
            let Some(map) = item.as_object() else {
                bail!("--items-json item {} must be an object", index);
            };
            Ok(by_tui::TodoItem {
                description: tui_format_string_field(
                    map,
                    &["description", "desc", "text", "title"],
                )
                .unwrap_or_default(),
                done: tui_format_bool_field(
                    map,
                    &["done", "done?", "completed", "completed?", "status"],
                )
                .unwrap_or(false),
                result: tui_format_string_field(map, &["result", "summary", "output"]),
                independent: tui_format_bool_field(
                    map,
                    &["independent", "independent?", "parallel", "parallel?"],
                )
                .unwrap_or(false),
            })
        })
        .collect()
}

fn parse_tui_format_usage_summary_arg(value: &str) -> Result<by_tui::UsageSummary> {
    let parsed = parse_rlm_json_or_edn(value).context("failed to parse --usage-json")?;
    let Some(root) = parsed.as_object() else {
        bail!("--usage-json must be a JSON or EDN map");
    };
    let totals = tui_format_value_field(root, &["totals"])
        .and_then(serde_json::Value::as_object)
        .unwrap_or(root);
    let input_tokens =
        tui_format_i64_field(totals, &["input-tokens", "total-input-tokens"]).unwrap_or(0);
    let output_tokens =
        tui_format_i64_field(totals, &["output-tokens", "total-output-tokens"]).unwrap_or(0);
    Ok(by_tui::UsageSummary {
        calls: tui_format_i64_field(totals, &["call-count", "total-calls", "calls"]).unwrap_or(0),
        tokens: tui_format_i64_field(totals, &["total-tokens", "tokens"])
            .unwrap_or(input_tokens + output_tokens),
        cost: tui_format_f64_field(totals, &["total-cost", "cost"]).unwrap_or(0.0),
    })
}

fn parse_tui_format_usage_table_arg(value: &str) -> Result<Vec<by_tui::UsageCall>> {
    let parsed = parse_rlm_json_or_edn(value).context("failed to parse --history-json")?;
    let Some(items) = parsed.as_array() else {
        bail!("--history-json must be a JSON or EDN vector");
    };
    items
        .iter()
        .enumerate()
        .map(|(index, item)| {
            let Some(map) = item.as_object() else {
                bail!("--history-json item {} must be an object", index);
            };
            let cache =
                tui_format_value_field(map, &["cache"]).and_then(serde_json::Value::as_object);
            let cost =
                tui_format_value_field(map, &["cost"]).and_then(serde_json::Value::as_object);
            let input_token_breakdown =
                tui_format_value_field(map, &["input-token-breakdown", "input_token_breakdown"])
                    .and_then(serde_json::Value::as_object)
                    .map(parse_tui_format_usage_breakdown);
            Ok(by_tui::UsageCall {
                latency_ms: tui_format_i64_field(map, &["latency-ms", "latency_ms", "latency"]),
                input_tokens: tui_format_i64_field(map, &["input-tokens", "input_tokens"])
                    .unwrap_or(0),
                output_tokens: tui_format_i64_field(map, &["output-tokens", "output_tokens"])
                    .unwrap_or(0),
                cache_read_tokens: cache
                    .and_then(|cache| {
                        tui_format_i64_field(cache, &["read-tokens", "read_tokens", "cache-read"])
                    })
                    .unwrap_or(0),
                cache_write_tokens: cache
                    .and_then(|cache| {
                        tui_format_i64_field(
                            cache,
                            &["write-tokens", "write_tokens", "cache-write"],
                        )
                    })
                    .unwrap_or(0),
                total_cost: cost
                    .and_then(|cost| tui_format_f64_field(cost, &["total-cost", "total_cost"]))
                    .or_else(|| tui_format_f64_field(map, &["total-cost", "total_cost", "cost"]))
                    .unwrap_or(0.0),
                turn_id: tui_format_string_field(map, &["turn-id", "turn_id"]),
                iteration: tui_format_string_field(map, &["iteration", "iter"]),
                provider: tui_format_string_field(map, &["provider"]),
                model: tui_format_string_field(map, &["model"]),
                agent_instance_id: tui_format_string_field(
                    map,
                    &[
                        "agent-instance-id",
                        "agent_instance_id",
                        "agent-id",
                        "agent_id",
                    ],
                ),
                input_token_breakdown,
            })
        })
        .collect()
}

fn parse_tui_format_usage_breakdown(
    map: &serde_json::Map<String, serde_json::Value>,
) -> by_tui::UsageInputTokenBreakdown {
    by_tui::UsageInputTokenBreakdown {
        system_prompt: tui_format_usage_token_group(map, &["system-prompt", "system_prompt"]),
        dspy_signature: tui_format_usage_token_group(map, &["dspy-signature", "dspy_signature"]),
        user_message: tui_format_usage_token_group(map, &["user-message", "user_message"]),
        system_context: tui_format_usage_token_group(map, &["system-context", "system_context"]),
    }
}

fn tui_format_usage_token_group(
    map: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> by_tui::UsageTokenGroup {
    let Some(group) = tui_format_value_field(map, keys).and_then(serde_json::Value::as_object)
    else {
        return by_tui::UsageTokenGroup::default();
    };
    let parts = tui_format_value_field(group, &["parts"])
        .and_then(serde_json::Value::as_object)
        .map(|parts| {
            parts
                .iter()
                .map(|(name, value)| {
                    let estimated_tokens = value
                        .as_object()
                        .and_then(|part| {
                            tui_format_i64_field(
                                part,
                                &["estimated-tokens", "estimated_tokens", "tokens"],
                            )
                        })
                        .or_else(|| tui_format_json_to_i64(value))
                        .unwrap_or(0);
                    by_tui::UsageTokenPart {
                        name: normalize_tui_format_map_key(name),
                        estimated_tokens,
                    }
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    by_tui::UsageTokenGroup {
        estimated_tokens: tui_format_i64_field(
            group,
            &["estimated-tokens", "estimated_tokens", "tokens"],
        )
        .unwrap_or(0),
        parts,
    }
}

