fn parse_tui_format_tool_arguments(value: &serde_json::Value) -> Result<Vec<by_tui::ToolArgument>> {
    match value {
        serde_json::Value::Array(items) => items
            .iter()
            .enumerate()
            .map(|(index, item)| {
                let Some(map) = item.as_object() else {
                    bail!("tool-args item {} must be an object", index);
                };
                let value = tui_format_value_field(map, &["value", "val"])
                    .map(tui_format_value_pr_str)
                    .unwrap_or_else(|| "nil".to_string());
                Ok(by_tui::ToolArgument {
                    name: tui_format_string_field(map, &["name", "key", "arg"])
                        .unwrap_or_else(|| index.to_string()),
                    value,
                })
            })
            .collect(),
        serde_json::Value::Object(map) => Ok(map
            .iter()
            .map(|(name, value)| by_tui::ToolArgument {
                name: normalize_tui_format_map_key(name),
                value: tui_format_value_pr_str(value),
            })
            .collect()),
        serde_json::Value::Null => Ok(Vec::new()),
        _ => bail!("tool-args must be a JSON/EDN vector or map"),
    }
}

