fn tui_format_value_field<'a>(
    map: &'a serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<&'a serde_json::Value> {
    keys.iter().find_map(|key| {
        rlm_map_get(map, key).or_else(|| {
            let normalized = key.trim_start_matches(':');
            let colon_key = format!(":{normalized}");
            rlm_map_get(map, &colon_key)
        })
    })
}

fn tui_format_string_field(
    map: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<String> {
    tui_format_value_field(map, keys).and_then(json_scalar_string)
}

fn tui_format_bool_field(
    map: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<bool> {
    tui_format_value_field(map, keys).and_then(tui_format_json_to_bool)
}

fn tui_format_i64_field(
    map: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<i64> {
    tui_format_value_field(map, keys).and_then(tui_format_json_to_i64)
}

fn tui_format_f64_field(
    map: &serde_json::Map<String, serde_json::Value>,
    keys: &[&str],
) -> Option<f64> {
    tui_format_value_field(map, keys).and_then(rlm_json_to_f64)
}

fn tui_format_json_to_bool(value: &serde_json::Value) -> Option<bool> {
    match value {
        serde_json::Value::Bool(value) => Some(*value),
        serde_json::Value::Number(value) => value.as_i64().map(|value| value != 0),
        serde_json::Value::String(value) => {
            match value
                .trim()
                .trim_start_matches(':')
                .replace('_', "-")
                .to_ascii_lowercase()
                .as_str()
            {
                "" | "false" | "no" | "n" | "0" | "nil" | "none" | "todo" | "pending"
                | "incomplete" | "not-done" | "open" => Some(false),
                "true" | "yes" | "y" | "1" | "done" | "completed" | "complete" | "closed"
                | "achieved" => Some(true),
                _ => None,
            }
        }
        serde_json::Value::Null => Some(false),
        _ => None,
    }
}

fn tui_format_json_to_i64(value: &serde_json::Value) -> Option<i64> {
    match value {
        serde_json::Value::Number(value) => value.as_i64().or_else(|| {
            value
                .as_f64()
                .filter(|value| value.is_finite())
                .map(|value| value.trunc() as i64)
        }),
        serde_json::Value::String(value) => value.parse::<i64>().ok(),
        _ => None,
    }
}

fn tui_format_value_display(value: &serde_json::Value) -> String {
    json_scalar_string(value)
        .unwrap_or_else(|| serde_json::to_string(value).unwrap_or_else(|_| value.to_string()))
}

fn tui_format_value_pr_str(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => "nil".to_string(),
        serde_json::Value::String(value) => {
            serde_json::to_string(value).unwrap_or_else(|_| format!("{value:?}"))
        }
        serde_json::Value::Bool(value) => value.to_string(),
        serde_json::Value::Number(value) => value.to_string(),
        serde_json::Value::Array(_) | serde_json::Value::Object(_) => {
            serde_json::to_string(value).unwrap_or_else(|_| value.to_string())
        }
    }
}

fn tui_format_mulog_fallback_pairs(
    map: &serde_json::Map<String, serde_json::Value>,
) -> Vec<(String, String)> {
    const SKIP_KEYS: &[&str] = &[
        "messages",
        "response-text",
        "eval-results",
        "usage",
        "body",
        "request",
        "response",
    ];

    map.iter()
        .filter(|(key, _)| {
            let trimmed = key.trim().trim_start_matches(':');
            if trimmed.starts_with("mulog/") {
                return false;
            }
            let normalized = trimmed.replace('_', "-");
            !SKIP_KEYS.iter().any(|skip| normalized == *skip)
        })
        .take(4)
        .map(|(key, value)| {
            let mut rendered = tui_format_value_pr_str(value);
            if rendered.chars().count() > 60 {
                let cut = rendered
                    .char_indices()
                    .nth(60)
                    .map(|(idx, _)| idx)
                    .unwrap_or(rendered.len());
                rendered.truncate(cut);
                rendered.push_str("...");
            }
            (normalize_tui_format_map_key(key), rendered)
        })
        .collect()
}

fn normalize_tui_format_map_key(value: &str) -> String {
    value
        .trim()
        .trim_start_matches(':')
        .rsplit_once('/')
        .map(|(_, name)| name)
        .unwrap_or_else(|| value.trim().trim_start_matches(':'))
        .to_string()
}

#[derive(Clone, Debug)]
struct TaskFormatTransitionOptions {
    task_id: String,
    name: String,
    status: String,
    prev_status: String,
    started_at: Option<i64>,
    completed_at: Option<i64>,
    error: Option<String>,
    now_ms: Option<i64>,
}

fn print_task_format_elapsed(
    started_at: i64,
    completed_at: Option<i64>,
    now_ms: Option<i64>,
) -> Result<()> {
    let elapsed = task_format_elapsed_str(Some(started_at), completed_at, now_ms);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "task.format/elapsed-str",
            "elapsed": elapsed,
        }))?
    );
    Ok(())
}

fn print_task_format_list(tasks_json: String, now_ms: Option<i64>) -> Result<()> {
    let mut tasks = parse_task_format_tasks_json(&tasks_json)?;
    tasks.sort_by(|left, right| {
        task_format_i64_field(left, "created-at")
            .unwrap_or(i64::MAX)
            .cmp(&task_format_i64_field(right, "created-at").unwrap_or(i64::MAX))
            .then_with(|| {
                task_format_string_field(left, "id")
                    .unwrap_or_default()
                    .cmp(&task_format_string_field(right, "id").unwrap_or_default())
            })
    });
    let rendered = task_format_list_rendered(&tasks, now_ms);
    let rows = tasks
        .iter()
        .map(|task| task_format_list_row(task, now_ms))
        .collect::<Vec<_>>();
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "task.format/format-task-list",
            "task-count": tasks.len(),
            "rows": rows,
            "rendered": rendered,
        }))?
    );
    Ok(())
}

fn print_task_format_detail(task_json: String, now_ms: Option<i64>) -> Result<()> {
    let task = serde_json::from_str::<serde_json::Value>(&task_json)
        .context("failed to parse --task-json JSON")?;
    if !task.is_object() {
        bail!("--task-json must be a JSON object");
    }
    let rendered = task_format_detail_rendered(&task, now_ms);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "task.format/format-task-detail",
            "rendered": rendered,
        }))?
    );
    Ok(())
}

fn print_task_format_output(
    task_id: String,
    lines_json: String,
    last_n: Option<usize>,
) -> Result<()> {
    let all_lines = parse_task_format_lines_json(&lines_json)?;
    let total = all_lines.len();
    let lines = if let Some(last_n) = last_n.filter(|value| *value > 0) {
        let start = all_lines.len().saturating_sub(last_n);
        all_lines[start..].to_vec()
    } else {
        all_lines.clone()
    };
    let rendered = task_format_output_rendered(&task_id, &all_lines, last_n);
    println!(
        "{}",
        serde_json::to_string_pretty(&serde_json::json!({
            "projection": "task.format/format-task-output",
            "task-id": task_id,
            "total-lines": total,
            "showing": lines.len(),
            "lines": lines,
            "rendered": rendered,
        }))?
    );
    Ok(())
}

