fn run_help_args(args: &str) -> bool {
    matches!(
        args.split_whitespace().next(),
        Some("help" | "--help" | "-h")
    )
}

fn run_init_show_args(args: &str) -> bool {
    matches!(args.split_whitespace().next(), Some("show" | "read"))
}

fn run_init_list_snapshots_args(args: &str) -> bool {
    matches!(args.split_whitespace().next(), Some("list-snapshots"))
}

fn run_init_revert_missing_args(args: &str) -> bool {
    let mut tokens = args.split_whitespace();
    matches!(tokens.next(), Some("revert")) && tokens.next().is_none()
}

fn run_init_revert_snapshot_arg(args: &str) -> Option<&str> {
    let trimmed = args.trim_start();
    let rest = trimmed.strip_prefix("revert")?;
    if !rest
        .chars()
        .next()
        .is_some_and(|character| character.is_whitespace())
    {
        return None;
    }
    let snapshot_path = rest.trim();
    (!snapshot_path.is_empty()).then_some(snapshot_path)
}

