fn render_run_init_revert(args: &str) -> Result<String> {
    let Some(snapshot_path) = run_init_revert_snapshot_arg(args) else {
        return Ok(run_init_revert_error_edn(
            "Provide :snapshot-path, or (:scope + :steps).",
        ));
    };
    let dirs = init_doc_dirs(None, None)?;
    let chosen = match init_doc_find_snapshot(&dirs, Some(Path::new(snapshot_path)), None, None)? {
        Ok(record) => record,
        Err(error) if error.starts_with("Snapshot not found:") => {
            return Ok(run_init_revert_lookup_error_edn(&error));
        }
        Err(error) => return Ok(run_init_revert_error_edn(&error)),
    };
    let Some(base) = init_doc_scope_dir(&dirs, &chosen.scope) else {
        return Ok(run_init_revert_error_edn(&format!(
            "No .brainyard/ dir for scope {}",
            chosen.scope
        )));
    };
    let dest = match init_doc_brainyard_file(&dirs, &chosen.scope) {
        Some(path) => path,
        None => {
            return Ok(run_init_revert_error_edn(&format!(
                "No target file path for scope {}",
                chosen.scope
            )));
        }
    };
    let pre_snapshot = match init_doc_take_snapshot(
        &base,
        &chosen.scope,
        &format!(
            "revert-to-{}",
            if chosen.reason.is_empty() {
                "snapshot"
            } else {
                &chosen.reason
            }
        ),
        &dirs,
    )? {
        Ok(path) => path,
        Err(error) => {
            return Ok(run_init_revert_error_edn(&format!(
                "Pre-revert snapshot failed: {error}"
            )));
        }
    };
    if let Some(parent) = dest.parent() {
        std::fs::create_dir_all(parent)
            .with_context(|| format!("failed to create {}", parent.display()))?;
    }
    std::fs::copy(&chosen.path, &dest).with_context(|| {
        format!(
            "failed to restore {} to {}",
            chosen.path.display(),
            dest.display()
        )
    })?;
    Ok(format!(
        "{{:ok? true,\n :scope :{},\n :restored-from\n {},\n :pre-revert-snapshot\n {},\n :dest\n {}}}\n",
        chosen.scope,
        edn_quote_string(&chosen.path.display().to_string()),
        edn_quote_string(&pre_snapshot.display().to_string()),
        edn_quote_string(&dest.display().to_string())
    ))
}

fn init_doc_take_snapshot(
    base: &Path,
    scope: &str,
    reason: &str,
    dirs: &InitDocDirs,
) -> Result<std::result::Result<PathBuf, String>> {
    let Some(file) = init_doc_brainyard_file(dirs, scope) else {
        return Ok(Err(format!("No .brainyard/ dir for scope {scope}")));
    };
    let snapshot_dir = init_doc_snapshot_dir(base);
    std::fs::create_dir_all(&snapshot_dir)
        .with_context(|| format!("failed to create {}", snapshot_dir.display()))?;
    let out = snapshot_dir.join(init_doc_snapshot_filename(
        &init_doc_now_ts(),
        scope,
        reason,
    ));
    if file.is_file() {
        std::fs::copy(&file, &out).with_context(|| {
            format!("failed to snapshot {} to {}", file.display(), out.display())
        })?;
    } else {
        std::fs::write(&out, "")
            .with_context(|| format!("failed to write empty snapshot {}", out.display()))?;
    }
    Ok(Ok(out))
}

fn run_init_revert_error_edn(error: &str) -> String {
    format!("{{:ok? false, :error {}}}\n", edn_quote_string(error))
}

fn run_init_revert_lookup_error_edn(error: &str) -> String {
    format!("{{:error {}}}\n", edn_quote_string(error))
}

fn edn_quote_string(value: &str) -> String {
    serde_json::to_string(value).expect("serializing a string to JSON cannot fail")
}

fn run_static_slash_command_block(input: &str) -> Option<&'static str> {
    match input {
        "/clear" => Some(RUN_CLEAR_BLOCK),
        "/help" => Some(RUN_HELP_BLOCK),
        "/history" => Some(RUN_HISTORY_BLOCK),
        "/queue" => Some(RUN_QUEUE_BLOCK),
        "/todo" => Some(RUN_TODO_BLOCK),
        "/usage" => Some(RUN_USAGE_BLOCK),
        "/verbose" => Some(RUN_VERBOSE_BLOCK),
        _ => None,
    }
}

fn split_run_slash_input(input: &str) -> (&str, &str) {
    let mut parts = input.splitn(2, char::is_whitespace);
    let command = parts.next().unwrap_or_default();
    let args = parts.next().unwrap_or_default().trim();
    (command, args)
}

fn print_run_command_header(input: &str) {
    println!("\n\x1b[1m\x1b[2m> {}\x1b[0m", input);
}

fn print_run_static_slash_command(input: &str, block: &str) {
    print_run_command_header(input);
    print!("{block}");
    if !block.is_empty() && !block.ends_with('\n') {
        println!();
    }
}

fn print_run_muted_line(line: &str) {
    println!("\x1b[2m{}\x1b[0m", line);
}

fn print_run_warning_line(line: &str) {
    println!("\x1b[1;93m{}\x1b[0m", line);
}

fn print_run_success_line(line: &str) {
    println!("\x1b[1;92m{}\x1b[0m", line);
}

fn run_usage_args_are_valid(args: &str) -> bool {
    let mut n_token: Option<&str> = None;
    for token in args.split_whitespace() {
        if token == "--breakdown" {
            continue;
        }
        if n_token.is_none() {
            n_token = Some(token);
        }
    }

    match n_token {
        Some(token) => token.parse::<u64>().is_ok_and(|n| n > 0),
        None => true,
    }
}

fn print_run_usage_slash_command(input: &str, args: &str) {
    print_run_command_header(input);
    if run_usage_args_are_valid(args) {
        print_run_muted_line("0 calls │ 0 tokens │ $0.0000");
    } else {
        print_run_warning_line("Usage: /usage [N] [--breakdown]");
    }
}

fn print_run_verbose_slash_command(input: &str, args: &str, verbosity: &mut &'static str) {
    print_run_command_header(input);
    if args.is_empty() {
        print_run_muted_line(&format!("Verbosity: {}", verbosity));
        return;
    }

    match args {
        "quiet" => {
            *verbosity = "quiet";
            print_run_muted_line(&format!("Verbosity: {}", verbosity));
        }
        "normal" => {
            *verbosity = "normal";
            print_run_muted_line(&format!("Verbosity: {}", verbosity));
        }
        "verbose" => {
            *verbosity = "verbose";
            print_run_muted_line(&format!("Verbosity: {}", verbosity));
        }
        _ => print_run_warning_line(&format!(
            "Invalid level: {}. Use quiet, normal, or verbose.",
            args
        )),
    }
}

fn print_run_effort_slash_command(input: &str, args: &str, effort: &mut &'static str) {
    print_run_command_header(input);
    if args.is_empty() {
        println!(
            "  effort = \x1b[1m\x1b[96m{}\x1b[0m\x1b[2m  (low | medium | high)\x1b[0m",
            effort
        );
        return;
    }

    match args {
        "low" => {
            *effort = "low";
            print_run_success_line(
                "effort = low  (enable-finalize-answer=false, max-refinements=0)",
            );
        }
        "medium" => {
            *effort = "medium";
            print_run_success_line(
                "effort = medium  (enable-finalize-answer=true, max-refinements=0)",
            );
        }
        "high" => {
            *effort = "high";
            print_run_success_line(
                "effort = high  (enable-finalize-answer=true, max-refinements=2)",
            );
        }
        _ => print_run_warning_line(&format!(
            "Unknown effort level: {}. Valid: low, medium, high",
            args
        )),
    }
}

